"use strict";(self.webpackChunktuyaopen_io_website=self.webpackChunktuyaopen_io_website||[]).push([["6046"],{11592(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/HackStorm-Hackathon-2026","metadata":{"permalink":"/ko/blog/HackStorm-Hackathon-2026","editUrl":"https://github.com/Tuya-Community/TuyaOpen.io/edit/master/i18n/ko/docusaurus-plugin-content-blog/2025-12-19-2026-hackstorm-hackathon.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2025-12-19-2026-hackstorm-hackathon.md","title":"HackStorm Hackathon 2026","description":"Tuya\uB294 HackStorm AI + IoT Hackathon//www.hackstorm.ai/)\uC5D0 \uACF5\uB3D9 \uC8FC\uCD5C\uC790\uC774\uC790 \uD575\uC2EC \uAE30\uC220 \uD6C4\uC6D0\uC0AC\uB85C \uCC38\uC5EC\uD558\uAC8C \uB418\uC5B4 \uAE30\uC069\uB2C8\uB2E4.","date":"2025-12-19T00:00:00.000Z","tags":[{"inline":false,"label":"TuyaOpen","permalink":"/ko/blog/tags/TuyaOpen","description":"TuyaOpen \uD50C\uB7AB\uD3FC \uBC0F \uAC1C\uBC1C \uAD00\uB828 \uCF58\uD150\uCE20"},{"inline":false,"label":"\uB300\uD68C","permalink":"/ko/blog/tags/Contest","description":"\uAC1C\uBC1C\uC790 \uB300\uD68C \uBC0F \uD574\uCEE4\uD1A4"}],"readingTime":1.75,"hasTruncateMarker":true,"authors":[{"name":"Tuya","title":"TuyaOpen \uBAA8\uB4E0 \uC720\uC9C0\uAD00\uB9AC\uC790","url":"https://github.com/tuya/tuya-open","socials":{"github":"https://github.com/tuya","youtube":"https://youtube.com/@tuyasmart5602","website":"https://tuyaopen.ai"},"imageURL":"https://avatars.githubusercontent.com/u/73523937?v=4","key":"tuya","page":null}],"frontMatter":{"slug":"/HackStorm-Hackathon-2026","title":"HackStorm Hackathon 2026","authors":["tuya"],"image":"/img/home/tuyaopen-logo-social-preview.png","tags":["TuyaOpen","Contest"]},"unlisted":false,"nextItem":{"title":"Tuya AI Innovators Hackathon 2025","permalink":"/ko/blog/2025-tuya-ai-innovatores-hackathon"}},"content":"Tuya\uB294 **HackStorm AI + IoT Hackathon: Makers Gathering**(https://www.hackstorm.ai/)\uC5D0 **\uACF5\uB3D9 \uC8FC\uCD5C\uC790\uC774\uC790 \uD575\uC2EC \uAE30\uC220 \uD6C4\uC6D0\uC0AC**\uB85C \uCC38\uC5EC\uD558\uAC8C \uB418\uC5B4 \uAE30\uC069\uB2C8\uB2E4.\\n\\n{/* truncate */}\\n\\n<img src=\\"https://images.tuyacn.com/fe-static/docs/img/74b29c86-a93b-4de4-8001-84ac3a20965b.jpg\\" alt=\\"banner\\" width=\\"1300\\" />\\n\\n\uAE00\uB85C\uBC8C IoT \uD50C\uB7AB\uD3FC \uC81C\uACF5\uC5C5\uCCB4\uC778 Tuya\uB294 \uAC1C\uBC1C\uC790\uAC00 AI \uC544\uC774\uB514\uC5B4\uB97C \uC2E4\uC81C \uC2A4\uB9C8\uD2B8 \uB514\uBC14\uC774\uC2A4\uB85C \uAD6C\uD604\uD560 \uC218 \uC788\uB3C4\uB85D \uC9C0\uC6D0\uD569\uB2C8\uB2E4. [TuyaOpen](https://tuyaopen.ai/), \uACF5\uC2DD \uAC1C\uBC1C \uD558\uB4DC\uC6E8\uC5B4, \uD604\uC7A5 \uAE30\uC220 \uC9C0\uC6D0\uC744 \uD1B5\uD574 \uBA54\uC774\uCEE4\uAC00 \uC18C\uD504\uD2B8\uC6E8\uC5B4\uB9CC\uC73C\uB85C \uC9C4\uD589\uD558\uB294 \uD504\uB85C\uC81D\uD2B8\uB97C \uB118\uC5B4 \uC2E4\uC81C \uC81C\uD488\uC5D0 \uC9C0\uB2A5\uC744 \uAD6C\uD604\uD558\uB3C4\uB85D \uB3D5\uC2B5\uB2C8\uB2E4.\\n\\n\uC18C\uD504\uD2B8\uC6E8\uC5B4\uB9CC \uB9CC\uB4DC\uB294 \uD574\uCEE4\uD1A4\uC774 \uC9C0\uB8E8\uD558\uB2E4\uBA74 \uC774\uBC88 \uD589\uC0AC\uAC00 \uC801\uD569\uD569\uB2C8\uB2E4!  \\nTuya\uC758 IoT \uC778\uD504\uB77C\uC640 AI \uAE30\uB2A5\uC744 \uD65C\uC6A9\uD558\uBA74 \uAC1C\uBC1C\uC790\uB294 **\uAC10\uC9C0\uD558\uACE0, \uB9D0\uD558\uACE0, \uBC18\uC751\uD558\uB294** \uB514\uBC14\uC774\uC2A4\uB97C \uB9CC\uB4E4\uACE0 \uC2E4\uC81C \uC138\uACC4\uC5D0\uC11C **\uAC10\uC815\uC801\uC778 \uC5F0\uACB0**\uC744 \uB9CC\uB4E4\uC5B4 \uB0BC \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n\\n\\n### \u{1F381} \uC2B9\uC778\uB41C \uBA54\uC774\uCEE4\uC5D0\uAC8C Tuya\uAC00 \uC81C\uACF5\uD558\uB294 \uAC83\\n- AMOLED \uB514\uC2A4\uD50C\uB808\uC774, WiFi, Bluetooth\uAC00 \uD3EC\uD568\uB41C Tuya T5 E1 \uAC1C\uBC1C \uD0A4\uD2B8  \\n- USB Type-C \uCF00\uC774\uBE14  \\n- \uC678\uBD80 \uC2A4\uD53C\uCEE4  \\n- GPS \uBAA8\uB4C8  \\n- \uBE60\uB978 \uD504\uB85C\uD1A0\uD0C0\uC774\uD551\uACFC \uC9C0\uB2A5\uD615 \uC0C1\uD638 \uC791\uC6A9\uC744 \uC704\uD55C \uC124\uACC4  \\n\\n\\n\\n### \u{1F3C6} \uC0C1\uAE08\\n- **1\uC704**: $5,000  \\n- **2\uC704**: $3,000  \\n- **3\uC704**: $2,000  \\n- VC\u2019s Choice \uBC0F Visitors\u2019 Choice\uB97C \uD3EC\uD568\uD55C **\uCD94\uAC00 \uC218\uC0C1**  \\n\\n\\n\\n### \u{1F4CD} \uD589\uC0AC \uC815\uBCF4\\n- **\uC7A5\uC18C**: JJ Lake Business Center, 340 E Middlefield Rd, Mountain View, CA 94043  \\n- **\uC77C\uC2DC**: 2026\uB144 1\uC6D4 9\uC77C \uAE08\uC694\uC77C(\uC624\uD6C4 6\uC2DC) \u2192 1\uC6D4 11\uC77C \uC77C\uC694\uC77C(\uC624\uD6C4 8\uC2DC)  \\n- **\uBA54\uC774\uCEE4 \uB4F1\uB85D**: https://luma.com/qin89snk  \\n- **\uBC29\uBB38\uC790 \uB4F1\uB85D\uB9CC**: https://luma.com/qi4ta2jw  \\n- **\uD589\uC0AC \uC0C1\uC138 \uC815\uBCF4**: https://www.hackstorm.ai/  \\n\\n\\n\\n### \u{1F4A1} Tuya\uB85C \uB9CC\uB4E4 \uC218 \uC788\uB294 \uAC83\\n- AI \uBC18\uB824\uB3D9\uBB3C \uBC30\uC9C0  \\n- AI \uC74C\uC131 \uC2DC\uACC4(\uB9D0\uD558\uACE0, \uBC18\uC751\uD558\uACE0, \uCF54\uCE6D\uD558\uB294 \uC2DC\uACC4)  \\n- \uC810\uC131\uC220/\uC131\uACA9 \uC704\uC82F(\uAE30\uBD84 \uBC0F \uBD84\uC704\uAE30 \uD45C\uC2DC)  \\n- AI \uB3D9\uBC18\uC790 \uBC0F \uD45C\uD604\uD615 \uB514\uBC14\uC774\uC2A4(\uAC10\uC815, \uC560\uB2C8\uBA54\uC774\uC158, \uC74C\uC131)  \\n- \uAC1C\uC778\uD654\uB41C \uC9C0\uB2A5\uC744 \uAC16\uCD98 \uC2A4\uB9C8\uD2B8 \uBBF8\uB7EC/\uC2A4\uB9C8\uD2B8 \uB514\uC2A4\uD50C\uB808\uC774  \\n- \uC6E8\uC5B4\uB7EC\uBE14, AI \uC7A5\uB09C\uAC10, \uC570\uBE44\uC5B8\uD2B8 \uB514\uBC14\uC774\uC2A4 \uB4F1  \\n\\n\\n\\n### \u{1F9ED} \uC8FC\uC694 \uC77C\uC815\\n- **1\uC6D4 7~8\uC77C(\uC624\uD6C4 7~9\uC2DC)**: \uC628\uB77C\uC778 \uC6CC\uD06C\uC20D  \\n- **1\uC6D4 9\uC77C(\uC624\uD6C4 6~7\uC2DC)**: \uD300 \uBBF8\uD305 \uBC0F \uAD6C\uC131  \\n- **1\uC6D4 9\uC77C(\uC624\uD6C4 7~9\uC2DC)**: \uD604\uC7A5 \uC124\uC815 \uC6CC\uD06C\uC20D \uBC0F \uAE30\uC220 \uC9C0\uC6D0  \\n- **1\uC6D4 10\uC77C**: \uAC1C\uBC1C\uC758 \uB0A0  \\n- **1\uC6D4 11\uC77C(\uC624\uD6C4 3\uC2DC)**: \uC81C\uCD9C \uB9C8\uAC10 \u2192 \uB370\uBAA8, \uC2DC\uC0C1, \uB124\uD2B8\uC6CC\uD0B9  \\n\\n\\n\\n### \u{1F4AC} Tuya\uB85C \uBB34\uC5C7\uC744 \uB9CC\uB4E4\uACE0 \uC2F6\uC740\uC9C0 \uB313\uAE00\uB85C \uC54C\uB824 \uC8FC\uC138\uC694. \uADF8\uB9AC\uACE0 Tuya \uACF5\uC2DD \uAC1C\uBC1C\uC790 Discord \uCEE4\uBBA4\uB2C8\uD2F0\uC5D0 \uCC38\uC5EC\uD558\uC138\uC694.  \\n\uC804 \uC138\uACC4 AIoT \uBE4C\uB354\uC640 \uC5F0\uACB0\uD558\uACE0 \uD504\uB85C\uC81D\uD2B8 \uC544\uC774\uB514\uC5B4\uB97C \uAD50\uD658\uD558\uBA70 \uAE30\uC220 \uC9C0\uC6D0\uC744 \uBC1B\uACE0 HackStorm \uC18C\uC2DD\uC744 \uD655\uC778\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.  \\n\u{1F449} [discord.gg/yPPShSTttG](https://discord.gg/yPPShSTttG)\\n\\n#HackStorm #Tuya #AIoT #Hackathon #IoT #Hardware #Makers #GenerativeAI #BayArea"},{"id":"/2025-tuya-ai-innovatores-hackathon","metadata":{"permalink":"/ko/blog/2025-tuya-ai-innovatores-hackathon","editUrl":"https://github.com/Tuya-Community/TuyaOpen.io/edit/master/i18n/ko/docusaurus-plugin-content-blog/2025-11-13-2025-tuya-ces-hackathon.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2025-11-13-2025-tuya-ces-hackathon.md","title":"Tuya AI Innovators Hackathon 2025","description":"\uBE14\uB85D\uC744 \uC313\uB4EF \uC27D\uAC8C AI \uD558\uB4DC\uC6E8\uC5B4 \uB9CC\uB4E4\uAE30","date":"2025-11-13T00:00:00.000Z","tags":[{"inline":false,"label":"TuyaOpen","permalink":"/ko/blog/tags/TuyaOpen","description":"TuyaOpen \uD50C\uB7AB\uD3FC \uBC0F \uAC1C\uBC1C \uAD00\uB828 \uCF58\uD150\uCE20"},{"inline":false,"label":"\uB300\uD68C","permalink":"/ko/blog/tags/Contest","description":"\uAC1C\uBC1C\uC790 \uB300\uD68C \uBC0F \uD574\uCEE4\uD1A4"}],"readingTime":9.19,"hasTruncateMarker":true,"authors":[{"name":"Tuya","title":"TuyaOpen \uBAA8\uB4E0 \uC720\uC9C0\uAD00\uB9AC\uC790","url":"https://github.com/tuya/tuya-open","socials":{"github":"https://github.com/tuya","youtube":"https://youtube.com/@tuyasmart5602","website":"https://tuyaopen.ai"},"imageURL":"https://avatars.githubusercontent.com/u/73523937?v=4","key":"tuya","page":null}],"frontMatter":{"slug":"/2025-tuya-ai-innovatores-hackathon","title":"Tuya AI Innovators Hackathon 2025","authors":["tuya"],"image":"/img/home/tuyaopen-logo-social-preview.png","tags":["TuyaOpen","Contest"]},"unlisted":false,"prevItem":{"title":"HackStorm Hackathon 2026","permalink":"/ko/blog/HackStorm-Hackathon-2026"},"nextItem":{"title":"V1.5.0 \uB9B4\uB9AC\uC2A4","permalink":"/ko/blog/2025/09/22/v1.5.0-release"}},"content":"## \uBE14\uB85D\uC744 \uC313\uB4EF \uC27D\uAC8C AI \uD558\uB4DC\uC6E8\uC5B4 \uB9CC\uB4E4\uAE30\\n\\n\\n**AI\uB97C \uC704\uD574, \uD601\uC2E0\uC744 \uC704\uD574, \uBBF8\uB798\uB97C \uC704\uD574.**\\n\\n{/* truncate */}\\n\\n<img src=\\"https://images.tuyacn.com/rms-static/0561b9d0-c5f7-11f0-8d7c-0576ce46d19e-1763632518637.png?tyName=%E4%BC%81%E4%B8%9A%E5%BE%AE%E4%BF%A1%E6%88%AA%E5%9B%BE_b253474d-4a55-4447-a758-73f614cb6990.png\\" />\\n\\n**\uC9C0\uAE08 \uB4F1\uB85D\uD558\uAE30!:https://pages.tuya.com/develop/a83a0c8d834745ad801d** \\n\\n**QR \uCF54\uB4DC\uB97C \uC2A4\uCE94\uD574 Discord \uCEE4\uBBA4\uB2C8\uD2F0\uC5D0 \uCC38\uC5EC\uD558\uAC70\uB098 \uC544\uB798 \uB9C1\uD06C\uB97C \uD074\uB9AD\uD574 \uB4F1\uB85D\uD558\uACE0 \uC804 \uC138\uACC4 \uAC1C\uBC1C\uC790\uC640 \uC2E4\uC2DC\uAC04\uC73C\uB85C \uC5F0\uACB0\uD558\uC138\uC694!**\\n\\n<img src=\\"https://images.tuyacn.com/rms-static/09896aa0-bf8d-11f0-946a-f10d211a0860-1762927291978.png?tyName=111%E4%BC%81%E4%B8%9A%E5%BE%AE%E4%BF%A1%E6%88%AA%E5%9B%BE_6832ebee-7982-4fe0-8f05-eb170dbb9911.png\\" alt=\\"Discord \uCEE4\uBBA4\uB2C8\uD2F0 \uCC38\uC5EC \uBC0F \uB4F1\uB85D QR \uCF54\uB4DC\\" width=\\"150\\" />\\n\\n- Discord \uB9C1\uD06C: [https://discord.com/invite/yPPShSTttG](https://discord.com/invite/yPPShSTttG)\\n\\n\\n## 1. \uD589\uC0AC \uAC1C\uC694\\n \\n### Tuya Developer Platform \uC18C\uAC1C\\n\\nTuyaOpen(https://tuyaopen.ai/)\uC740 AI+IoT(Artificial Intelligence and Internet of Things) \uC0B0\uC5C5\uC744 \uC704\uD574 \uC124\uACC4\uB41C \uAC1C\uBC29\uD615 \uACF5\uB3D9 \uCC3D\uC791 \uAC1C\uBC1C \uD504\uB808\uC784\uC6CC\uD06C\uC785\uB2C8\uB2E4. \uC131\uC219\uD55C \uC0C1\uC6A9 IoT \uC6B4\uC601 \uCCB4\uC81C\uC778 TuyaOS\uB97C \uAE30\uBC18\uC73C\uB85C \uD558\uBA70 \uD06C\uB85C\uC2A4 \uD50C\uB7AB\uD3FC \uD638\uD658\uC131, \uBAA8\uB4C8\uC131, \uAC15\uB825\uD55C \uBCF4\uC548 \uC900\uC218 \uAE30\uB2A5\uC744 \uAC16\uCDA5\uB2C8\uB2E4. 1\uC5B5 \uB300\uAC00 \uB118\uB294 \uB514\uBC14\uC774\uC2A4 \uBC30\uD3EC\uC640 \uC218\uBC31\uB9CC \uBA85\uC758 \uAC1C\uBC1C\uC790\uB97C \uD1B5\uD574 \uAC80\uC99D\uB41C Tuya\uB294 \uD558\uB4DC\uC6E8\uC5B4, \uC18C\uD504\uD2B8\uC6E8\uC5B4, \uD074\uB77C\uC6B0\uB4DC \uC11C\uBE44\uC2A4\uB97C \uC544\uC6B0\uB974\uB294 \uD1B5\uD569 \uD601\uC2E0 \uD658\uACBD\uC744 \uC81C\uACF5\uD569\uB2C8\uB2E4.\\n\\n### \uD574\uCEE4\uD1A4 \uC18C\uAC1C\\n\\n\uC774 \uD574\uCEE4\uD1A4\uC740 Tuya Smart\uAC00 \uC8FC\uCD5C\uD558\uACE0 Amazon Web Services(AWS) Kiro\uAC00 \uACF5\uC2DD \uD074\uB77C\uC6B0\uB4DC \uD30C\uD2B8\uB108\uB85C \uCC38\uC5EC\uD569\uB2C8\uB2E4.\\n2026\uB144 1\uC6D4 CES \uAE30\uAC04\uC5D0 \uAC1C\uCD5C\uB418\uB294 \uC774 \uD589\uC0AC\uC758 \uACF5\uC2DD \uBA85\uCE6D\uC740 \u201CTuya AI Innovators Hackathon 2025: Build AI Hardware, As Easy As Stacking Blocks\u201D\uC785\uB2C8\uB2E4. \uC804 \uC138\uACC4 \uAC1C\uBC1C\uC790\uAC00 Tuya Open Platform\uC744 \uD65C\uC6A9\uD574 AI\uC640 IoT\uC758 \uAD50\uCC28 \uC601\uC5ED\uC5D0\uC11C \uD601\uC2E0\uC744 \uC774\uB04C\uB3C4\uB85D \uC9C0\uC6D0\uD558\uB294 \uAC83\uC744 \uBAA9\uD45C\uB85C \uD569\uB2C8\uB2E4. \uCC38\uAC00\uC790\uB294 \uCC28\uC138\uB300 AI \uAE30\uBC18 \uC2A4\uB9C8\uD2B8 \uD558\uB4DC\uC6E8\uC5B4\uC640 \uC194\uB8E8\uC158\uC758 \uD504\uB85C\uD1A0\uD0C0\uC785\uC744 \uB9CC\uB4E4\uACE0 Tuya Open Global AI+IoT Ecosystem Center\uC758 \uD601\uC2E0\uACFC \uC601\uD5A5\uB825\uC744 \uBCF4\uC5EC \uC90D\uB2C8\uB2E4.\\n\\nTuya Smart\uB294 \uC804 \uC138\uACC4 \uAC1C\uBC1C\uC790, \uBA54\uC774\uCEE4, \uB300\uD559 \uD300\uC758 \uCC38\uC5EC\uB97C \uD658\uC601\uD569\uB2C8\uB2E4. KIRO \uAE30\uBC18 AI \uCF54\uB529\uC744 \uD1B5\uD574 \uCC38\uAC00\uC790\uB294 \uB85C\uC6B0 \uCF54\uB4DC\uC640 \uBE60\uB978 \uC2DC\uC791\uC774 \uAC00\uB2A5\uD55C \uAC1C\uBC1C \uACBD\uD5D8\uC744 \uB204\uB9B4 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n\\n## 2. \uD589\uC0AC \uC77C\uC815\\n\\n| \uB2E8\uACC4 | \uB0A0\uC9DC |\\n|-------------------------------------|-------------------------------|\\n| \uB4F1\uB85D \uAE30\uAC04 | 2025\uB144 11\uC6D4 20\uC77C \u2013 12\uC6D4 20\uC77C |\\n| 1\uCC28 \uC81C\uCD9C \uB9C8\uAC10 | 2025\uB144 12\uC6D4 20\uC77C |\\n| 1\uCC28 \uD3C9\uAC00 | 2025\uB144 12\uC6D4 \uC911\uC21C |\\n| \uAC1C\uC120 \uAE30\uAC04 | 2025\uB144 12\uC6D4 \uC911\uC21C \u2013 2026\uB144 1\uC6D4 \uCD08 |\\n| Demo Day(CES, \uB77C\uC2A4\uBCA0\uC774\uAC70\uC2A4) | 2026\uB144 1\uC6D4 4\uC77C |\\n| \uCD5C\uC885 \uC81C\uCD9C \uB9C8\uAC10 | 2026\uB144 2\uC6D4 20\uC77C |\\n| \uC218\uC0C1\uC790 \uBC1C\uD45C | 2026\uB144 3\uC6D4 \uCD08 |\\n\\n\\n## 3. \uD589\uC0AC \uAC1C\uC694\\n **\uACBD\uC7C1 \uD2B8\uB799**\\n\uBAA8\uB4E0 \uCD9C\uD488\uC791\uC740 TuyaOpen Platform AI \uC624\uD508 \uC18C\uC2A4 \uD328\uD0A4\uC9C0\uB97C \uAE30\uBC18\uC73C\uB85C \uAC1C\uBC1C\uD574\uC57C \uD569\uB2C8\uB2E4.\\n\uCC38\uAC00\uC790\uB294 \uC138 \uAC00\uC9C0 \uD2B8\uB799 \uC911 **\uD558\uB098\uB97C \uC120\uD0DD\uD574** AI \uD558\uB4DC\uC6E8\uC5B4 \uB370\uBAA8\uB97C \uC81C\uC791\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n| \uD2B8\uB799 \uC774\uB984 | \uC124\uBA85 |\\n|--------------------------|-----------------------------------------------------------------------------|\\n| **AI Agent \uC560\uD50C\uB9AC\uCF00\uC774\uC158** | \uBA40\uD2F0\uBAA8\uB2EC \uC9C0\uB2A5\uD615 Agent, \uC74C\uC131/\uC774\uBBF8\uC9C0 \uC778\uC2DD, AI \uBE44\uC11C \uBC0F \uAE30\uD0C0 \uD601\uC2E0 \uD504\uB85C\uC81D\uD2B8\uC5D0 \uC9D1\uC911\uD569\uB2C8\uB2E4(\uD558\uB4DC\uC6E8\uC5B4 \uACBD\uD5D8 \uBD88\uD544\uC694). |\\n| **\uD558\uB4DC\uC6E8\uC5B4 \uAC1C\uBC1C** | Tuya \uAC1C\uBC1C \uBCF4\uB4DC\uB97C \uC0AC\uC6A9\uD574 \uB370\uC2A4\uD06C\uD1B1 \uB85C\uBD07, AI \uCC57\uBD07, AI \uC7A5\uB09C\uAC10, AI \uC6E8\uC5B4\uB7EC\uBE14, AI + \uC2A4\uB9C8\uD2B8 \uD648 \uB514\uBC14\uC774\uC2A4 \uB4F1 \uCC3D\uC758\uC801\uC778 \uD558\uB4DC\uC6E8\uC5B4\uB97C \uB9CC\uB4ED\uB2C8\uB2E4. |\\n| **\uC0B0\uC5C5 \uC194\uB8E8\uC158** | \uC5D0\uB108\uC9C0 \uAD00\uB9AC, \uD5EC\uC2A4\uCF00\uC5B4, \uAD50\uC721, \uC0B0\uC5C5 \uD601\uC2E0 \uC2DC\uB098\uB9AC\uC624 \uB4F1 \uB2E4\uC591\uD55C \uC0B0\uC5C5\uC758 AI + IoT \uC560\uD50C\uB9AC\uCF00\uC774\uC158\uC5D0 \uC9D1\uC911\uD569\uB2C8\uB2E4. |\\n\\n\\n### \uD559\uC2B5 \uC790\uB8CC:\\n\\n| \uD559\uC2B5 \uC790\uB8CC | \uB9C1\uD06C |\\n|----------------|----------------------------------|\\n| GitHub \uB9AC\uC18C\uC2A4 \uC0AC\uC774\uD2B8 | [https://github.com/tuya/TuyaOpen](https://github.com/tuya/TuyaOpen) |\\n| \uBAA8\uB4C8 \uC0AC\uC591 \uBB38\uC11C | https://developer.tuya.com/en/docs/iot/T5-E1-Module-Datasheet?id=Kdar6hf0kzmfi |\\n| TuyaOpen \uBC0F TuyaOS \uBB38\uC11C \uBAA8\uC74C | https://tuyaopen.ai/zh/blog | TuyaOpen](https://tuyaopen.ai/blog) |\\n| AI Agent \uAC1C\uBC1C | [https://developer.tuya.com/cn/docs/iot/ai-agent-management?id=Kdxr4v7uv4fud](https://developer.tuya.com/en/docs/iot/ai-agent-management?id=Kdxr4v7uv4fud) |\\n\\n- **\uBE44\uB514\uC624 \uC790\uB8CC**: \uCD5C\uC2E0 \uAC1C\uBC1C\uC790 \uB370\uBAA8 \uBC0F \uD29C\uD1A0\uB9AC\uC5BC \uBAA8\uC74C\\nTuya \uACF5\uC2DD YouTube \uCC44\uB110\uC744 \uD314\uB85C\uC6B0\uD558\uC138\uC694: https://www.youtube.com/@tuya2023/videos \\n  (\uB354 \uB9CE\uC740 \uC790\uB8CC\uB294 \uBD80\uB85D 1 \uCC38\uC870)\\n\\n- **\uB77C\uC774\uBE0C \uC2A4\uD2B8\uB9AC\uBC0D**: \uD589\uC0AC \uAE30\uAC04\uC5D0 \uC815\uAE30\uC801\uC778 \uAC1C\uBC1C\uC790 \uBD80\uD2B8\uCEA0\uD504 \uB77C\uC774\uBE0C \uC138\uC158\uC774 \uC5F4\uB9BD\uB2C8\uB2E4. \uC5C5\uB370\uC774\uD2B8\uB294 \uB300\uD68C Discord \uADF8\uB8F9\uC5D0\uC11C \uD655\uC778\uD558\uC138\uC694.\\n\\n<img src=\\"https://images.tuyacn.com/rms-static/09896aa0-bf8d-11f0-946a-f10d211a0860-1762927291978.png?tyName=111%E4%BC%81%E4%B8%9A%E5%BE%AE%E4%BF%A1%E6%88%AA%E5%9B%BE_6832ebee-7982-4fe0-8f05-eb170dbb9911.png\\" alt=\\"Discord \uCEE4\uBBA4\uB2C8\uD2F0 \uCC38\uC5EC \uBC0F \uB4F1\uB85D QR \uCF54\uB4DC\\" width=\\"150\\" />\\n\\n- Discord \uB9C1\uD06C: [https://discord.com/invite/yPPShSTttG](https://discord.com/invite/yPPShSTttG)\\n\\n\\n## \uB300\uD68C \uC694\uAD6C \uC0AC\uD56D  \\n\u25CF **\uD300 \uADDC\uBAA8**: 1~3\uBA85, \uAD6D\uC81C \uD300 \uCC38\uAC00 \uAC00\uB2A5.  \\n\u25CF **\uC5B8\uC5B4 \uC694\uAD6C \uC0AC\uD56D**: \uBAA8\uB4E0 \uC81C\uCD9C\uBB3C\uACFC \uBC1C\uD45C\uB294 **\uC601\uC5B4**\uB85C \uC791\uC131\uD574\uC57C \uD569\uB2C8\uB2E4.  \\n\u25CF **\uAE30\uC220 \uC694\uAD6C \uC0AC\uD56D**: AI \uD558\uB4DC\uC6E8\uC5B4 \uAC1C\uBC1C\uC740 **Tuya \uAC1C\uBC1C \uD50C\uB7AB\uD3FC\uC744 \uAE30\uBC18\uC73C\uB85C \uD574\uC57C \uD569\uB2C8\uB2E4**.  \\n  1\uFE0F\u20E3 **TuyaOpen**: TuyaOpen\uC740 \uC5C5\uACC4 \uC120\uB3C4\uC801\uC778 TuyaOS \uC544\uD0A4\uD14D\uCC98\uB97C \uAE30\uBC18\uC73C\uB85C \uD55C \uC624\uD508 \uC18C\uC2A4 \uD50C\uB7AB\uD3FC\uC774\uBA70 **\uC804 \uC138\uACC4 141.7\uB9CC \uBA85\uC758 \uAC1C\uBC1C\uC790**\uAC00 \uAC80\uC99D\uD588\uC2B5\uB2C8\uB2E4.  \\n  2\uFE0F\u20E3 **TuyaOS**: Tuya Wind IDE\uB294 TuyaOS EasyGo\uB97C \uC0AC\uC6A9\uD558\uB294 \uAC1C\uBC1C\uC790\uB97C \uC704\uD55C \uC6D0\uC2A4\uD1B1 \uD1B5\uD569 \uAC1C\uBC1C \uD658\uACBD\uC744 \uC81C\uACF5\uD569\uB2C8\uB2E4. \uCC38\uAC00\uC790\uB294 \uD504\uB85C\uC81D\uD2B8 \uC694\uAD6C \uC0AC\uD56D\uC5D0 \uB530\uB77C \uD50C\uB7AB\uD3FC\uC744 \uC120\uD0DD\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.  \\n**AI \uAE30\uB2A5 \uD1B5\uD569 \uB610\uB294 \uC0C1\uC6A9\uD654 \uC2DC\uB098\uB9AC\uC624**\uAC00 \uD544\uC694\uD55C \uD504\uB85C\uC81D\uD2B8\uC5D0\uB294 **TuyaOS\uB97C \uAD8C\uC7A5\uD569\uB2C8\uB2E4**.  \\n\uADF8 \uC678 \uC2DC\uB098\uB9AC\uC624\uB098 \uC694\uAD6C \uC0AC\uD56D\uC5D0\uB294 \uB354 \uAC1C\uBC29\uC801\uC778 **TuyaOpen** \uC0DD\uD0DC\uACC4\uB97C \uAD8C\uC7A5\uD569\uB2C8\uB2E4.   \\n\\n\u25CF **\uD558\uB4DC\uC6E8\uC5B4 \uC694\uAD6C \uC0AC\uD56D**:  \\n  1\uFE0F\u20E3 **\uAC1C\uBC1C \uBCF4\uB4DC**: **T5 \uC2DC\uB9AC\uC988\uB97C \uAD8C\uC7A5**\uD558\uBA70 \uB2E4\uB978 TuyaOpen \uC9C0\uC6D0 \uC0DD\uD0DC\uACC4\uB3C4 \uC0AC\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC790\uC138\uD55C \uB0B4\uC6A9\uC740 [https://tuyaopen.ai/docs/about-tuyaopen](https://tuyaopen.ai/docs/about-tuyaopen)\uC744 \uCC38\uC870\uD558\uC138\uC694.  \\n  2\uFE0F\u20E3 **DIY \uAC1C\uBC1C \uBCF4\uB4DC**: **T5 \uBAA8\uB4C8\uC744 \uC0AC\uC6A9\uD574\uC57C \uD569\uB2C8\uB2E4**.\\n\\n\\n## \uC608\uC120 \uC81C\uCD9C  \\n1. **\uC644\uC131\uB41C \uD504\uB85C\uC81D\uD2B8 \uC18C\uAC1C PDF**(\uD544\uC218)  \\n   \uC608\uC2DC: [https://drive.google.com/file/d/1IOT_VpJG1q701favo4UujjE5cZ6Cyp7q/view](https://drive.google.com/file/d/1IOT_VpJG1q701favo4UujjE5cZ6Cyp7q/view)  \\n2. **DEMO \uB3D9\uC601\uC0C1**: \uAC1C\uBC1C \uBCF4\uB4DC\uC758 \uAE30\uBCF8 \uAE30\uB2A5\uC744 \uBCF4\uC5EC \uC8FC\uACE0 **AI Chatbox \uD50C\uB798\uC2F1 \uACBD\uD5D8**\uC744 \uC644\uB8CC\uD569\uB2C8\uB2E4. (\uB354 \uB9CE\uC740 \uC790\uB8CC\uB294 \uBD80\uB85D 1 \uCC38\uC870) *(\uC6B0\uC120 \uC120\uC815)*  \\n3. **GitHub \uB9C1\uD06C**: \uAC00\uB2A5\uD55C \uACBD\uC6B0 **TuyaOpen**\uACFC \uAD00\uB828\uB41C \uCF54\uB4DC\uB97C GitHub\uC5D0 \uC5C5\uB85C\uB4DC\uD569\uB2C8\uB2E4: [https://github.com/tuya/TuyaOpen](https://github.com/tuya/TuyaOpen)  \\n4. **\uD558\uB4DC\uC6E8\uC5B4 \uBAA9\uB85D \uBC0F \uC544\uD0A4\uD14D\uCC98 \uB2E4\uC774\uC5B4\uADF8\uB7A8**(\uAC00\uB2A5\uD55C \uACBD\uC6B0)\\n\\n**\uC81C\uCD9C \uBC29\uBC95**: \uC704 \uB124 \uBB38\uC11C\uB97C \uC555\uCD95 \uD30C\uC77C\uB85C \uB9CC\uB4E4\uC5B4 \uB2E4\uC74C \uC8FC\uC18C\uB85C \uBCF4\uB0C5\uB2C8\uB2E4.  \\n**yuwei.xu@tuya.com**, \uCC38\uC870 **weila.qiu@tuya.com**  \\n**\uC774\uBA54\uC77C \uC81C\uBAA9 \uD615\uC2DD**: \\"\uD300 \uC774\uB984 + \uD504\uB85C\uC81D\uD2B8 \uC774\uB984 + \uB300\uD68C \uD2B8\uB799\\"\\n\\n\\n\\n## \uCD94\uAC00 \uD61C\uD0DD  \\n\u{1F497} \uC608\uC120 \uC2EC\uC0AC\uB97C \uD1B5\uACFC\uD55C \uC791\uC131\uC790\uB294 **Demo Day(CES \uD604\uC7A5 \uAD50\uB958\uC758 \uB0A0) \uCD08\uCCAD\uC7A5**\uC744 \uBC1B\uC2B5\uB2C8\uB2E4.\\n\\n**Tuya**\uC640 **TuyaOpen \uC81C\uC791\uC790**\uC758 \uD2B9\uBCC4 \uAC8C\uC2A4\uD2B8\uAC00 **\uAE30\uC870\uC5F0\uC124, \uC8FC\uC81C \uAC15\uC5F0, \uB77C\uC6B4\uB4DC\uD14C\uC774\uBE14 \uD1A0\uB860, AI \uAC1C\uBC1C \uACBD\uD5D8 \uACF5\uC720**\uB97C \uC9C4\uD589\uD558\uBA70 **AI \uD558\uB4DC\uC6E8\uC5B4 \uC0C1\uC6A9\uD654 \uD2B8\uB80C\uB4DC**\uB97C \uD568\uAED8 \uC0B4\uD3B4\uBD05\uB2C8\uB2E4. Tuya\uC758 \uAE00\uB85C\uBC8C \uC0DD\uD0DC\uACC4\uC5D0\uC11C **\uB6F0\uC5B4\uB09C AI \uD558\uB4DC\uC6E8\uC5B4**\uB97C \uB9CC\uB4DC\uB294 \uBC29\uBC95\uC744 \uB17C\uC758\uD558\uACE0 \uC774 \uC0DD\uD0DC\uACC4\uC5D0\uC11C **\uAC1C\uBC1C\uC790\uC758 \uAE30\uD68C\uC640 \uC131\uC7A5**\uC5D0 \uB300\uD55C \uAD00\uC810\uC744 \uACF5\uC720\uD569\uB2C8\uB2E4.\\n\\nTuya\uB294 **\uACE0\uD488\uC9C8 \uD504\uB85C\uC81D\uD2B8**\uAC00 **\uC790\uBCF8 \uC2DC\uC7A5\uACFC \uC5F0\uACB0**\uB420 \uC218 \uC788\uB3C4\uB85D \uC9C0\uC6D0\uD574 \uB354 \uB9CE\uC740 **\uC0C1\uC5C5\uC801 \uAC00\uCE58\uB97C \uAC00\uC9C4 AI \uC81C\uD488**\uC774 \uC8FC\uBAA9\uBC1B\uB3C4\uB85D \uB3D5\uC2B5\uB2C8\uB2E4.\\n\\n\uAE30\uC220 \uCE21\uBA74\uC5D0\uC11C\uB294 Vibe Coding \uB3C4\uAD6C\uB97C \uC0AC\uC6A9\uD574 **\uAE30\uCD08\uAC00 \uC5C6\uB294 \uAC1C\uBC1C\uC790**\uAC00 \uC644\uC804\uD55C AI \uD558\uB4DC\uC6E8\uC5B4\uB97C \uBE60\uB974\uACE0 \uD6A8\uC728\uC801\uC73C\uB85C \uAD6C\uCD95\uD558\uB294 \uBC29\uBC95\uC744 \uC0B4\uD3B4\uBD05\uB2C8\uB2E4. **AI \uB3C4\uAD6C\uC758 \uC9C4\uD654\uC640 \uBC1C\uC804**\uC774 **AI \uC81C\uD488 \uAC1C\uBC1C \uBC0F \uC0C1\uC6A9\uD654\uC758 \uBBF8\uB798\uB97C \uC5B4\uB5BB\uAC8C \uBC14\uAFB8\uB294\uC9C0**\uB3C4 \uB17C\uC758\uD569\uB2C8\uB2E4.\\n\\n\uC774 \uD589\uC0AC\uB294 **\uCD08\uCCAD \uC804\uC6A9**\uC785\uB2C8\uB2E4. **AI \uC804\uBB38\uAC00, AI \uC81C\uD488 \uC560\uD638\uAC00, \uC2A4\uB9C8\uD2B8 \uD558\uB4DC\uC6E8\uC5B4 \uAC1C\uBC1C\uC790 \uB610\uB294 AI \uC2A4\uD0C0\uD2B8\uC5C5 \uCC3D\uC5C5\uC790**\uB77C\uBA74 **Hackathon**\uC5D0 \uC2E0\uCCAD\uD574 **Demo Day \uCD08\uCCAD**\uC744 \uBC1B\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n**\uB370\uBAA8 \uC8FC\uC81C**: *AI\uB85C \uAC15\uD654\uB41C \uD558\uB4DC\uC6E8\uC5B4 \uC5EC\uC815\uC758 \uCF54\uD30C\uC77C\uB7FF*  \\nDemo Day \uCC38\uAC00\uC790\uB294 **Tuya \uAC1C\uBC1C\uC790 \uC804\uC6A9 \uAD7F\uC988**\uC640 **\uC644\uC804\uD55C Tuya \uAC1C\uBC1C \uD0A4\uD2B8**\uB97C \uBC1B\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4 *(\uC218\uB7C9 \uD55C\uC815)*.\\n\\n## \uCD5C\uC885 \uC81C\uCD9C \uB0B4\uC6A9\\n\u25CF **\uD504\uB85C\uC81D\uD2B8 \uCF54\uB4DC(GitHub)**  \\n\u25CF **\uAE30\uC220 \uBB38\uC11C(README.md\uC5D0 \uB2E4\uC74C \uC139\uC158\uC744 \uD3EC\uD568\uD574\uC57C \uD568):**  \\n\u2003\u25CB \uD504\uB85C\uC81D\uD2B8 \uC774\uB984 \uBC0F \uD300 \uC18C\uAC1C  \\n\u2003\u25CB \uC804\uCCB4 \uD504\uB85C\uC81D\uD2B8 \uC124\uBA85(\uD574\uACB0\uD560 \uBB38\uC81C, \uB300\uC0C1 \uC0AC\uC6A9\uC790, \uC124\uACC4)  \\n\u2003\u25CB \uC124\uACC4 \uC6D0\uCE59(\uC2DC\uC2A4\uD15C \uC544\uD0A4\uD14D\uCC98 \uB2E4\uC774\uC5B4\uADF8\uB7A8\uACFC \uD558\uB4DC\uC6E8\uC5B4 \uC5F0\uACB0 \uB2E4\uC774\uC5B4\uADF8\uB7A8 \u2014 \uB9E4\uC6B0 \uC911\uC694!)  \\n\u2003\u25CB \uD558\uB4DC\uC6E8\uC5B4 \uBAA9\uB85D(\uC815\uD655\uD55C \uBAA8\uB378, \uC608: Tuya T5 Dev Board, Raspberry Pi 4, OV5647 Camera \uB4F1)  \\n\u2003\u25CB \uB370\uBAA8 \uB3D9\uC601\uC0C1 \uB9C1\uD06C(\uAC00\uC7A5 \uB208\uC5D0 \uC798 \uB744\uB294 \uC704\uCE58\uC5D0 \uBC30\uCE58)  \\n\u25CF **\uB370\uBAA8 \uB3D9\uC601\uC0C1(1~3\uBD84)**  \\n\u2003\u25CB YouTube\uC5D0 \uD504\uB85C\uC81D\uD2B8 \uAC1C\uBC1C \uACFC\uC815\uC744 \uACF5\uC720\uD558\uACE0 \uB2E4\uC74C \uD574\uC2DC\uD0DC\uADF8\uB97C \uC0AC\uC6A9\uD569\uB2C8\uB2E4: #TuyaOpen #TuyaAI #HackWithTuya #TuyaHackathon #TuyaDevelopers #TuyaGlobal\\n\\n  \\n\\n## \uC694\uAD6C \uC0AC\uD56D\\n\u25CF \uBAA8\uB4E0 \uC81C\uCD9C\uBB3C\uC740 \uAD00\uB828 \uAD6D\uAC00 \uBC95\uB960 \uBC0F \uADDC\uC815\uC744 \uC900\uC218\uD574\uC57C \uD558\uBA70 \uB0B4\uC6A9\uC740 \uAE0D\uC815\uC801\uC774\uACE0 \uAC74\uC804\uD574\uC57C \uD569\uB2C8\uB2E4.  \\n\u25CF Tuya\uC758 \uC218\uC11D IoT \uC5D4\uC9C0\uB2C8\uC5B4\uAC00 \uBAA8\uB4E0 \uC81C\uCD9C\uBB3C\uC744 \uACF5\uC815\uD558\uACE0 \uACF5\uD3C9\uD558\uAC8C \uC2EC\uC0AC\uD569\uB2C8\uB2E4.\\n\\n  \\n\\n## \uB300\uD68C \uB9AC\uC18C\uC2A4 \uC774\uC6A9\\n\\n### a. \uAC1C\uBC1C \uBCF4\uB4DC \uC9C1\uC811 \uAD6C\uB9E4\\n\uCC38\uAC00\uC790\uB294 \uB2E4\uC74C \uB9C1\uD06C\uC5D0\uC11C **T5 AI \uAC1C\uBC1C \uBCF4\uB4DC \uD0A4\uD2B8**\uB97C \uAD6C\uB9E4\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.  \\n\u25CF [https://tuyaopen.ai/get-hardware](https://tuyaopen.ai/get-hardware)(\uC18C\uAC1C)  \\n\u25CF [AliExpress](https://www.aliexpress.com/item/1005009476541406.html)\\n\\nb. **\uBB34\uB8CC \uAC1C\uBC1C \uBCF4\uB4DC(\uD55C\uC815 \uD61C\uD0DD)**  \\n\uCC3D\uC758\uC131\uACFC \uD504\uB85C\uC81D\uD2B8 \uC2E4\uD604 \uAC00\uB2A5\uC131\uC744 \uAE30\uC900\uC73C\uB85C \uC120\uC815\uB41C \uAC1C\uBC1C\uC790\uC5D0\uAC8C \uC81C\uD55C\uB41C \uC218\uB7C9\uC758 T5 AI \uAC1C\uBC1C \uBCF4\uB4DC\uB97C \uC81C\uACF5\uD569\uB2C8\uB2E4. \uC2B9\uC778\uB41C \uC2E0\uCCAD\uC790\uB294 \uC2EC\uC0AC \uD6C4 \uBCF4\uB4DC\uB97C \uBC1B\uC2B5\uB2C8\uB2E4.  \\n**\uB9AC\uC18C\uC2A4 \uC2E0\uCCAD \uC694\uAD6C \uC0AC\uD56D:**  \\n1. \uD558\uB4DC\uC6E8\uC5B4 \uAC1C\uBC1C \uACBD\uD5D8 \u2014 \uC774\uC804 \uD504\uB85C\uC81D\uD2B8\uB97C GitHub\uB85C \uC81C\uCD9C\uD558\uAC70\uB098 \uAD00\uB828 \uD504\uB85C\uC81D\uD2B8 \uB3D9\uC601\uC0C1\uC744 \uC81C\uACF5\uD558\uC138\uC694(\uAC80\uC99D\uB41C \uACBD\uD5D8\uC774 \uC788\uB294 \uC2E0\uCCAD\uC790\uB97C \uC6B0\uC120\uD569\uB2C8\uB2E4).  \\n2. \uBA85\uD655\uD55C \uD504\uB85C\uC81D\uD2B8 \uC81C\uC548 \u2014 AI \uAD00\uB828 \uAC1C\uB150\uACFC \uAC1C\uBC1C \uC5ED\uB7C9\uC744 \uD3EC\uD568\uD55C \uC0C1\uC138\uD55C \uD504\uB85C\uC81D\uD2B8 \uACC4\uD68D\uC744 \uC81C\uC2DC\uD574\uC57C \uD569\uB2C8\uB2E4.  \\n\\nc. **Tuya Cloud \uC11C\uBE44\uC2A4 \uC774\uC6A9**  \\n**\uD574\uCEE4\uD1A4 \uAE30\uAC04 \uB3D9\uC548** \uCC38\uAC00\uC790\uB294 \uC74C\uC131 \uD569\uC131, \uC74C\uC131 \uBCF5\uC81C, \uC74C\uC131 \uC778\uC2DD \uBC0F \uAE30\uD0C0 AI \uAE30\uBC18 \uD074\uB77C\uC6B0\uB4DC \uC11C\uBE44\uC2A4 \uB4F1 Tuya\uC758 AI \uAE30\uB2A5\uC744 \uBB34\uB8CC\uB85C \uC0AC\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uD589\uC0AC \uAE30\uAC04\uC5D0\uB9CC \uC801\uC6A9\uB418\uBA70 \uD589\uC0AC \uC678\uC5D0\uB294 [AI \uACFC\uAE08 \uADDC\uCE59](https://developer.tuya.com/en/docs/iot/ai-agent-price?id=Kegb2s2shaj4d)\uC5D0 \uB530\uB77C AI \uC0AC\uC6A9\uB7C9\uC774 \uCE21\uC815\uB418\uACE0 \uACFC\uAE08\uB429\uB2C8\uB2E4.\\n\\n## 4. \uC2DC\uC0C1(\uCD1D\uC561 $4,000 \uC774\uC0C1)\\n\\n\u{1F3C6} **\uB300\uC0C1(1\uBA85)** \u2013 \uAD6C\uC131:  \\n\u25CF $2,000 Amazon \uAE30\uD504\uD2B8 \uCE74\uB4DC  \\n\u25CF Tuya \uACF5\uC2DD \uBBF8\uB514\uC5B4 \uC778\uD130\uBDF0 \uBC0F \uCDE8\uC7AC \uAE30\uD68C  \\n\u25CF Tuya \uAE30\uC220\uD300\uC758 \uC77C\uB300\uC77C \uC778\uD050\uBCA0\uC774\uC158 \uC9C0\uC6D0 \uBC0F \uC0C1\uC6A9\uD654 \uBCA4\uCC98 \uCE90\uD53C\uD138 \uB9AC\uC18C\uC2A4 \uB9E4\uCE6D  \\n\\n\u2699\uFE0F **\uCD5C\uACE0\uC758 AI \uD558\uB4DC\uC6E8\uC5B4 \uB514\uC790\uC778\uC0C1(1\uBA85)** \u2013 \uAD6C\uC131:  \\n\u25CF $1,000 Amazon \uAE30\uD504\uD2B8 \uCE74\uB4DC  \\n\u25CF Tuya \uAE30\uC220\uD300\uC758 \uC77C\uB300\uC77C \uC778\uD050\uBCA0\uC774\uC158 \uC9C0\uC6D0 \uBC0F \uC0C1\uC6A9\uD654 \uBCA4\uCC98 \uCE90\uD53C\uD138 \uB9AC\uC18C\uC2A4 \uB9E4\uCE6D  \\n\\n\u{1F4A1} **TuyaOpen \uCD5C\uACE0 \uD65C\uC6A9\uC0C1(1\uBA85)** \u2013 \uAD6C\uC131:  \\n\u25CF $500 Amazon \uAE30\uD504\uD2B8 \uCE74\uB4DC  \\n\u25CF Tuya \uACF5\uC2DD \uBBF8\uB514\uC5B4 \uCC44\uB110\uC758 \uB3C5\uC810 \uC778\uD130\uBDF0 \uBC0F \uCDE8\uC7AC \uAE30\uD68C  \\n\\n\u{1F9E0} **\uCD5C\uACE0\uC758 AI \uCF54\uB529 \uC6B0\uC218\uC0C1(1\uBA85)** \u2013 \uAD6C\uC131:  \\n\u25CF $200 Amazon \uAE30\uD504\uD2B8 \uCE74\uB4DC  \\n\\n\u{1F30D} **\uCEE4\uBBA4\uB2C8\uD2F0 \uC778\uAE30\uC0C1(5\uBA85)** \u2013 \uAD6C\uC131:  \\n\u25CF $100 Amazon \uAE30\uD504\uD2B8 \uCE74\uB4DC  \\n\\n## \uCD94\uAC00 \uC778\uC13C\uD2F0\uBE0C\\n\\n\uAC1C\uBC1C\uC790\uAC00 TuyaOpen\uACFC Vibe Coding \uB3C4\uAD6C\uB97C \uD568\uAED8 \uC0AC\uC6A9\uD574 AI \uD558\uB4DC\uC6E8\uC5B4\uB97C \uB9CC\uB4E4\uACE0 \uAC1C\uBC1C \uD6A8\uC728\uC744 \uB192\uC774\uAE30\uB97C \uAD8C\uC7A5\uD569\uB2C8\uB2E4. Vibe Coding\uC744 \uC0AC\uC6A9\uD55C \uAC1C\uBC1C\uC790\uB294 \uCD94\uAC00 \uBCF4\uC0C1\uC744 \uBC1B\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n- **\uC911\uAD6D \uBCF8\uD1A0 \uAC1C\uBC1C\uC790:**  \\n  \uC870\uAC74\uC744 \uCDA9\uC871\uD558\uB294 \uCC38\uAC00\uC790\uB294 Kiro \u201CMillion Bonus Pool Program\u201D\uC744 \uD1B5\uD574 \uCD94\uAC00 \uBCF4\uC0C1\uC744 \uBC1B\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4(\uC911\uAD6D \uBCF8\uD1A0\uC5D0 \uAE30\uBC18\uD55C \uAC1C\uBC1C\uC790\uB9CC \uC774\uC6A9 \uAC00\uB2A5).\\n\\n<img src=\\"https://images.tuyacn.com/rms-static/f3722230-c5f8-11f0-8d7c-0576ce46d19e-1763633347539.jpg?tyName=%E4%BC%81%E4%B8%9A%E5%BE%AE%E4%BF%A1%E6%88%AA%E5%9B%BE_c0909bb7-9ef4-4622-bc49-c3562d689b6a.jpg\\" />\\n\\n- **\uD574\uC678 \uAC1C\uBC1C\uC790(\uC911\uAD6D \uBCF8\uD1A0 \uC678):**  \\n  Vibe Coding \uB3C4\uAD6C\uC758 \uAC1C\uC778\uC6A9 \uC5D0\uB514\uC158\uC740 Tuya\uAC00 \uBD80\uB2F4\uD569\uB2C8\uB2E4.  \\n  Vibe Coding\uC744 \uC0AC\uC6A9\uD558\uB294 \uD574\uC678 \uCC38\uAC00\uC790 \uC911 \uCD5C\uACE0\uC758 \uD65C\uC6A9 \uC0AC\uB840\uB97C \uC120\uC815\uD558\uACE0 \uB3C4\uAD6C \uAD6C\uB9E4 \uBCF4\uC870\uAE08(\uACC4\uC815\uB2F9 \uCD5C\uB300 300\uB2EC\uB7EC)\uC744 \uC81C\uACF5\uD569\uB2C8\uB2E4.\\n\\n### \uC218\uC0C1 \uD300 \uC0DD\uD0DC\uACC4 \uC9C0\uC6D0  \\n\u25CF \uC0C1\uC6A9\uD654 \uBC1C\uC804\uC744 \uB3D5\uB294 Tuya \uAE30\uC220 \uBA58\uD1A0\uC758 \uC77C\uB300\uC77C \uC9C0\uB3C4  \\n\u25CF Tuya Developer Ecosystem\uC758 \uACF5\uC2DD \uD575\uC2EC \uC778\uC99D \uAC1C\uBC1C\uC790\uAC00 \uB418\uC5B4 \uCD5C\uC2E0 \uD50C\uB7AB\uD3FC \uAE30\uB2A5, \uB370\uBAA8 \uACF5\uB3D9 \uC81C\uC791\uC744 \uC704\uD55C \uBB34\uB8CC \uBAA8\uB4C8 \uBC0F \uAC1C\uBC1C \uBCF4\uB4DC, \uAE30\uC220 \uC9C0\uC6D0\uC5D0 \uC6B0\uC120 \uC811\uADFC  \\n\u25CF \uD574\uC678 \uC81C\uD488 \uBC0F \uBE44\uC988\uB2C8\uC2A4 \uC9C0\uC6D0: \uC218\uC0C1 \uD504\uB85C\uC81D\uD2B8\uB97C \uAD6D\uC81C \uC804\uC2DC\uD68C\uC5D0 \uC120\uBCF4\uC774\uACE0 Tuya\uAC00 \uD574\uC678 \uD655\uC7A5\uC744 \uC704\uD55C \uC804 \uCC44\uB110 \uC9C0\uC6D0 \uC81C\uACF5  \\n\u25CF Tuya Developer Accelerator Program\uC5D0 \uCC38\uC5EC\uD574 \uD6C4\uC18D \uC778\uD050\uBCA0\uC774\uC158 \uC9C0\uC6D0 \uC218\uB839  \\n\\n## \uBD80\uB85D 1: \uB9AC\uC18C\uC2A4\\n### \uB370\uBAA8 \uB3D9\uC601\uC0C1\\n1. [TuyaOpen Framework \uC18C\uAC1C](https://www.youtube.com/watch?v=YQ7hDAvBsG4&t=229s)\\n2. [AI \uC2A4\uB9C8\uD2B8 \uB77C\uC774\uD2B8 \uC2A4\uD2B8\uB9BD](https://www.youtube.com/watch?v=c_Of93erYdk)\\n3. [T5 AI \uAC1C\uBC1C \uBCF4\uB4DC](https://www.youtube.com/watch?v=kW9lWuF3RmE)\\n4. [AI \uC2A4\uB9C8\uD2B8 \uC804\uC6D0 \uC18C\uCF13](https://www.youtube.com/watch?v=7A8sYujTdno)\\n5. [AI \uB2E4\uC911 \uBC18\uB824\uB3D9\uBB3C \uC778\uC2DD](https://www.youtube.com/watch?v=3JX4e09S70M)\\n6. [AI \uC2A4\uB9C8\uD2B8 \uD648](https://www.youtube.com/watch?v=5CJGn6necrQ)\\n7. [\uC2A4\uB9C8\uD2B8 \uB514\uC9C0\uD138 \uC561\uC790](https://www.youtube.com/watch?v=JaxHobM5278)\\n\\n### \uAC1C\uBC1C\uC790 \uBB38\uC11C \uBAA9\uB85D\\n1. TuyaOpen \uC18C\uAC1C  \\nhttps://tuyaopen.ai/docs/about-tuyaopen  \\n2. \uB85C\uB4DC\uB9F5 \uBC0F \uB9B4\uB9AC\uC2A4  \\n[\uB85C\uB4DC\uB9F5 \uBC0F \uB9B4\uB9AC\uC2A4 | TuyaOpen ](https://tuyaopen.ai/docs/maintenance-and-releases) \\n3. \uB514\uB809\uD130\uB9AC \uAD6C\uC870  \\nhttps://tuyaopen.ai/docs/project-walkthrough  \\n4. \uC2DC\uC791\uD558\uAE30  \\nhttps://tuyaopen.ai/docs/quick-start  \\n5. \uD558\uB4DC\uC6E8\uC5B4 \uAC00\uC774\uB4DC  \\nhttps://tuyaopen.ai/docs/hardware  \\n6. \uC560\uD50C\uB9AC\uCF00\uC774\uC158  \\nhttps://tuyaopen.ai/docs/applications  \\n7. \uC608\uC81C - \uC77C\uBC18 \uB370\uBAA8  \\nhttps://tuyaopen.ai/docs/examples/demo-generic-examples  \\n8. \uC8FC\uBCC0 \uC7A5\uCE58  \\nhttps://tuyaopen.ai/docs/peripheral/support_peripheral_list  \\n9. \uC0C8 \uD504\uB85C\uC81D\uD2B8 - \uD50C\uB7AB\uD3FC \uD3EC\uD305  \\nhttps://tuyaopen.ai/docs/hardware/porting/porting-platform  \\n10. \uD074\uB77C\uC6B0\uB4DC \uC11C\uBE44\uC2A4 - \uC81C\uD488 \uC0DD\uC131  \\nhttps://tuyaopen.ai/docs/cloud/tuya-cloud/creating-new-product  \\n11. TKL API - OS API - tkl_mutex | \uBBA4\uD14D\uC2A4 \uC7A0\uAE08  \\nhttps://tuyaopen.ai/docs/tkl-api/tkl_mutex  \\n12. TOS \uB3C4\uAD6C  \\nhttps://tuyaopen.ai/docs/tos-tools/tos-guide  \\n13. \uBE4C\uB4DC \uC2DC\uC2A4\uD15C  \\nhttps://tuyaopen.ai/docs/build-system/compilation-guide  \\n\\n### Q&A\\n1. FAQ  \\n[FAQ | TuyaOpen](https://tuyaopen.ai/docs/faqs)  \\n2. \uAE30\uC5EC  \\n[\uAE30\uC5EC \uAC00\uC774\uB4DC | TuyaOpen](https://tuyaopen.ai/docs/contribute/contribute-guide)  \\n\\n\\n### \uD504\uB85C\uC81D\uD2B8\\n- [https://tuyaopen.ai/projects](https://tuyaopen.ai/projects)\\n\\n  \\n\\n## \uBD80\uB85D 2: \uC8FC\uC694 \uB9C1\uD06C\\n\\n- **\uD504\uB85C\uC81D\uD2B8 \uC18C\uAC1C PDF \uC608\uC2DC**:  \\n  [Google Drive](https://drive.google.com/file/d/1IOT_VpJG1q701favo4UujjE5cZ6Cyp7q/view?usp=drive_link)\\n\\n- **T5 AI Board \uAD6C\uB9E4**:  \\n  [AliExpress](https://www.aliexpress.com/item/1005009476541406.html)"},{"id":"/2025/09/22/v1.5.0-release","metadata":{"permalink":"/ko/blog/2025/09/22/v1.5.0-release","editUrl":"https://github.com/Tuya-Community/TuyaOpen.io/edit/master/i18n/ko/docusaurus-plugin-content-blog/2025-09-22-v1.5.0-release.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2025-09-22-v1.5.0-release.md","title":"V1.5.0 \uB9B4\uB9AC\uC2A4","description":"\u{1F389} v1.5.0 \uC8FC\uC694 \uB9B4\uB9AC\uC2A4(2025\uB144 9\uC6D4 22\uC77C) - \uC5F4\uC2EC\uD788 \uC900\uBE44\uD588\uC2B5\uB2C8\uB2E4! \uC774\uBC88 \uC5C5\uB370\uC774\uD2B8\uC5D0\uB294 \uBAA8\uB4E0 \uC5ED\uB7C9\uC744 \uC3DF\uC558\uC2B5\uB2C8\uB2E4!","date":"2025-09-22T00:00:00.000Z","tags":[{"inline":false,"label":"TuyaOpen","permalink":"/ko/blog/tags/TuyaOpen","description":"TuyaOpen \uD50C\uB7AB\uD3FC \uBC0F \uAC1C\uBC1C \uAD00\uB828 \uCF58\uD150\uCE20"}],"readingTime":6.57,"hasTruncateMarker":true,"authors":[{"name":"Tuya","title":"TuyaOpen \uBAA8\uB4E0 \uC720\uC9C0\uAD00\uB9AC\uC790","url":"https://github.com/tuya/tuya-open","socials":{"github":"https://github.com/tuya","youtube":"https://youtube.com/@tuyasmart5602","website":"https://tuyaopen.ai"},"imageURL":"https://avatars.githubusercontent.com/u/73523937?v=4","key":"tuya","page":null}],"frontMatter":{"title":"V1.5.0 \uB9B4\uB9AC\uC2A4","authors":["tuya"],"image":"/img/home/tuyaopen-logo-social-preview.png","tags":["TuyaOpen"]},"unlisted":false,"prevItem":{"title":"Tuya AI Innovators Hackathon 2025","permalink":"/ko/blog/2025-tuya-ai-innovatores-hackathon"},"nextItem":{"title":"AI \uCF54\uB529\uC73C\uB85C TuyaOpen \uAC1C\uBC1C \uAC00\uC18D\uD558\uAE30","permalink":"/ko/blog/2025/09/19/vibe-coding-accelerate-tuyaopen-development"}},"content":"## \u{1F389} v1.5.0 \uC8FC\uC694 \uB9B4\uB9AC\uC2A4(2025\uB144 9\uC6D4 22\uC77C) - \uC5F4\uC2EC\uD788 \uC900\uBE44\uD588\uC2B5\uB2C8\uB2E4! \uC774\uBC88 \uC5C5\uB370\uC774\uD2B8\uC5D0\uB294 \uBAA8\uB4E0 \uC5ED\uB7C9\uC744 \uC3DF\uC558\uC2B5\uB2C8\uB2E4!\\n\\n\\n{/* truncate */}\\n\\n\uD300\uC774 \uC218\uAC1C\uC6D4 \uB3D9\uC548 \uC138\uC2EC\uD558\uAC8C \uB2E4\uB4EC\uC740 \uB05D\uC5D0 v1.5.0\uC744 \uCD9C\uC2DC\uD569\uB2C8\uB2E4! \uC774\uBC88 \uC5C5\uB370\uC774\uD2B8\uB294 \uD558\uC704 \uC544\uD0A4\uD14D\uCC98\uBD80\uD130 \uC0AC\uC6A9\uC790 \uACBD\uD5D8\uAE4C\uC9C0 \uCD5C\uADFC \uAC00\uC7A5 \uC885\uD569\uC801\uC778 \uC5C5\uADF8\uB808\uC774\uB4DC\uB77C\uACE0 \uD560 \uC218 \uC788\uC73C\uBA70 \uBAA8\uB4E0 \uC138\uBD80 \uC0AC\uD56D\uC5D0 \uD300\uC758 \uB178\uB825\uC744 \uB2F4\uC558\uC2B5\uB2C8\uB2E4. TuyaOpen \uD504\uB85C\uC81D\uD2B8\uB97C \uB354 \uC7AC\uBBF8\uC788\uACE0 \uD48D\uBD80\uD558\uAC8C \uB9CC\uB4E4\uC5B4 \uC900 \uD65C\uBC1C\uD55C \uCEE4\uBBA4\uB2C8\uD2F0\uC640 \uAC1C\uBC1C\uC790 \uC5EC\uB7EC\uBD84\uC758 \uD6CC\uB96D\uD55C \uC81C\uC548\uC5D0\uB3C4 \uAC10\uC0AC\uB4DC\uB9BD\uB2C8\uB2E4. \uCEE4\uBBA4\uB2C8\uD2F0 \uAC1C\uBC1C\uC790 [HangYongmao](https://github.com/HangYongmao)\uAC00 \uC624\uD508 \uC18C\uC2A4 \uACF5\uB3D9 \uC81C\uC791\uC5D0 \uCC38\uC5EC\uD574 \uC7AC\uBBF8\uC788\uB294 \uAC8C\uC784 \uB370\uBAA8\uB97C \uB9CC\uB4E0 \uAC83\uC744 \uBCF4\uAC8C \uB418\uC5B4 \uD300\uB3C4 \uD2B9\uD788 \uAE30\uC069\uB2C8\uB2E4.\\n\\n### \u{1F4AA} T5AI \uD50C\uB7AB\uD3FC: \uC131\uB2A5 \uB3C4\uC57D\uACFC \uD558\uB4DC\uC6E8\uC5B4 \uC0DD\uD0DC\uACC4 \uD655\uC7A5\\n\\n**\uC774\uBC88 \uC8FC\uC694 \uC5C5\uB370\uC774\uD2B8:**\\n- **\uBA40\uD2F0\uCF54\uC5B4 \uC131\uB2A5 \uC5C5\uADF8\uB808\uC774\uB4DC**: Tuya T5 \uCE69\uC774 \uC774\uC81C SMP(Symmetric Multi-Processing) \uC544\uD0A4\uD14D\uCC98\uB97C \uC644\uC804\uD788 \uC9C0\uC6D0\uD569\uB2C8\uB2E4. \uBA40\uD2F0\uCF54\uC5B4 \uC5F0\uC0B0 \uC131\uB2A5\uC744 \uD06C\uAC8C \uB04C\uC5B4\uC62C\uB824 \uC2DC\uC2A4\uD15C \uB3D9\uC2DC\uC131\uACFC \uC131\uB2A5\uC744 \uD5A5\uC0C1\uD558\uBA70 \uACE0\uBD80\uD558 \uBC0F \uBA40\uD2F0\uD0DC\uC2A4\uD06C \uC2DC\uB098\uB9AC\uC624\uC5D0 \uC801\uD569\uD569\uB2C8\uB2E4.\\n- **MCP(Multimodal Control Platform) \uC11C\uBE44\uC2A4 \uACF5\uC2DD \uCD9C\uC2DC**: TuyaOpen \uB514\uBC14\uC774\uC2A4\uB97C Tuya Cloud\uC5D0 \uC5F0\uACB0\uD558\uBA74 \uAC1C\uBC1C\uC790\uAC00 \uD074\uB77C\uC6B0\uB4DC\uC5D0\uC11C \uB9DE\uCDA4\uD615 MCP \uC11C\uBE44\uC2A4\uB97C \uAC8C\uC2DC\uD558\uACE0 \uC5F0\uACB0\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uACF5\uC2DD \uD504\uB9AC\uC14B\uACFC \uC0AC\uC6A9\uC790 \uC9C0\uC815 \uD655\uC7A5\uC744 \uC9C0\uC6D0\uD574 Agent\uC640 IoT \uB514\uBC14\uC774\uC2A4\uC758 \uC0C1\uD638 \uC791\uC6A9 \uAE30\uB2A5\uC744 \uD06C\uAC8C \uD655\uC7A5\uD569\uB2C8\uB2E4.\\n- **\uD558\uB4DC\uC6E8\uC5B4 \uC0DD\uD0DC\uACC4 \uC9C0\uC18D \uD655\uC7A5**: `TUYA_T5AI_Pocket`, `TUYA_T5A_Core`, `WAVESHARE_T5AI_TOUCH_AMOLED_1_75` \uB4F1\uC744 \uD3EC\uD568\uD55C \uC5EC\uB7EC \uACF5\uC2DD \uBC0F \uC0DD\uD0DC\uACC4 \uAC1C\uBC1C \uBCF4\uB4DC \uC9C0\uC6D0\uC744 \uCD94\uAC00\uD574 \uB354 \uB9CE\uC740 \uC560\uD50C\uB9AC\uCF00\uC774\uC158 \uC2DC\uB098\uB9AC\uC624\uB97C \uC9C0\uC6D0\uD558\uACE0 \uAC1C\uBC1C\uC790\uAC00 \uC720\uC5F0\uD558\uAC8C \uC120\uD0DD\uD560 \uC218 \uC788\uB3C4\uB85D \uD588\uC2B5\uB2C8\uB2E4.\\n- **\uD601\uC2E0\uC801\uC778 \uC560\uD50C\uB9AC\uCF00\uC774\uC158 \uC608\uC81C**: \uC0C8\uB85C\uC6B4 `tuya_t5_pocket` \uAC8C\uC784 \uCF58\uC194 \uC560\uD50C\uB9AC\uCF00\uC774\uC158\uC744 \uCD9C\uC2DC\uD574 \uBA40\uD2F0\uBAA8\uB2EC \uC0C1\uD638 \uC791\uC6A9, \uADF8\uB798\uD53D \uD45C\uC2DC, \uC5D4\uD130\uD14C\uC778\uBA3C\uD2B8 \uC560\uD50C\uB9AC\uCF00\uC774\uC158\uC5D0\uC11C T5AI \uD50C\uB7AB\uD3FC\uC758 \uAC15\uB825\uD55C \uAE30\uB2A5\uC744 \uBCF4\uC5EC \uC8FC\uACE0 \uC784\uBCA0\uB514\uB4DC \uAC1C\uBC1C\uC758 \uCC3D\uC758\uC801\uC778 \uAC00\uB2A5\uC131\uC744 \uD655\uC7A5\uD588\uC2B5\uB2C8\uB2E4.\\n- **\uC8FC\uBCC0 \uC7A5\uCE58 \uBC0F \uB4DC\uB77C\uC774\uBC84 \uD655\uC7A5 \uC5C5\uADF8\uB808\uC774\uB4DC**: \uC774\uBC88 \uBC84\uC804\uC740 \uC5EC\uB7EC T5AI DVP \uBE44\uB514\uC624 \uC13C\uC11C \uB4DC\uB77C\uC774\uBC84, ws2812 \uB4F1 RGB LED \uB4DC\uB77C\uC774\uBC84, IR \uC801\uC678\uC120 \uB9AC\uBAA8\uCEE8 \uC1A1\uC218\uC2E0\uAE30 \uB4F1 \uB2E4\uC591\uD55C \uC8FC\uBCC0 \uC7A5\uCE58\uC640 \uB4DC\uB77C\uC774\uBC84\uC758 \uC9C0\uC6D0\uC744 \uCD94\uAC00\uD558\uACE0 \uCD5C\uC801\uD654\uD588\uC2B5\uB2C8\uB2E4. \uAC1C\uBC1C\uC790\uB294 \uC13C\uC11C, \uB514\uC2A4\uD50C\uB808\uC774, \uC870\uBA85, \uC801\uC678\uC120 \uB4F1 \uB2E4\uC591\uD55C \uC8FC\uBCC0 \uC7A5\uCE58\uB97C \uC27D\uAC8C \uD1B5\uD569\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n- **\uB4DC\uB77C\uC774\uBC84 \uC0DD\uD0DC\uACC4 \uC9C0\uC18D \uC131\uC7A5**: \uACF5\uC2DD \uD300\uACFC \uCEE4\uBBA4\uB2C8\uD2F0\uAC00 \uC0C8\uB85C\uC6B4 \uB4DC\uB77C\uC774\uBC84\uB97C \uACC4\uC18D \uAE30\uC5EC\uD574 \uB354 \uB9CE\uC740 \uB300\uC911\uC801\uC774\uACE0 \uD601\uC2E0\uC801\uC778 \uD558\uB4DC\uC6E8\uC5B4\uB97C \uC9C0\uC6D0\uD569\uB2C8\uB2E4. \uC624\uB514\uC624/\uBE44\uB514\uC624 \uCEA1\uCC98, \uB514\uC2A4\uD50C\uB808\uC774 \uC81C\uC5B4, \uC2A4\uB9C8\uD2B8 \uD648, \uC5D4\uD130\uD14C\uC778\uBA3C\uD2B8 \uC0C1\uD638 \uC791\uC6A9 \uB4F1 \uB2E4\uC591\uD55C \uC601\uC5ED\uC5D0\uC11C \uC81C\uD488 \uC544\uC774\uB514\uC5B4\uB97C \uBE60\uB974\uAC8C \uAD6C\uD604\uD560 \uC218 \uC788\uB294 \uB4DC\uB77C\uC774\uBC84\uC640 \uC560\uD50C\uB9AC\uCF00\uC774\uC158 \uC608\uC81C\uB97C \uCC3E\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n--- \\n\\n# Tuya \uD50C\uB7AB\uD3FC, MCP \uD1B5\uD569!\\nTuya Intelligent Agent Development Platform\uC740 \uC774\uC81C MCP Server \uD1B5\uD569 \uAE30\uB2A5\uC744 \uC644\uC804\uD788 \uC9C0\uC6D0\uD569\uB2C8\uB2E4. \uACF5\uC2DD MCP Server \uB610\uB294 \uC9C1\uC811 \uAC1C\uBC1C\uD55C MCP Server\uB97C \uD1B5\uD569\uD558\uBA74 Agent\uC640 \uC11C\uB4DC\uD30C\uD2F0 \uC11C\uBE44\uC2A4 \uBC0F IoT \uB514\uBC14\uC774\uC2A4 \uC0AC\uC774\uC758 \uC0C1\uD638 \uC791\uC6A9 \uAE30\uB2A5\uC744 \uD06C\uAC8C \uD655\uC7A5\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC774\uB294 \uB300\uADDC\uBAA8 \uC5B8\uC5B4 \uBAA8\uB378\uC5D0 \uBB3C\uB9AC\uC801 \uC138\uACC4\uB97C \uC778\uC2DD\uD558\uACE0 \uC2E4\uD589\uD560 \uC218 \uC788\uB294 \\"\uB208, \uD314, \uB2E4\uB9AC\\"\uB97C \uC7A5\uCC29\uD558\uB294 \uAC83\uACFC \uAC19\uC2B5\uB2C8\uB2E4. LLM\uC744 \uD1B5\uD55C \uC9C0\uB2A5\uD615 \uC758\uC0AC \uACB0\uC815\uC744 \uAD6C\uD604\uD558\uACE0 \uC2E4\uC81C \uB514\uBC14\uC774\uC2A4 \uBC0F \uC11C\uBE44\uC2A4\uC640 \uD6A8\uC728\uC801\uC774\uACE0 \uC548\uC804\uD558\uAC8C \uC0C1\uD638 \uC791\uC6A9\uD574 AI\uC640 \uBB3C\uB9AC\uC801 \uC2DC\uC2A4\uD15C\uC744 \uC5F0\uACB0\uD558\uB294 \uC9C0\uB2A5\uD615 \uB2E4\uB9AC\uB97C \uAD6C\uCD95\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\nTuya MCP \uAE30\uC220\uC758 \uC7A5\uC810\\n- IoT \uB514\uBC14\uC774\uC2A4 \uC0DD\uD0DC\uACC4\uC5D0 \uB9DE\uAC8C \uC124\uACC4: Tuya \uC0DD\uD0DC\uACC4 \uB514\uBC14\uC774\uC2A4\uB294 \uD50C\uB7EC\uADF8 \uC564 \uD50C\uB808\uC774 \uBC29\uC2DD\uC774\uBBC0\uB85C Agent\uC5D0 MCP Server\uB97C \uCD94\uAC00\uD558\uAE30\uB9CC \uD558\uBA74 \uC989\uC2DC \uC0AC\uC6A9\uD560 \uC218 \uC788\uC73C\uBA70 \uB2E4\uC591\uD55C IoT \uC2DC\uB098\uB9AC\uC624\uC5D0 \uC790\uC5F0\uC2A4\uB7FD\uAC8C \uD1B5\uD569\uB429\uB2C8\uB2E4.\\n- \uB2E4\uC591\uD55C MCP \uC11C\uBE44\uC2A4 \uD1B5\uD569 \uC9C0\uC6D0: \uACF5\uC2DD \uD504\uB9AC\uC14B MCP Server\uBFD0 \uC544\uB2C8\uB77C \uAC1C\uBC1C\uC790\uC758 MCP \uC11C\uBE44\uC2A4 \uB9DE\uCDA4 \uD655\uC7A5\uB3C4 \uC9C0\uC6D0\uD574 \uD48D\uBD80\uD55C \uC11C\uBE44\uC2A4 \uC0DD\uD0DC\uACC4\uC640 \uAC1C\uC778\uD654\uB41C \uD1B5\uD569\uC744 \uACB0\uD569\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n- \uB354 \uAC04\uB2E8\uD55C \uAC1C\uBC1C \uD1B5\uD569: \uD50C\uB7AB\uD3FC\uC5D0 \uC11C\uBE44\uC2A4\uB97C \uD55C \uBC88 \uB4F1\uB85D\uD558\uACE0 \uACBD\uB7C9 SDK\uB97C \uD1B5\uD569\uD558\uBA74 \uC5EC\uB7EC \uC9C0\uC5ED\uC5D0\uC11C MCP Server\uC5D0 \uBE60\uB974\uAC8C \uC811\uADFC\uD558\uACE0 \uBC30\uD3EC\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n- \uAE00\uB85C\uBC8C \uC11C\uBE44\uC2A4 \uBC30\uD3EC \uC9C0\uC6D0: \uC804 \uC138\uACC4 5\uAC1C \uC8FC\uC694 \uC9C0\uC5ED\uC758 \uC11C\uBE44\uC2A4 \uC5F0\uACB0\uC744 \uC9C0\uC6D0\uD558\uACE0 \uC778\uC811 \uC9C0\uC5ED\uC758 \uB0AE\uC740 \uC9C0\uC5F0 \uC2DC\uAC04 \uC811\uADFC\uC744 \uC81C\uACF5\uD574 \uAC01 \uC9C0\uC5ED\uC758 \uBE44\uC988\uB2C8\uC2A4 \uBC30\uD3EC \uBC0F \uADDC\uC815 \uC900\uC218 \uC694\uAD6C \uC0AC\uD56D\uC744 \uCDA9\uC871\uD569\uB2C8\uB2E4.\\n- \uC548\uC804\uD558\uACE0 \uC548\uC815\uC801\uC778 \uC7A5\uAE30 \uC5F0\uACB0 \uD1B5\uC2E0: WebSocket \uD504\uB85C\uD1A0\uCF5C\uC744 \uAE30\uBC18\uC73C\uB85C \uC5EC\uB7EC \uC9C0\uC5ED\uC5D0 \uC548\uC804\uD55C \uC7A5\uAE30 \uC5F0\uACB0\uC744 \uAD6C\uCD95\uD574 \uB370\uC774\uD130 \uC804\uC1A1\uC758 \uAE30\uBC00\uC131, \uBB34\uACB0\uC131, \uAC00\uC6A9\uC131\uC744 \uBCF4\uC7A5\uD569\uB2C8\uB2E4.\\n\\n### \u{1F6E0}\uFE0F MCP SDK \uBE60\uB978 \uD1B5\uD569\\n\uAC1C\uBC1C\uC790\uB294 \uACF5\uC2DD \uC624\uD508 \uC18C\uC2A4 SDK\uB97C \uD1B5\uD574 MCP \uAE30\uB2A5\uC744 \uBE60\uB974\uAC8C \uD1B5\uD569\uD560 \uC218 \uC788\uC5B4 \uAC1C\uBC1C\uC744 \uD06C\uAC8C \uAC04\uC18C\uD654\uD569\uB2C8\uB2E4.  \\n- **MCP SDK(\uC624\uD508 \uC18C\uC2A4) \uC8FC\uC18C**: [https://github.com/tuya/tuya-mcp-sdk](https://github.com/tuya/tuya-mcp-sdk)\\n\uC774 SDK\uB294 \uC644\uC804\uD55C \uD1B5\uD569 [\uBB38\uC11C](https://developer.tuya.com/cn/docs/iot/mcp-manage?id=Ketxzvb2s9ziq), \uC608\uC81C \uCF54\uB4DC, \uC9C0\uC18D\uC801\uC778 \uC720\uC9C0 \uAD00\uB9AC\uB97C \uC81C\uACF5\uD558\uBA70 \uBA40\uD2F0 \uD50C\uB7AB\uD3FC \uBC0F \uB2E4\uAD6D\uC5B4 \uD655\uC7A5\uC744 \uC9C0\uC6D0\uD574 Agent\uC640 \uBB3C\uB9AC\uC801 \uC138\uACC4\uB97C \uD6A8\uC728\uC801\uC73C\uB85C \uC5F0\uACB0\uD569\uB2C8\uB2E4.\\n\\n\\n# TuyaOpen SMP \uC544\uD0A4\uD14D\uCC98! SMP \uC544\uD0A4\uD14D\uCC98\uB780 \uBB34\uC5C7\uC774\uBA70 \uC131\uB2A5\uC744 \uC5B4\uB5BB\uAC8C \uAC1C\uC120\uD558\uB098\uC694?\\n![AMP vs SMP](https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQIGZ1BIgEvkdELaNGGX_P2SoDTFdHkpTPPiA&s)\\n  \\nAMP(Asymmetric Multi-Processing)\uC640 SMP(Symmetric Multi-Processing)\uB294 \uBA40\uD2F0\uCF54\uC5B4 \uD504\uB85C\uC138\uC11C\uC5D0\uC11C \uC0AC\uC6A9\uD558\uB294 \uB450 \uAC00\uC9C0 \uC77C\uBC18\uC801\uC778 \uC544\uD0A4\uD14D\uCC98\uC785\uB2C8\uB2E4.\\n\\n- **AMP(Asymmetric Multi-Processing)**: \uAC01 \uCF54\uC5B4\uAC00 \uC11C\uB85C \uB2E4\uB978 \uC6B4\uC601 \uCCB4\uC81C\uB098 \uC791\uC5C5\uC744 \uC2E4\uD589\uD560 \uC218 \uC788\uC73C\uBA70 \uCF54\uC5B4 \uAC04 \uB9AC\uC18C\uC2A4 \uD560\uB2F9\uACFC \uC2A4\uCF00\uC904\uB9C1\uC774 \uBE44\uAD50\uC801 \uB3C5\uB9BD\uC801\uC785\uB2C8\uB2E4. \uC2E4\uC2DC\uAC04\uC131 \uB610\uB294 \uBCF4\uC548\uC5D0 \uD2B9\uBCC4\uD55C \uC694\uAD6C \uC0AC\uD56D\uC774 \uC788\uB294 \uC2DC\uB098\uB9AC\uC624\uC5D0 \uC801\uD569\uD558\uC9C0\uB9CC \uAC1C\uBC1C \uBC0F \uB9AC\uC18C\uC2A4 \uAD00\uB9AC\uC758 \uBCF5\uC7A1\uB3C4\uAC00 \uB192\uC2B5\uB2C8\uB2E4. \uC608\uB97C \uB4E4\uC5B4 \uD55C \uCF54\uC5B4\uB294 Linux\uB97C \uC2E4\uD589\uD558\uACE0 \uB2E4\uB978 \uCF54\uC5B4\uB294 RTOS\uB97C \uC2E4\uD589\uD560 \uC218 \uC788\uC73C\uBA70 \uC11C\uB85C \uC601\uD5A5\uC744 \uC8FC\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.\\n\\n- **SMP(Symmetric Multi-Processing)**: \uBAA8\uB4E0 \uCF54\uC5B4\uAC00 \uB3D9\uC77C\uD55C \uC6B4\uC601 \uCCB4\uC81C\uB97C \uC2E4\uD589\uD558\uACE0 \uC2DC\uC2A4\uD15C\uC774 \uC791\uC5C5\uC744 \uAC01 \uCF54\uC5B4\uC5D0 \uC790\uB3D9\uC73C\uB85C \uBD84\uBC30\uD569\uB2C8\uB2E4. \uCF54\uC5B4\uC758 \uC0C1\uD0DC\uAC00 \uB3D9\uC77C\uD558\uACE0 \uB9AC\uC18C\uC2A4\uB97C \uACF5\uC720\uD558\uBBC0\uB85C \uAC1C\uBC1C\uC790\uAC00 \uD2B9\uC815 \uC791\uC5C5\uC774 \uC5B4\uB290 \uCF54\uC5B4\uC5D0\uC11C \uC2E4\uD589\uB418\uB294\uC9C0 \uC2E0\uACBD \uC4F8 \uD544\uC694\uAC00 \uC5C6\uC5B4 \uACE0\uB3D9\uC2DC\uC131 \uBC0F \uBA40\uD2F0\uD0DC\uC2A4\uD06C \uC2DC\uB098\uB9AC\uC624\uC5D0 \uC801\uD569\uD569\uB2C8\uB2E4.\\n\\n**\uAC04\uB2E8\uD788 \uB9D0\uD558\uBA74**: AMP\uB294 \uB354 \uC720\uC5F0\uD558\uC9C0\uB9CC \uBCF5\uC7A1\uD574 \uD2B9\uC218\uD55C \uC694\uAD6C \uC0AC\uD56D\uC5D0 \uC801\uD569\uD558\uACE0, SMP\uB294 \uC0AC\uC6A9\uD558\uAE30 \uC26C\uC6CC \uB300\uBD80\uBD84\uC758 \uBC94\uC6A9 \uBA40\uD2F0\uCF54\uC5B4 \uC560\uD50C\uB9AC\uCF00\uC774\uC158\uC5D0 \uC801\uD569\uD569\uB2C8\uB2E4. T5AI v1.5.0\uC740 SMP \uC544\uD0A4\uD14D\uCC98\uB97C \uCC44\uD0DD\uD574 \uBA40\uD2F0\uCF54\uC5B4 \uAC1C\uBC1C\uC744 \uB354 \uAC04\uB2E8\uD558\uACE0 \uD6A8\uC728\uC801\uC73C\uB85C \uB9CC\uB4ED\uB2C8\uB2E4!\\n\\n**TuyaOpen\uC758 SMP \uC544\uD0A4\uD14D\uCC98\uB294 \uAC1C\uBC1C\uC790\uC5D0\uAC8C \uBB34\uC5C7\uC744 \uC758\uBBF8\uD558\uB098\uC694? \uAC1C\uBC1C \uBC29\uC2DD\uC744 \uBC14\uAFD4\uC57C \uD558\uB098\uC694?**\\n> \uC694\uC57D: v1.5.0\uC740 \uAC1C\uBC1C\uC744 \uB354 \uD6A8\uC728\uC801\uC774\uACE0 \uAC15\uB825\uD558\uAC8C \uB9CC\uB4E4\uC9C0\uB9CC \uAC1C\uBC1C \uC2B5\uAD00\uACFC \uCF54\uB4DC \uAD6C\uC870\uB97C \uD06C\uAC8C \uBCC0\uACBD\uD560 \uD544\uC694\uB294 \uC5C6\uC2B5\uB2C8\uB2E4. \uC0C8 \uAE30\uB2A5\uACFC \uBA40\uD2F0\uCF54\uC5B4 \uBAA8\uBC94 \uC0AC\uB840\uC5D0 \uC9D1\uC911\uD558\uBA74 \uC5C5\uADF8\uB808\uC774\uB4DC\uC758 \uC774\uC810\uC744 \uC27D\uAC8C \uB204\uB9B4 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n- **\uB354 \uC6D0\uD65C\uD55C \uAC1C\uBC1C \uACBD\uD5D8**: SMP \uBA40\uD2F0\uCF54\uC5B4 \uC9C0\uC6D0\uACFC \uD558\uB4DC\uC6E8\uC5B4 \uC0DD\uD0DC\uACC4 \uD655\uC7A5\uC744 \uD1B5\uD574 \uC131\uB2A5 \uBCD1\uBAA9\uC744 \uAC71\uC815\uD558\uC9C0 \uC54A\uACE0 \uACE0\uB3D9\uC2DC\uC131 \uBA40\uD2F0\uD0DC\uC2A4\uD06C \uC560\uD50C\uB9AC\uCF00\uC774\uC158\uC744 \uC27D\uAC8C \uAC1C\uBC1C\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uAE30\uC874 \uC2F1\uAE00\uCF54\uC5B4 \uCF54\uB4DC\uB294 \uD06C\uAC8C \uC218\uC815\uD560 \uD544\uC694\uAC00 \uC5C6\uC73C\uBA70 \uC2DC\uC2A4\uD15C\uC774 \uBA40\uD2F0\uCF54\uC5B4 \uB9AC\uC18C\uC2A4\uB97C \uC790\uB3D9\uC73C\uB85C \uC2A4\uCF00\uC904\uB9C1\uD569\uB2C8\uB2E4. \uBA40\uD2F0\uCF54\uC5B4 \uC7A0\uC7AC\uB825\uC744 \uB354 \uD65C\uC6A9\uD558\uB824\uBA74 \uBA40\uD2F0\uC2A4\uB808\uB529/\uBA40\uD2F0\uD0DC\uC2A4\uD06C \uD504\uB85C\uADF8\uB798\uBC0D(RTOS \uD0DC\uC2A4\uD06C, LVGL \uBA40\uD2F0\uC2A4\uB808\uB4DC \uB80C\uB354\uB9C1 \uB4F1)\uC73C\uB85C \uB354 \uB192\uC740 \uC131\uB2A5\uC744 \uAD6C\uD604\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n- **API \uD638\uD658\uC131 \uBCF4\uC7A5**: \uB300\uBD80\uBD84\uC758 API\uB294 \uC774\uC804 \uBC84\uC804\uACFC \uD638\uD658\uB418\uBBC0\uB85C \uAE30\uC874 \uD504\uB85C\uC81D\uD2B8\uB97C \uC6D0\uD65C\uD558\uAC8C \uC5C5\uADF8\uB808\uC774\uB4DC\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC0C8 \uD558\uB4DC\uC6E8\uC5B4\uC640 \uC0C8 \uB4DC\uB77C\uC774\uBC84 \uC811\uADFC \uBC29\uC2DD\uB3C4 \uC774\uC804\uACFC \uC77C\uAD00\uB429\uB2C8\uB2E4.\\n- **\uB354 \uB113\uC740 \uCC3D\uC758\uC801 \uACF5\uAC04**: LVGL \uB4C0\uC5BC \uBC84\uC804, \uD48D\uBD80\uD55C \uC8FC\uBCC0 \uC7A5\uCE58 \uBC0F \uAC8C\uC784 \uC560\uD50C\uB9AC\uCF00\uC774\uC158\uC744 \uD65C\uC6A9\uD574 \uB354 \uD601\uC2E0\uC801\uC778 \uBC29\uC2DD\uC744 \uC2DC\uB3C4\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uACF5\uC2DD \uC608\uC81C\uB97C \uBC14\uB85C \uC7AC\uC0AC\uC6A9\uD558\uAC70\uB098 \uC0C8 \uB4DC\uB77C\uC774\uBC84\uC640 \uAE30\uB2A5\uC744 \uAE30\uBC18\uC73C\uB85C \uC790\uCCB4 \uC560\uD50C\uB9AC\uCF00\uC774\uC158\uC744 \uAC1C\uBC1C\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n- **\uB300\uADDC\uBAA8 \uB9AC\uD329\uD130\uB9C1 \uBD88\uD544\uC694**: \uC774\uBBF8 T5AI \uAE30\uBC18 \uD504\uB85C\uC81D\uD2B8\uAC00 \uC788\uB2E4\uBA74 v1.5.0\uC73C\uB85C \uC5C5\uADF8\uB808\uC774\uB4DC\uD55C \uB4A4 \uB300\uADDC\uBAA8 \uCF54\uB4DC \uB9AC\uD329\uD130\uB9C1\uC744 \uC9C4\uD589\uD560 \uD544\uC694\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4.\\n- **\uAD8C\uC7A5 \uC0AC\uD56D**: \uBA40\uD2F0\uCF54\uC5B4\uC640 \uC0C8 \uD558\uB4DC\uC6E8\uC5B4 \uAE30\uB2A5\uC744 \uCD5C\uB300\uD55C \uD65C\uC6A9\uD558\uB824\uBA74 RTOS \uD0DC\uC2A4\uD06C, \uC138\uB9C8\uD3EC\uC5B4, \uD050 \uBC0F \uAE30\uD0C0 \uBA40\uD2F0\uCF54\uC5B4 \uB3D9\uC2DC \uD504\uB85C\uADF8\uB798\uBC0D \uBC29\uC2DD\uC744 \uD559\uC2B5\uD558\uACE0 \uC0AC\uC6A9\uD558\uC138\uC694. \uACF5\uC2DD \uBA40\uD2F0\uCF54\uC5B4 \uC608\uC81C\uC640 \uBB38\uC11C\uB97C \uCC38\uACE0\uD558\uC138\uC694.\\n\\n> **SMP \uC544\uD0A4\uD14D\uCC98\uC5D0 \uC9C8\uBB38\uC774\uB098 \uC758\uBB38\uC774 \uC788\uB098\uC694? GitHub\uC5D0\uC11C Issue\uB97C \uB4F1\uB85D\uD574 \uB17C\uC758\uD574 \uC8FC\uC138\uC694: https://github.com/tuya/TuyaOpen/issues**\\n\\n\\n# \u{1F929} \uBA40\uD2F0\uBAA8\uB2EC Tuya \uC624\uD508 \uC18C\uC2A4 Pocket \uB514\uBC14\uC774\uC2A4 \uACF5\uAC1C(\uC900\uBE44 \uC911)\\n![Tuya T5 Pocket](https://images.tuyacn.com/fe-static/docs/img/18ee541f-6e1c-49e5-af58-45797ac1eb82.png)\\nT5 Pocket\uC740 AI \uC74C\uC131 \uBC0F \uBE44\uC804 \uB300\uADDC\uBAA8 \uC5B8\uC5B4 \uBAA8\uB378(LLM) \uAE30\uB2A5\uC744 \uC704\uD55C \uD734\uB300\uC6A9 \uD578\uB4DC\uD5EC\uB4DC \uB514\uBC14\uC774\uC2A4\uC785\uB2C8\uB2E4. T5\uC758 \uC804\uCCB4 \uAE30\uB2A5\uACFC \uD558\uB4DC\uC6E8\uC5B4 \uC778\uD130\uD398\uC774\uC2A4\uB97C \uD65C\uC6A9\uD569\uB2C8\uB2E4. **\uC18C\uD504\uD2B8\uC6E8\uC5B4\uC640 \uD558\uB4DC\uC6E8\uC5B4 \uC624\uD508 \uC18C\uC2A4 \uBC0F \uD29C\uD1A0\uB9AC\uC5BC \uC790\uB8CC\uB97C \uC801\uADF9\uC801\uC73C\uB85C \uC900\uBE44\uD558\uACE0 \uC788\uC2B5\uB2C8\uB2E4.** \uACC4\uC18D \uC9C0\uCF1C\uBD10 \uC8FC\uC138\uC694!\\n- \uACC4\uC18D \uC5C5\uB370\uC774\uD2B8\uB418\uB294 \uCF54\uB4DC\uB294 \uB2E4\uC74C\uC5D0\uC11C \uD655\uC778\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4: https://github.com/tuya/TuyaOpen/tree/master/apps/tuya_t5_pocket\\n\\n\\n\\n# \u{1F3A8} \uADF8\uB798\uD53D \uBC0F \uB514\uC2A4\uD50C\uB808\uC774: \uB4C0\uC5BC \uBC84\uC804 \uBCD1\uB82C \uC9C0\uC6D0\uACFC \uAC8C\uC784 \uACBD\uD5D8 \uC5C5\uADF8\uB808\uC774\uB4DC\\n\\n**TuyaOpen\uC758 \uD601\uC2E0:**\\n- **LVGL \uB4C0\uC5BC \uBC84\uC804 \uC9C0\uC6D0**: \uC5C5\uACC4 \uCD5C\uCD08\uB85C LVGL V8\uACFC V9\uB97C \uB3D9\uC2DC\uC5D0 \uC9C0\uC6D0\uD569\uB2C8\uB2E4. \uAC1C\uBC1C\uC790\uB294 \uD504\uB85C\uC81D\uD2B8 \uC694\uAD6C \uC0AC\uD56D\uC5D0 \uB530\uB77C \uC720\uC5F0\uD558\uAC8C \uC804\uD658\uD560 \uC218 \uC788\uC5B4 \uBC84\uC804 \uD638\uD658\uC131 \uBB38\uC81C\uB97C \uC904\uC77C \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n- **\uD074\uB798\uC2DD \uAC8C\uC784 \uCEEC\uB809\uC158**: \uC815\uC131\uC2A4\uB7FD\uAC8C \uC81C\uC791\uD55C LVGL \uAC8C\uC784 \uC560\uD50C\uB9AC\uCF00\uC774\uC158\uC5D0 2048, \uD654\uB8FD\uB2E4\uC624, Match-3 \uB4F1 \uD074\uB798\uC2DD \uAC8C\uC784\uC774 \uB0B4\uC7A5\uB418\uC5B4 \uB514\uBC14\uC774\uC2A4\uB97C \uC989\uC2DC \uAC8C\uC784 \uCF58\uC194\uB85C \uBC14\uAFC0 \uC218 \uC788\uC2B5\uB2C8\uB2E4! LVGL \uAC8C\uC784 \uC560\uD50C\uB9AC\uCF00\uC774\uC158 \uAC1C\uBC1C\uC5D0 \uC911\uC694\uD55C \uAE30\uC5EC\uB97C \uD55C [HangYongmao](https://github.com/HangYongmao)\uC5D0\uAC8C \uD2B9\uBCC4\uD788 \uAC10\uC0AC\uB4DC\uB9BD\uB2C8\uB2E4.\\n\\n# \u{1F916} \uBE44\uC804 \uBC0F \uB0A0\uC528 \uC11C\uBE44\uC2A4\\n**\uC9C0\uB2A5\uD615 \uAE30\uB2A5\uC758 \uB3CC\uD30C\uAD6C:**\\n- **\uCE74\uBA54\uB77C \uD074\uB77C\uC6B0\uB4DC \uD1B5\uD569**: \uC0C8\uB85C\uC6B4 `camera_demo` \uC608\uC81C\uB97C \uD1B5\uD574 \uCE74\uBA54\uB77C\uB97C Tuya Cloud\uC5D0 \uC27D\uAC8C \uD1B5\uD569\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC5EC\uB7EC \uBE44\uB514\uC624 \uC13C\uC11C \uB4DC\uB77C\uC774\uBC84\uB97C \uC9C0\uC6D0\uD558\uBA70 AI \uBE44\uC804 \uAE30\uB2A5\uC744 \uD06C\uAC8C \uD5A5\uC0C1\uD588\uC2B5\uB2C8\uB2E4.\\n    - \uB370\uBAA8: [camera_demo \uC608\uC81C \uC18C\uC2A4 \uCF54\uB4DC](https://github.com/tuya/TuyaOpen/tree/master/examples/peripherals/video) \u2014\u2014 \uCE74\uBA54\uB77C DVP \uCD9C\uB825 \uBC0F \uB80C\uB354\uB9C1\uC73C\uB85C \uBE60\uB974\uAC8C \uC2DC\uC791\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n> **\uCE74\uBA54\uB77C AI \uBAA8\uB2EC\uB9AC\uD2F0 \uAE30\uB2A5\uACFC API \uD1B5\uD569\uC744 \uAC1C\uBC1C \uC911\uC785\uB2C8\uB2E4. \uACE7 \uC0C8\uB85C\uC6B4 \uBE44\uB514\uC624 \uBAA8\uB2EC\uB9AC\uD2F0 API\uB97C \uACF5\uAC1C\uD560 \uC608\uC815\uC774\uB2C8 \uAE30\uB300\uD574 \uC8FC\uC138\uC694!**\\n- **\uB0A0\uC528 \uC11C\uBE44\uC2A4 \uD1B5\uD569**: `weather_get_demo` \uC608\uC81C\uB85C \uB2E4\uC591\uD55C \uD615\uC2DD\uC758 \uB0A0\uC528 \uC815\uBCF4\uB97C \uC27D\uAC8C \uAC00\uC838\uC62C \uC218 \uC788\uC5B4 \uC2A4\uB9C8\uD2B8 \uC2DC\uB098\uB9AC\uC624 \uAC1C\uBC1C\uC774 \uAC04\uB2E8\uD574\uC9D1\uB2C8\uB2E4.\\n    - \uB370\uBAA8: [weather_get_demo \uC608\uC81C \uC18C\uC2A4 \uCF54\uB4DC](https://github.com/tuya/TuyaOpen/tree/master/apps/tuya_cloud/weather_get_demo) \u2014\u2014 \uB0A0\uC528 \uC815\uBCF4 \uAC00\uC838\uC624\uAE30\uB85C \uBE60\uB974\uAC8C \uC2DC\uC791\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n\\n# \u{1F527} \uC8FC\uBCC0 \uC7A5\uCE58 \uBC0F \uB4DC\uB77C\uC774\uBC84: \uC885\uD569\uC801\uC778 \uAE30\uB2A5\uACFC \uBB34\uD55C\uD55C \uCC3D\uC758\uC131\\n**\uC885\uD569 \uD558\uB4DC\uC6E8\uC5B4 \uC9C0\uC6D0 \uC5C5\uADF8\uB808\uC774\uB4DC:**\\n- **\uBE44\uB514\uC624 \uCEA1\uCC98\uC758 \uC0C8\uB85C\uC6B4 \uC218\uC900**: T5AI DVP \uB2E4\uC911 \uBE44\uB514\uC624 \uC13C\uC11C \uB4DC\uB77C\uC774\uBC84\uB97C \uD1B5\uD574 \uBE44\uB514\uC624 \uCEA1\uCC98 \uBC0F \uCC98\uB9AC \uAE30\uB2A5\uC744 \uD55C \uB2E8\uACC4 \uB192\uC600\uC2B5\uB2C8\uB2E4.\\n- **IR \uB9AC\uBAA8\uCEE8 \uC804 \uBC94\uC704 \uC9C0\uC6D0**: IR \uC801\uC678\uC120 \uB9AC\uBAA8\uCEE8 \uC218\uC2E0 \uBC0F \uC1A1\uC2E0 \uC608\uC81C\uB97C \uC81C\uACF5\uD574 \uB2E4\uC591\uD55C \uC801\uC678\uC120 \uB9AC\uBAA8\uCEE8 \uC2DC\uB098\uB9AC\uC624\uB97C \uC9C0\uC6D0\uD558\uACE0 \uB514\uBC14\uC774\uC2A4\uB97C \uB354 \uC2A4\uB9C8\uD2B8\uD558\uAC8C \uB9CC\uB4ED\uB2C8\uB2E4.\\n- **\uCC3D\uC758\uC801\uC778 \uC870\uBA85 \uD65C\uC6A9**: ws2812 \uBC0F \uAE30\uD0C0 RGB LED \uB4DC\uB77C\uC774\uBC84\uC640 \uD48D\uBD80\uD55C \uC870\uBA85 \uC81C\uC5B4 \uAE30\uB2A5\uC73C\uB85C \uBB34\uD55C\uD55C \uCC3D\uC758\uC131\uC744 \uC2E4\uD604\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n---\\n\\n**\u{1F3AF} \uC774\uBC88 \uC5C5\uB370\uC774\uD2B8\uB294 \uAE30\uB2A5\uBFD0 \uC544\uB2C8\uB77C \uAC00\uB2A5\uC131\uB3C4 \uAC00\uC838\uC654\uC2B5\uB2C8\uB2E4. \uBAA8\uB4E0 \uC0C8 \uAE30\uB2A5\uC740 \uC548\uC815\uC131\uACFC \uC2E0\uB8B0\uC131\uC744 \uBCF4\uC7A5\uD558\uAE30 \uC704\uD574 \uD300\uC774 \uBC18\uBCF5\uC801\uC73C\uB85C \uD14C\uC2A4\uD2B8\uD558\uACE0 \uCD5C\uC801\uD654\uD588\uC2B5\uB2C8\uB2E4. \uAC1C\uBC1C\uC790 \uC5EC\uB7EC\uBD84\uC758 \uC9C0\uC6D0\uC5D0 \uAC10\uC0AC\uB4DC\uB9AC\uBA70 \uD568\uAED8 \uB354 \uB098\uC740 \uC2A4\uB9C8\uD2B8 \uD558\uB4DC\uC6E8\uC5B4\uC758 \uBBF8\uB798\uB97C \uB9CC\uB4E4\uC5B4 \uAC11\uC2DC\uB2E4!**"},{"id":"/2025/09/19/vibe-coding-accelerate-tuyaopen-development","metadata":{"permalink":"/ko/blog/2025/09/19/vibe-coding-accelerate-tuyaopen-development","editUrl":"https://github.com/Tuya-Community/TuyaOpen.io/edit/master/i18n/ko/docusaurus-plugin-content-blog/2025-09-19-vibe-coding-accelerate-tuyaopen-development.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2025-09-19-vibe-coding-accelerate-tuyaopen-development.md","title":"AI \uCF54\uB529\uC73C\uB85C TuyaOpen \uAC1C\uBC1C \uAC00\uC18D\uD558\uAE30","description":"\uAC1C\uC694","date":"2025-09-19T00:00:00.000Z","tags":[{"inline":false,"label":"AI","permalink":"/ko/blog/tags/AI","description":"AI \uAD00\uB828 \uD29C\uD1A0\uB9AC\uC5BC, \uC6CC\uD06C\uD50C\uB85C\uC640 \uC81C\uD488 \uC5C5\uB370\uC774\uD2B8"},{"inline":false,"label":"TuyaOpen","permalink":"/ko/blog/tags/TuyaOpen","description":"TuyaOpen \uD50C\uB7AB\uD3FC \uBC0F \uAC1C\uBC1C \uAD00\uB828 \uCF58\uD150\uCE20"},{"inline":false,"label":"\uAC1C\uBC1C","permalink":"/ko/blog/tags/Development","description":"\uAC1C\uBC1C\uC790 \uAC00\uC774\uB4DC, \uAD6C\uD604 \uB178\uD2B8\uC640 \uC5D4\uC9C0\uB2C8\uC5B4\uB9C1 \uC2E4\uCC9C"},{"inline":false,"label":"\uD29C\uD1A0\uB9AC\uC5BC","permalink":"/ko/blog/tags/Tutorial","description":"\uB2E8\uACC4\uBCC4 \uD29C\uD1A0\uB9AC\uC5BC \uBC0F \uD559\uC2B5 \uCF58\uD150\uCE20"}],"readingTime":8.2,"hasTruncateMarker":true,"authors":[{"name":"Tuya","title":"TuyaOpen \uBAA8\uB4E0 \uC720\uC9C0\uAD00\uB9AC\uC790","url":"https://github.com/tuya/tuya-open","socials":{"github":"https://github.com/tuya","youtube":"https://youtube.com/@tuyasmart5602","website":"https://tuyaopen.ai"},"imageURL":"https://avatars.githubusercontent.com/u/73523937?v=4","key":"tuya","page":null}],"frontMatter":{"title":"AI \uCF54\uB529\uC73C\uB85C TuyaOpen \uAC1C\uBC1C \uAC00\uC18D\uD558\uAE30","authors":["tuya"],"tags":["AI","TuyaOpen","Development","Tutorial"]},"unlisted":false,"prevItem":{"title":"V1.5.0 \uB9B4\uB9AC\uC2A4","permalink":"/ko/blog/2025/09/22/v1.5.0-release"},"nextItem":{"title":"100\uC77C AI \uAC01\uC131 \uACC4\uD68D: \uBBF8\uB798\uC758 AI \uD558\uB4DC\uC6E8\uC5B4 \uB9CC\uB4E4\uAE30","permalink":"/ko/blog/8-8-online-contest"}},"content":"## \uAC1C\uC694\\n\\nAI \uAE30\uC220\uC774 \uBE60\uB974\uAC8C \uBC1C\uC804\uD558\uB294 \uC624\uB298\uB0A0, \uC6B0\uB9AC \uC8FC\uBCC0\uC758 \uD3C9\uBC94\uD55C \uBB3C\uAC74\uB3C4 \uC0C8\uB86D\uAC8C \uC815\uC758\uD558\uACE0 \uC9C0\uB2A5\uC744 \uBD80\uC5EC\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC624\uB298\uC740 Tuya T5AI-Board \uAC1C\uBC1C \uBCF4\uB4DC\uB97C \uC0AC\uC6A9\uD574 **\uB9DE\uCDA4\uD615 \uC2A4\uB9C8\uD2B8 \uB370\uC2A4\uD06C\uD1B1 \uCC57\uBD07**\uC744 \uB9CC\uB4DC\uB294 \uD765\uBBF8\uB85C\uC6B4 \uBC29\uBC95\uC744 \uC0B4\uD3B4\uBD05\uB2C8\uB2E4.\\n\\n{/* truncate */}\\n\\n\uAC15\uB825\uD55C TuyaOpen \uD504\uB808\uC784\uC6CC\uD06C\uC640 Tuya \uC9C0\uB2A5\uD615 Agent\uC758 \uC9C0\uC6D0\uC744 \uBC1B\uC73C\uBA74 \uAC1C\uBC1C \uACBD\uD5D8\uC774 \uC804\uD600 \uC5C6\uB294 \uCD08\uBCF4\uC790\uB3C4 AI Coding \uB3C4\uAD6C\uB85C \\"\uC81C\uB85C \uCF54\uB4DC\\" \uAC1C\uBC1C\uC744 \uC27D\uAC8C \uC2E4\uD604\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uB300\uD654\uC758 \uAC10\uC815 \uBCC0\uD654\uB97C \uBBFC\uAC10\uD558\uAC8C \uD3EC\uCC29\uD560 \uBFD0 \uC544\uB2C8\uB77C \uC2E4\uC2DC\uAC04\uC73C\uB85C \uD574\uB2F9 \uC774\uBBF8\uC9C0\uB97C \uD45C\uC2DC\uD574 \uAC10\uC815\uC758 \uAE34\uC7A5\uAC10\uC744 \uC804\uB2EC\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uB354 \uB180\uB77C\uC6B4 \uC810\uC740 \uC9E7\uC740 \uC2DC\uAC04 \uC548\uC5D0 \uAC1C\uBC1C \uBCF4\uB4DC\uB97C \uC644\uC804\uD788 \uD50C\uB808\uC774 \uAC00\uB2A5\uD55C \uAC8C\uC784 \uCF58\uC194\uB85C \uBC14\uAFD4 \uCC44\uD305 \uBCF4\uC870 \uB3C4\uAD6C\uC5D0\uC11C \uC5D4\uD130\uD14C\uC778\uBA3C\uD2B8 \uB514\uBC14\uC774\uC2A4\uB85C \uC27D\uAC8C \uC804\uD658\uD560 \uC218 \uC788\uB2E4\uB294 \uAC83\uC785\uB2C8\uB2E4.\\n\\n### \uD6A8\uACFC \uC774\uBBF8\uC9C0\\n\\n| \uCD08\uAE30 \uD6A8\uACFC | \uCD5C\uC885 \uD6A8\uACFC |\\n| --- | --- |\\n| <img alt=\\"\uCD08\uAE30 \uD6A8\uACFC\\" src=\\"https://images.tuyacn.com/content-platform/hestia/175609316343564ed226c.png\\" width=\\"640\\"  /> |<img alt=\\"\uCD5C\uC885 \uD6A8\uACFC\\" src=\\"https://images.tuyacn.com/content-platform/hestia/1756101670562a63c3c0a.png\\" width=\\"700\\"  />|\\n\\n### TuyaOpen \uC18C\uAC1C\\n\\nTuyaOpen\uC740 \uC131\uC219\uD55C \uC0C1\uC6A9 IoT \uC2DC\uC2A4\uD15C\uC778 TuyaOS\uB97C \uAE30\uBC18\uC73C\uB85C \uAD6C\uCD95\uB41C AIoT \uC0B0\uC5C5\uC6A9 \uC624\uD508 \uC18C\uC2A4 \uAC1C\uBC29\uD615 \uAC1C\uBC1C \uD504\uB808\uC784\uC6CC\uD06C\uC785\uB2C8\uB2E4. \uD06C\uB85C\uC2A4 \uD50C\uB7AB\uD3FC \uD638\uD658\uC131, \uD06C\uB85C\uC2A4 \uC2DC\uC2A4\uD15C \uC9C0\uC6D0, \uBAA8\uB4C8\uC131, \uAC15\uB825\uD55C \uBCF4\uC548 \uC900\uC218 \uB4F1 \uD575\uC2EC \uAE30\uB2A5\uC744 \uACC4\uC2B9\uD588\uC73C\uBA70, \uC804 \uC138\uACC4 1\uC5B5 \uB300\uAC00 \uB118\uB294 \uB514\uBC14\uC774\uC2A4 \uBC30\uD3EC\uC640 \uC218\uBC31\uB9CC \uBA85\uC758 \uC0AC\uC6A9\uC790\uB85C \uAC80\uC99D\uB418\uC5C8\uC2B5\uB2C8\uB2E4.\\n\\nTuyaOpen\uC740 \uC5E3\uC9C0 \uCE21 AI \uCD94\uB860 \uC5D4\uC9C4\uACFC Tuya \uD074\uB77C\uC6B0\uB4DC \uC9C0\uB2A5\uD615 Agent Hub\uB97C \uD1B5\uD569\uD558\uACE0 \uC5E3\uC9C0-\uD074\uB77C\uC6B0\uB4DC \uC735\uD569 \uBA40\uD2F0\uBAA8\uB2EC AI \uAE30\uB2A5\uC744 \uC9C0\uC6D0\uD569\uB2C8\uB2E4. \uAD6D\uB0B4 \uADDC\uC815\uC744 \uC900\uC218\uD558\uB294 \uB300\uADDC\uBAA8 \uBAA8\uB378(DeepSeek, Tongyi Qianwen, Doubao \uB4F1)\uC744 \uC6D0\uD65C\uD558\uAC8C \uD638\uCD9C\uD558\uAC70\uB098 \uC138\uACC4\uC801\uC778 AI \uC11C\uBE44\uC2A4(ChatGPT, Claude, Gemini \uB4F1)\uC5D0 \uC720\uC5F0\uD558\uAC8C \uC5F0\uACB0\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uB2E4\uC591\uD55C \uB3C4\uAD6C \uC0DD\uD0DC\uACC4\uB97C \uD1B5\uD574 \uD14D\uC2A4\uD2B8 \uBC0F \uC74C\uC131 \uB300\uD654, \uC774\uBBF8\uC9C0 \uC0DD\uC131, \uBE44\uB514\uC624 \uC0DD\uC131 \uB4F1 \uC5EC\uB7EC AI \uAE30\uB2A5\uC744 \uAD6C\uD604\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n## \uD558\uB4DC\uC6E8\uC5B4 \uC18C\uAC1C\\n\\n\uBA3C\uC800 [T5AI-Board \uAC1C\uBC1C \uBCF4\uB4DC](https://developer.tuya.com/cn/docs/iot-device-dev/T5-E1-IPEX-development-board?id=Ke9xehig1cabj)\uC758 \uAD00\uB828 \uC815\uBCF4\uB97C \uD655\uC778\uD558\uC138\uC694.\\n\\n\uAC1C\uBC1C \uBCF4\uB4DC\uC758 \uC0C1\uC138 \uC0AC\uC591\uC740 \uB2E4\uC74C \uD45C\uB97C \uCC38\uC870\uD558\uC138\uC694.\\n\\n| \uB514\uBC14\uC774\uC2A4 | \uB9E4\uAC1C\uBCC0\uC218 |\\n|----------|---------------------|\\n| T5AI-Board | \uBA54\uC778 \uC81C\uC5B4 \uBAA8\uB4C8: T5-E1-IPEX \uBAA8\uB4C8 ARMv8-M Star(M33F) @480MHz, 16 KB ITCM + 16 KB DTCM, 8 MB SiP Flash, 16 MB SiP PSRAM, 640 KB Share SRAM |\\n| \uD654\uBA74 | RGB565 \uD130\uCE58\uC2A4\uD06C\uB9B0, 480 x 320 \uD53D\uC140, \uB514\uC2A4\uD50C\uB808\uC774 \uB4DC\uB77C\uC774\uBC84 \uCE69: ILI9488, \uD130\uCE58 \uB4DC\uB77C\uC774\uBC84 \uCE69: GT1151 |\\n\\n![T5AI-Board \uAC1C\uBC1C \uBCF4\uB4DC.png](https://images.tuyacn.com/content-platform/hestia/17561085897400828f8e3.png)\\n\\n## \uC800\uC7A5\uC18C \uD074\uB860 \uBC0F \uCEF4\uD30C\uC77C/\uD50C\uB798\uC2F1\\n\\n\uBE0C\uB77C\uC6B0\uC800\uC5D0\uC11C **TuyaOpen.ai**\uB97C \uAC80\uC0C9\uD574 TuyaOpen Git \uC800\uC7A5\uC18C\uC5D0 \uC811\uC18D\uD558\uACE0 \uC544\uB798\uC640 \uAC19\uC774 \uC800\uC7A5\uC18C \uB9C1\uD06C\uB97C \uBCF5\uC0AC\uD558\uC138\uC694. TuyaOpen SDK\uB97C \uB85C\uCEEC \uCEF4\uD4E8\uD130\uC5D0 \uD074\uB860\uD55C \uB2E4\uC74C AI \uCC57\uBD07 \uD504\uB85C\uC81D\uD2B8 `your_chat_bot`\uC744 \uB300\uD654\uC5D0 \uCD94\uAC00\uD558\uBA74 AI Coding \uB3C4\uAD6C\uAC00 \uCEF4\uD30C\uC77C\uACFC \uD50C\uB798\uC2F1\uC744 \uC790\uB3D9\uC73C\uB85C \uC2E4\uD589\uD569\uB2C8\uB2E4.\\n\\n- GitHub \uC800\uC7A5\uC18C: https://github.com/tuya/TuyaOpen\\n- Gitee \uC800\uC7A5\uC18C: https://gitee.com/tuya-open/TuyaOpen\\n\\n### \uD504\uB86C\uD504\uD2B8 \uD15C\uD50C\uB9BF\\n\\n\uB2E4\uC74C \uD15C\uD50C\uB9BF\uC744 \uCC38\uACE0\uD574 AI Coding \uB3C4\uAD6C\uAC00 \uCEF4\uD30C\uC77C \uBC0F \uD50C\uB798\uC2F1\uC744 \uC2E4\uD589\uD558\uB3C4\uB85D \uC548\uB0B4\uD558\uB294 \uD504\uB86C\uD504\uD2B8\uB97C \uC791\uC131\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n```\\nHelp me compile and flash this project\\nSet up compilation environment\\nHelp me compile and flash this project, compilation and flashing methods refer to readme documentation and the links below\\nEnvironment setup\\nhttps://tuyaopen.ai/zh/docs/quick-start/enviroment-setup\\nCompilation:\\nhttps://tuyaopen.ai/zh/docs/quick-start/project-compilation\\nFlashing:\\nhttps://tuyaopen.ai/zh/docs/quick-start/firmware-burning\\n```\\n\\n![\uD504\uB86C\uD504\uD2B8 \uD15C\uD50C\uB9BF.png](https://images.tuyacn.com/content-platform/hestia/1756191238cfcb3b4eb39.png)\\n\\n\\n## \uAC1C\uBC1C \uBCF4\uB4DC \uC778\uC99D\\n\\n\uD50C\uB798\uC2F1\uC744 \uC644\uB8CC\uD55C \uD6C4\uC5D0\uB3C4 **Tuya** \uC571\uC5D0\uC11C \uB514\uBC14\uC774\uC2A4\uB97C \uCC3E\uC744 \uC218 \uC5C6\uB2E4\uBA74 \uAC1C\uBC1C \uBCF4\uB4DC\uB97C \uC778\uC99D\uD574\uC57C \uD569\uB2C8\uB2E4.\\n\\n`your_chat_bot` \uD504\uB85C\uC81D\uD2B8\uB97C \uC5F4\uACE0 `apps/tuya.ai/your_chat_bot/include/tuya_config.h` \uD30C\uC77C\uC5D0\uC11C \uB2E4\uC74C \uB9E4\uAC1C\uBCC0\uC218\uB97C \uC124\uC815\uD558\uC138\uC694.\\n- `TUYA_OPENSDK_UUID`: UUID\uB294 \uBB34\uB8CC\uB85C \uBC1C\uAE09\uBC1B\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC544\uB798 QR \uCF54\uB4DC\uB97C \uC2A4\uCE94\uD574 \uADF8\uB8F9\uC5D0 \uCC38\uC5EC\uD558\uACE0 Tuya \uC9C1\uC6D0\uC5D0\uAC8C \uBB38\uC758\uD558\uC138\uC694.\\n- `TUYA_OPENSDK_AUTHKEY`: Authkey\uB294 \uBB34\uB8CC\uB85C \uBC1C\uAE09\uBC1B\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uC544\uB798 QR \uCF54\uB4DC\uB97C \uC2A4\uCE94\uD574 \uADF8\uB8F9\uC5D0 \uCC38\uC5EC\uD558\uACE0 Tuya \uC9C1\uC6D0\uC5D0\uAC8C \uBB38\uC758\uD558\uC138\uC694.\\n\\n<img alt=\\"\uADF8\uB8F9 QR \uCF54\uB4DC\\" src=\\"https://images.tuyacn.com/content-platform/hestia/1756115540e394937a07f.png\\" width=\\"300\\"  />\\n\\n![UUID.png](https://images.tuyacn.com/content-platform/hestia/17561097834516e414c77.png)\\n\\n\uC0C1\uC138\uD55C \uC778\uC99D \uC808\uCC28\uB294 [\uB514\uBC14\uC774\uC2A4 \uC778\uC99D](https://tuyaopen.ai/zh/docs/quick-start/equipment-authorization)\uC744 \uCC38\uC870\uD558\uC138\uC694.\\n\\n:::info\\n\uAD6C\uB9E4\uD55C T5 \uBAA8\uB4C8\uC5D0 TuyaOpen \uC778\uC99D \uCF54\uB4DC\uAC00 \uC774\uBBF8 \uD50C\uB798\uC2F1\uB418\uC5B4 \uC788\uB2E4\uBA74 UUID\uC640 Authkey\uB97C \uC785\uB825\uD560 \uD544\uC694\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4.\\n:::\\n\\n## \uC774\uBBF8\uC9C0 \uC900\uBE44\\n\\n\uC774\uBBF8\uC9C0 \uC0DD\uC131 \uC6F9\uC0AC\uC774\uD2B8\uC5D0\uC11C 7\uAC00\uC9C0 \uAC10\uC815\uC778 \\"happy, angry, sad, shocked, confused, like, thinking\\"\uC5D0 \uD574\uB2F9\uD558\uB294 \uC774\uBBF8\uC9C0\uB97C \uC0DD\uC131\uD55C \uD6C4 \uC774\uBBF8\uC9C0 \uD53D\uC140\uC744 **240 x 240**\uC73C\uB85C \uBCC0\uACBD\uD558\uC138\uC694. T5 \uAC1C\uBC1C \uBCF4\uB4DC\uC758 Flash \uACF5\uAC04\uC774 \uC81C\uD55C\uB418\uC5B4 \uC788\uC5B4 \uD070 \uC774\uBBF8\uC9C0\uB294 \uB354 \uB9CE\uC740 Flash \uACF5\uAC04\uC744 \uCC28\uC9C0\uD558\uBBC0\uB85C \uC774\uBBF8\uC9C0 \uD06C\uAE30\uB97C \uC904\uC5EC\uC57C \uD569\uB2C8\uB2E4.\\n\\n\uD604\uC7AC Tuya Agent\uB294 \uB300\uD654\uC5D0 \uB530\uB77C \uCD5C\uB300 21\uAC1C\uC758 \uAC10\uC815 \uAC12\uC744 \uBC18\uD658\uD569\uB2C8\uB2E4. \uB2E4\uC74C \uD45C\uB97C \uCC38\uC870\uD558\uC138\uC694.\\n\\n| \uC774\uBAA8\uC9C0 | \uD45C\uD604 | \uC774\uBAA8\uC9C0 | \uD45C\uD604 | \uC774\uBAA8\uC9C0 | \uD45C\uD604 |\\n|-------|------------|-------|------------|-------|------------|\\n| \u{1F636} | \uC911\uB9BD | \u{1F633} | \uB2F9\uD669 | \u{1F60C} | \uD3B8\uC548\uD568 |\\n| \u{1F642} | \uD589\uBCF5 | \u{1F62F} | \uB180\uB78C | \u{1F924} | \uB9DB\uC788\uC74C |\\n| \u{1F606} | \uC6C3\uC74C | \u{1F631} | \uCDA9\uACA9 | \u{1F618} | \uD0A4\uC2A4 |\\n| \u{1F602} | \uC7AC\uBBF8\uC788\uC74C | \u{1F914} | \uC0DD\uAC01 \uC911 | \u{1F60F} | \uC790\uC2E0\uAC10 |\\n| \u{1F614} | \uC2AC\uD514 | \u{1F609} | \uC719\uD06C | \u{1F634} | \uC878\uB9BC |\\n| \u{1F620} | \uD654\uB0A8 | \u{1F60E} | \uBA4B\uC9D0 | \u{1F61C} | \uC7A5\uB09C\uC2A4\uB7EC\uC6C0 |\\n| \u{1F62D} | \uC6B8\uC74C | \u{1F644} | \uD63C\uB780 | \u{1F60D} | \uC0AC\uB791\uC2A4\uB7EC\uC6C0 |\\n\\n## \uD504\uB85C\uC81D\uD2B8\uC5D0 \uC774\uBBF8\uC9C0 \uCD94\uAC00\\n\\n\uC784\uBCA0\uB514\uB4DC \uAC1C\uBC1C\uC5D0\uC11C \uD654\uBA74\uC5D0 \uC774\uBBF8\uC9C0\uB97C \uD45C\uC2DC\uD558\uB294 \uC791\uC5C5\uC740 \uC77C\uBC18\uC801\uC73C\uB85C \uB9E4\uC6B0 \uBCF5\uC7A1\uD569\uB2C8\uB2E4. \uCF54\uB4DC\uB97C \uC9C1\uC811 \uC791\uC131\uD560 \uB54C\uB294 \uC774\uBBF8\uC9C0\uB97C \uACE0\uC815 \uD06C\uAE30\uB85C \uC790\uB974\uACE0 C \uBC30\uC5F4 \uD615\uC2DD\uC73C\uB85C \uBCC0\uD658\uD574\uC57C \uD558\uBA70 \uD654\uBA74 \uD06C\uAE30\uC640 \uC774\uBBF8\uC9C0 \uC800\uC7A5 \uC704\uCE58 \uB4F1 \uC138\uBD80 \uC0AC\uD56D\uB3C4 \uACE0\uB824\uD574\uC57C \uD569\uB2C8\uB2E4.\\n\\n\uB530\uB77C\uC11C AI Coding \uB3C4\uAD6C\uB97C \uC0AC\uC6A9\uD560 \uB54C\uB294 \uD504\uB86C\uD504\uD2B8 \uC124\uBA85\uC774 \uAD6C\uCCB4\uC801\uC774\uACE0 \uC790\uC138\uD560\uC218\uB85D \uCD5C\uC885 \uACB0\uACFC\uAC00 \uC815\uD655\uD558\uACE0 \uAE30\uB300\uC5D0 \uAC00\uAE4C\uC6CC\uC9D1\uB2C8\uB2E4. \uCC38\uACE0 \uC0AC\uB840, \uCF54\uB4DC \uC2A4\uB2C8\uD3AB, \uC694\uAD6C \uC0AC\uD56D \uBB38\uC11C\uAC00 \uC788\uB2E4\uBA74 \uB3C4\uAD6C\uC5D0 \uD568\uAED8 \uC81C\uACF5\uD558\uC138\uC694. \uAC1C\uBC1C\uC5D0 \uD544\uC694\uD55C \uAE30\uC220 \uC138\uBD80 \uC0AC\uD56D\uC744 \uBBF8\uB9AC \uBA85\uD655\uD788 \uD558\uBA74 \uB3C4\uAD6C \uCD9C\uB825\uC758 \uC801\uD569\uC131\uC744 \uB192\uC774\uACE0 \uC774\uD6C4 \uC870\uC815 \uBE44\uC6A9\uC744 \uC904\uC77C \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n\uC608\uB97C \uB4E4\uC5B4 AI\uC5D0 \uD654\uBA74 \uC774\uBBF8\uC9C0 \uD45C\uC2DC \uAE30\uB2A5\uC744 \uAD6C\uD604\uD558\uB3C4\uB85D \uC694\uCCAD\uD560 \uB54C\uB294 \uBA3C\uC800 \uC774\uBBF8\uC9C0\uB97C C \uBC30\uC5F4 \uD615\uC2DD\uC73C\uB85C \uBCC0\uD658\uD558\uB3C4\uB85D \uBA85\uC2DC\uD574\uC57C \uD569\uB2C8\uB2E4. \uADF8\uB807\uC9C0 \uC54A\uC73C\uBA74 AI\uAC00 \uD30C\uC77C \uACBD\uB85C \uD638\uCD9C\uC744 \uC0AC\uC6A9\uD574 PNG \uB610\uB294 JPG \uC774\uBBF8\uC9C0 \uD30C\uC77C\uC744 \uC9C1\uC811 \uC5F4\uB824\uACE0 \uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uB610\uD55C \uC774\uBBF8\uC9C0 \uC778\uCF54\uB529 \uD615\uC2DD\uC740 RGB565, RGB888 \uB4F1 \uB2E4\uC591\uD569\uB2C8\uB2E4. \uBBF8\uB9AC \uC9C0\uC815\uD558\uC9C0 \uC54A\uC73C\uBA74 \uC5EC\uB7EC \uBC88\uC758 \uB514\uBC84\uAE45 \uCEF4\uD30C\uC77C\uB85C \uD45C\uC2DC \uD6A8\uACFC\uB97C \uAD6C\uD604\uD560 \uC218 \uC788\uB354\uB77C\uB3C4 \uB514\uBC84\uAE45 \uD69F\uC218\uC640 \uBE44\uC6A9\uC774 \uD06C\uAC8C \uB298\uC5B4\uB0A9\uB2C8\uB2E4.\\n\\n### \uC77C\uBC18\uC801\uC778 \uC774\uBBF8\uC9C0 \uC778\uCF54\uB529 \uD615\uC2DD\\n\\n\uB2E4\uC74C \uD45C\uC5D0\uB294 \uC77C\uBC18\uC801\uC778 PNG \uC774\uBBF8\uC9C0 \uC778\uCF54\uB529 \uD615\uC2DD\uC774 \uC815\uB9AC\uB418\uC5B4 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n| \uC2DC\uB098\uB9AC\uC624 | \uC77C\uBC18\uC801\uC778 \uC778\uCF54\uB529 \uD615\uC2DD \uBC0F \uC124\uBA85 |\\n|-----------------|----------------------|\\n| \uB370\uC2A4\uD06C\uD1B1 \uD45C\uC2DC PNG | RGB24: \uD45C\uC900 \uD2B8\uB8E8 \uCEEC\uB7EC, ARGB32: \uD22C\uBA85\uB3C4 \uC9C0\uC6D0 |\\n| \uC784\uBCA0\uB514\uB4DC UI(\uC608: LVGL) | RGB565/Indexed Color: 16\uBE44\uD2B8 \uC0C9\uC0C1 \uB610\uB294 \uC778\uB371\uC2A4 \uC0C9\uC0C1\uC744 \uC0AC\uC6A9\uD574 \uB9AC\uC18C\uC2A4\uB97C \uC808\uC57D |\\n| \uAC8C\uC784/\uBE44\uB514\uC624 \uB80C\uB354\uB9C1 | RGBA8888: \uACE0\uC131\uB2A5 GPU\uB294 \uC77C\uBC18\uC801\uC73C\uB85C 32\uBE44\uD2B8 \uD615\uC2DD\uC744 \uC0AC\uC6A9 |\\n\\n### \uD504\uB86C\uD504\uD2B8 \uD15C\uD50C\uB9BF\\n\\nAI Coding \uB3C4\uAD6C\uAC00 \uC694\uAD6C \uC0AC\uD56D\uC744 \uB354 \uC815\uD655\uD558\uAC8C \uC774\uD574\uD558\uB3C4\uB85D \uD558\uB824\uBA74 \uB300\uC0C1 \uB514\uBC14\uC774\uC2A4\uAC00 \uC9C0\uC6D0\uD558\uB294 \uC774\uBBF8\uC9C0 \uD615\uC2DD, \uD06C\uAE30 \uC0AC\uC591, \uC774\uBBF8\uC9C0 \uC800\uC7A5 \uC704\uCE58 \uB4F1\uC758 \uB9E4\uAC1C\uBCC0\uC218\uB97C \uBA85\uD655\uD558\uAC8C \uC815\uC758\uD574\uC57C \uD569\uB2C8\uB2E4. \uC774\uB807\uAC8C \uD558\uBA74 \uCEF4\uD30C\uC77C \uB514\uBC84\uAE45 \uD69F\uC218\uB97C \uD6A8\uACFC\uC801\uC73C\uB85C \uC904\uC774\uACE0 \uAC1C\uBC1C \uD6A8\uC728\uC744 \uB192\uC77C \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uB2E4\uC74C \uD15C\uD50C\uB9BF\uC744 \uCC38\uACE0\uD558\uC138\uC694.\\n\\n```\\nGoal: Help me add images from the image folder to the your_chat_bot project. Replace the text emoji displayed for emotion in the current project src/display/ui/ui_chatbot.c, change to display images from the image folder based on emotion values. Use LVGL RGB565 format for images, images need to be converted to C array format.\\nConstraints: If ROM overflows, reduce to 4 main images (Happy, Sad, Angry, Love)\\nTechnology: The screen size used in the current project is H 480, W 320 pixels, using LVGL V8 version GUI library\\nVerification: Compilation succeeds with no ROM overflow, images display normally after flashing\\nAlternative: If 240x240 fails, try 120x120 or further reduce the number of images\\n```\\n\\n![\uD504\uB86C\uD504\uD2B8 \uD15C\uD50C\uB9BF.png](https://images.tuyacn.com/content-platform/hestia/1756114763298dd9e9663.png)\\n\\n\uD575\uC2EC \uC758\uB3C4\uB97C \uC815\uD655\uD788 \uD30C\uC545\uD558\uBA74 AI Coding \uB3C4\uAD6C\uAC00 \uB300\uC0C1 \uD504\uB85C\uC81D\uD2B8\uC5D0\uC11C Python \uAE30\uBC18 \uC774\uBBF8\uC9C0 \uBCC0\uD658 \uB3C4\uAD6C\uB97C \uC790\uB3D9\uC73C\uB85C \uC0DD\uC131\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n![\uC0DD\uC131\uB41C \uB3C4\uAD6C.png](https://images.tuyacn.com/content-platform/hestia/1756115044f42f98b5006.png)\\n\\n## 2048 \uAC8C\uC784 \uC778\uD130\uD398\uC774\uC2A4 \uCD94\uAC00\\n\\n2048 \uAC8C\uC784 \uC778\uD130\uD398\uC774\uC2A4\uB97C \uAC1C\uBC1C\uD558\uAE30 \uC804\uC5D0 AI Coding \uB3C4\uAD6C\uB97C \uD1B5\uD574 \uC778\uD130\uD398\uC774\uC2A4 \uB514\uC790\uC778\uC744 \uACC4\uD68D\uD574\uC57C \uD569\uB2C8\uB2E4. \uCEE8\uD2B8\uB864\uB7EC \uCE69\uC758 \uC131\uB2A5 \uC81C\uD55C\uACFC \uD654\uBA74 \uD53D\uC140 \uD06C\uAE30 \uB4F1\uC758 \uC815\uBCF4\uB97C AI Coding \uB3C4\uAD6C\uC5D0 \uC81C\uACF5\uD558\uBA74 4 \xd7 4 \uBCF4\uB4DC \uAC8C\uC784 \uC778\uD130\uD398\uC774\uC2A4\uB97C \uACC4\uD68D\uD569\uB2C8\uB2E4. \uC2E4\uC81C \uC131\uB2A5\uC774 \uAE30\uC900\uC744 \uCDA9\uC871\uD558\uBA74 \uC774\uD6C4 5 \xd7 5 \uBCF4\uB4DC \uB808\uC774\uC544\uC6C3\uC744 \uACE0\uB824\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n<img alt=\\"\uC608\uC2DC \uC774\uBBF8\uC9C0\\" src=\\"https://images.tuyacn.com/content-platform/hestia/17561158982c6d7812f26.png\\" width=\\"500\\"  />\\n\\n\uC774 \uB2E8\uACC4\uC758 \uBAA9\uC801\uC740 \uAE30\uB2A5 \uAD6C\uD604 \uBA85\uB839\uC744 \uB0B4\uB9AC\uAE30 \uC804\uC5D0 AI Coding \uB3C4\uAD6C\uC758 \uCD5C\uC885 \uCD9C\uB825\uC774 \uAE30\uB300\uC5D0 \uBD80\uD569\uD558\uB294\uC9C0 \uBBF8\uB9AC \uD655\uC778\uD558\uB294 \uAC83\uC785\uB2C8\uB2E4. \uCC28\uC774\uAC00 \uC788\uB2E4\uBA74 \uD504\uB86C\uD504\uD2B8\uC5D0 \uC81C\uC57D \uC870\uAC74\uC744 \uCD94\uAC00\uD574 \uC218\uC815\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n### \uD504\uB86C\uD504\uD2B8 \uD15C\uD50C\uB9BF\\n\\nAI Coding \uB3C4\uAD6C\uAC00 \uACC4\uD68D\uD55C 2048 \uAC8C\uC784 \uC778\uD130\uD398\uC774\uC2A4\uB97C \uD655\uC778\uD55C \uD6C4 2048 \uAC8C\uC784 \uC778\uD130\uD398\uC774\uC2A4\uB97C \uC0DD\uC131\uD558\uB3C4\uB85D \uC9C0\uC2DC\uD558\uC138\uC694. \uD654\uBA74\uC5D0 \uD1A0\uAE00 \uBC84\uD2BC\uC744 \uC124\uC815\uD574 \uCC44\uD305 \uC778\uD130\uD398\uC774\uC2A4\uC640 \uAC8C\uC784 \uC778\uD130\uD398\uC774\uC2A4 \uC0AC\uC774\uB97C \uC804\uD658\uD558\uACE0, \uD504\uB85C\uC81D\uD2B8 \uAD00\uB9AC\uB97C \uD3B8\uB9AC\uD558\uAC8C \uD558\uB3C4\uB85D 2048 \uAC8C\uC784 \uC778\uD130\uD398\uC774\uC2A4\uB97C \uBCC4\uB3C4\uC758 UI \uD30C\uC77C \uD615\uC2DD\uC73C\uB85C \uC800\uC7A5\uD574\uC57C \uD569\uB2C8\uB2E4.\\n\\n```\\nGoal: Help me add a 2048 game interface to the your_chat_bot project, only need to implement basic 2048 game functionality with score statistics. Can switch back and forth between chat interface and game interface through a button.\\nConstraints: The screen resolution size in the current project is H 480, W 320 pixels, game interface is a 4*4 board.\\nVerification: Compilation succeeds with no ROM overflow, images display normally after flashing\\n\\n```\\n\\n![\uD504\uB86C\uD504\uD2B8.png](https://images.tuyacn.com/content-platform/hestia/1756116811b2d24299207.png)\\n\\n## \uD6A8\uACFC \uD655\uC778\\n\\n\uC774\uC81C TuyaOpen \uC624\uD508 \uC18C\uC2A4 \uB300\uD654 \uD504\uB85C\uC81D\uD2B8 `your_chat_bot`\uC744 \uAE30\uBC18\uC73C\uB85C \uAC1C\uBC1C\uD55C \uB370\uC2A4\uD06C\uD1B1 \uCC57\uBD07\uC774 \uC644\uC131\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uC774 \uB85C\uBD07\uC740 \uC774\uBAA8\uC9C0 \uC774\uBBF8\uC9C0 \uAD50\uCCB4 \uAE30\uB2A5\uACFC 2048 \uAC8C\uC784 \uC778\uD130\uD398\uC774\uC2A4 \uD1B5\uD569\uC744 \uC9C0\uC6D0\uD569\uB2C8\uB2E4.\\n\\n\uCD5C\uC885 \uC0DD\uC131 \uD38C\uC6E8\uC5B4 \uD30C\uC77C\uC740 \uB2E4\uC74C\uACFC \uAC19\uC2B5\uB2C8\uB2E4: [your_chat_bot_QIO_1.0.1.bin](https://drive.weixin.qq.com/s?k=AGQAugfWAAkS4ye03BAbQAqAb1AFU). \uD38C\uC6E8\uC5B4\uB97C \uBC1B\uC544 \uD50C\uB798\uC2F1\uD55C \uD6C4 \uCD5C\uC885 \uD6A8\uACFC\uB97C \uD655\uC778\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n## \uD504\uB86C\uD504\uD2B8 \uC0AC\uC6A9 \uACBD\uD5D8 \uC694\uC57D\\n\\n- \uD504\uB85C\uC81D\uD2B8 \uB610\uB294 \uB370\uBAA8\uB97C \uAC1C\uBC1C\uD560 \uB54C\uB294 \uBA3C\uC800 AI \uB3C4\uAD6C\uB85C \uC804\uCCB4 \uAE30\uB2A5 \uC544\uD0A4\uD14D\uCC98\uB97C \uC815\uB9AC\uD558\uACE0 \uC694\uC57D\uD55C \uB2E4\uC74C, \uC544\uD0A4\uD14D\uCC98\uC5D0 \uAE30\uBC18\uD574 \uAC1C\uBC1C \uC9C0\uC2DC\uB97C \uB0B4\uB9AC\uBA74 \uD6A8\uACFC\uB97C \uB192\uC77C \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n- \uC2DC\uC791\uD560 \uB54C \uC81C\uACF5\uD558\uB294 \uD504\uB86C\uD504\uD2B8\uAC00 \uC790\uC138\uD560\uC218\uB85D \uCD5C\uC885 \uACB0\uACFC\uAC00 \uC88B\uC544\uC9D1\uB2C8\uB2E4. \uCC38\uACE0 \uC790\uB8CC\uAC00 \uC788\uB2E4\uBA74 \uAC00\uB2A5\uD55C \uD55C AI \uB3C4\uAD6C\uC5D0 \uC81C\uACF5\uD558\uC138\uC694. \uAE30\uC220 \uC138\uBD80 \uC0AC\uD56D\uC744 \uBBF8\uB9AC \uBA85\uD655\uD788 \uD558\uBA74 \uB354 \uC88B\uC2B5\uB2C8\uB2E4. \uC608\uB97C \uB4E4\uC5B4 \uD654\uBA74 \uC774\uBBF8\uC9C0 \uD45C\uC2DC \uAE30\uB2A5\uC744 \uAD6C\uD604\uD560 \uB54C \uC774\uBBF8\uC9C0\uAC00 C \uBC30\uC5F4 \uD615\uC2DD\uC73C\uB85C \uBCC0\uD658\uB418\uC5B4\uC57C \uD55C\uB2E4\uACE0 \uC9C0\uC815\uD558\uACE0 RGB565, RGB888 \uB4F1 \uAD6C\uCCB4\uC801\uC778 \uC778\uCF54\uB529 \uD615\uC2DD\uC744 \uBA85\uC2DC\uD574\uC57C \uD569\uB2C8\uB2E4. \uC778\uCF54\uB529 \uD615\uC2DD\uC744 \uC9C0\uC815\uD558\uC9C0 \uC54A\uC73C\uBA74 \uB514\uBC84\uAE45 \uD69F\uC218\uAC00 \uD06C\uAC8C \uB298\uC5B4\uB0A9\uB2C8\uB2E4.\\n\\n- \uD504\uB86C\uD504\uD2B8\uB294 \uB2E4\uC74C \uD15C\uD50C\uB9BF\uC744 \uCC38\uACE0\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n    \\n    ```\\n    Goal: [What specifically to achieve]\\n    Constraints: [What are the limiting conditions]\\n    Technology: [What tools/methods to use]\\n    Verification: [How to confirm success]\\n    Alternative: [What to do if it fails]\\n    ```\\n    \uC608:\\n    ```\\n    Goal: Change emotion images from 64x64 to 240x240 pixels\\n    Constraints: If ROM overflows, reduce to 4 main images (Happy, Sad, Angry, Love)\\n    Technology: Use png_to_c_array.py tool to regenerate, update CMakeLists.txt\\n    Verification: Compilation succeeds with no ROM overflow, images display normally after flashing\\n    Alternative: If 240x240 fails, try 120x120 or further reduce the number of images.\\n    ```\\n\\n## \uBE60\uB978 \uC2DC\uC791 \uD504\uB85C\uC81D\uD2B8 \uCD94\uCC9C\\n\\n\uC544\uC774\uB514\uC5B4\uAC00 \uCC3D\uC758\uC131\uC744 \uC2DC\uC791\uD558\uAC8C \uD558\uACE0 T5 \uAC1C\uBC1C \uBCF4\uB4DC\uAC00 \uC774\uB97C \uC2E4\uD604\uD558\uB3C4\uB85D \uB3C4\uC640\uC90D\uB2C8\uB2E4! \uC9C0\uAE08 \uC2DC\uC791\uD574 \uB2E8 \uD55C \uC8FC\uB9D0 \uB9CC\uC5D0 \uCCAB \uD504\uB85C\uC81D\uD2B8\uB97C \uC644\uC131\uD558\uC138\uC694. [\uACF5\uC2DD \uD29C\uD1A0\uB9AC\uC5BC](https://tuyaopen.ai/zh)\uC740 \uC804\uCCB4 \uAE30\uC220 \uC9C0\uC6D0\uC744 \uC81C\uACF5\uD569\uB2C8\uB2E4.\\n\\n### \uC2A4\uB9C8\uD2B8 \uC74C\uC131 \uBE44\uC11C\\n\\nAI \uAC1C\uBC1C\uC774 \uCC98\uC74C\uC774\uB77C\uBA74 \uB2E4\uC74C \uC138 \uAC00\uC9C0 \uD575\uC2EC \uAE30\uB2A5\uC744 \uAD6C\uD604\uD560 \uC218 \uC788\uB294 \uC2A4\uB9C8\uD2B8 \uC74C\uC131 \uBE44\uC11C \uD504\uB85C\uC81D\uD2B8\uB97C \uCD94\uCC9C\uD569\uB2C8\uB2E4.\\n- \uC74C\uC131 \uBA85\uB839\uC73C\uB85C \uC870\uBA85\uACFC \uC5D0\uC5B4\uCEE8 \uB4F1 \uD648 \uB514\uBC14\uC774\uC2A4\uB97C \uC81C\uC5B4\uD569\uB2C8\uB2E4.\\n- \uC74C\uC131 \uBA85\uB839\uC5D0 \uC751\uB2F5\uD574 \uC74C\uC545 \uC7AC\uC0DD, \uC54C\uB9BC \uC124\uC815 \uB4F1\uC758 \uC791\uC5C5\uC744 \uC2E4\uD589\uD569\uB2C8\uB2E4.\\n- \uC0AC\uC6A9\uC790 \uC9C0\uC815 \uC804\uC6A9 \uC74C\uC131 \uC6E8\uC774\uD06C \uC6CC\uB4DC\uB97C \uC9C0\uC6D0\uD569\uB2C8\uB2E4.\\n\\n### \uBC18\uB824\uB3D9\uBB3C \uBE44\uC11C\\n\\n\uBC18\uB824\uB3D9\uBB3C\uC744 \uC88B\uC544\uD558\uB294 \uAC1C\uBC1C\uC790\uB77C\uBA74 \uBC18\uB824\uB3D9\uBB3C \uBE44\uC11C \uD504\uB85C\uC81D\uD2B8\uB85C \uB2E4\uC74C \uAE30\uB2A5\uC744 \uAD6C\uD604\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n- \uC790\uB3D9 \uAE09\uC2DD: \uBC18\uB824\uB3D9\uBB3C\uC758 \uAE09\uC2DD \uC694\uAD6C\uB97C \uD574\uACB0\uD558\uACE0 \uC0AC\uC6A9\uC790\uAC00 \uCD9C\uC7A5 \uC911\uC77C \uB54C\uB3C4 \uC790\uB3D9\uC73C\uB85C \uBA39\uC774\uB97C \uC90D\uB2C8\uB2E4.\\n- \uC6D0\uACA9 \uACE0\uC591\uC774 \uB180\uC544 \uC8FC\uAE30 \uBC0F \uC0B0\uCC45: \uC6D0\uACA9 \uC0C1\uD638 \uC791\uC6A9\uC744 \uC9C0\uC6D0\uD574 \uC9D1\uC5D0 \uC5C6\uC744 \uB54C\uB3C4 \uBC18\uB824\uB3D9\uBB3C\uACFC \uC0C1\uD638 \uC791\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n\\n### \uCC3D\uC758\uC801\uC778 \uC870\uBA85 \uC544\uD2B8\\n\\n\uC774 \uC194\uB8E8\uC158\uC740 \uBA4B\uC9C4 \uC2A4\uD0C0\uC77C\uC758 \uC791\uD488\uC744 \uAC1C\uBC1C\uD558\uB824\uB294 \uBA54\uC774\uCEE4\uC5D0\uAC8C \uD2B9\uD788 \uC801\uD569\uD558\uBA70 \uB2E4\uC74C \uB450 \uC885\uB958\uC758 \uC81C\uD488\uC744 \uAC1C\uBC1C\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n- \uC74C\uC131 \uC81C\uC5B4 \uC0C9\uC0C1 \uBCC0\uACBD \uC870\uBA85\\n- \uC74C\uC545 \uB9AC\uB4EC \uB77C\uC774\uD2B8 \uC2A4\uD2B8\uB9BD"},{"id":"/8-8-online-contest","metadata":{"permalink":"/ko/blog/8-8-online-contest","editUrl":"https://github.com/Tuya-Community/TuyaOpen.io/edit/master/i18n/ko/docusaurus-plugin-content-blog/2025-08-08-100-days-ai-hackathon.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2025-08-08-100-days-ai-hackathon.md","title":"100\uC77C AI \uAC01\uC131 \uACC4\uD68D: \uBBF8\uB798\uC758 AI \uD558\uB4DC\uC6E8\uC5B4 \uB9CC\uB4E4\uAE30","description":"\uBB38\uD654\uC640 \uC9C0\uB2A5\uC758 \uC81C\uC870 | AI \uBB38\uD654 \uC2E0\uC885 \uAC01\uC131 \uACC4\uD68D","date":"2025-08-08T00:00:00.000Z","tags":[{"inline":false,"label":"TuyaOpen","permalink":"/ko/blog/tags/TuyaOpen","description":"TuyaOpen \uD50C\uB7AB\uD3FC \uBC0F \uAC1C\uBC1C \uAD00\uB828 \uCF58\uD150\uCE20"},{"inline":false,"label":"\uB300\uD68C","permalink":"/ko/blog/tags/Contest","description":"\uAC1C\uBC1C\uC790 \uB300\uD68C \uBC0F \uD574\uCEE4\uD1A4"}],"readingTime":6.31,"hasTruncateMarker":true,"authors":[{"name":"Tuya","title":"TuyaOpen \uBAA8\uB4E0 \uC720\uC9C0\uAD00\uB9AC\uC790","url":"https://github.com/tuya/tuya-open","socials":{"github":"https://github.com/tuya","youtube":"https://youtube.com/@tuyasmart5602","website":"https://tuyaopen.ai"},"imageURL":"https://avatars.githubusercontent.com/u/73523937?v=4","key":"tuya","page":null}],"frontMatter":{"slug":"/8-8-online-contest","title":"100\uC77C AI \uAC01\uC131 \uACC4\uD68D: \uBBF8\uB798\uC758 AI \uD558\uB4DC\uC6E8\uC5B4 \uB9CC\uB4E4\uAE30","authors":["tuya"],"image":"/img/home/tuyaopen-logo-social-preview.png","tags":["TuyaOpen","Contest"]},"unlisted":false,"prevItem":{"title":"AI \uCF54\uB529\uC73C\uB85C TuyaOpen \uAC1C\uBC1C \uAC00\uC18D\uD558\uAE30","permalink":"/ko/blog/2025/09/19/vibe-coding-accelerate-tuyaopen-development"},"nextItem":{"title":"72\uC2DC\uAC04 Adventure X \uC774\uBCA4\uD2B8","permalink":"/ko/blog/72h-with-tuyaopen"}},"content":"## \uBB38\uD654\uC640 \uC9C0\uB2A5\uC758 \uC81C\uC870 | AI \uBB38\uD654 \uC2E0\uC885 \uAC01\uC131 \uACC4\uD68D\\n## 100\uC77C \uB3D9\uC548 \uBBF8\uB798\uC758 AI \uD558\uB4DC\uC6E8\uC5B4 \uB9CC\uB4E4\uAE30\\n\\n**AI\uB97C \uC704\uD574, \uD601\uC2E0\uC744 \uC704\uD574, \uBBF8\uB798\uB97C \uC704\uD574**\\n\\n{/* truncate */}\\n\\n<img src=\\"https://images.tuyacn.com/rms-static/acd8a070-7c19-11f0-9fb9-e1834df84344-1755511016439.jpg?tyName=%E4%B8%BB%E8%A7%86%E8%A7%89banner-%E6%9C%89%E6%94%AF%E6%8C%81%403x%20(1).jpg\\" alt=\\"\\" width=\\"300\\" />\\n\\n## 1. \uD589\uC0AC \uAC1C\uC694\\n\\n### Tuya Developer Platform \uC18C\uAC1C (https://tuyaopen.ai/zh)\\n\\nTuyaOpen\uC740 \uC131\uC219\uD55C \uC0C1\uC6A9 IoT \uC2DC\uC2A4\uD15C\uC778 TuyaOS\uB97C \uAE30\uBC18\uC73C\uB85C \uAD6C\uCD95\uB41C AIoT \uC0B0\uC5C5\uC6A9 \uC624\uD508 \uC18C\uC2A4 \uAC1C\uBC29\uD615 \uAC1C\uBC1C \uD504\uB808\uC784\uC6CC\uD06C\uC785\uB2C8\uB2E4. \uD06C\uB85C\uC2A4 \uD50C\uB7AB\uD3FC \uD638\uD658\uC131, \uD06C\uB85C\uC2A4 \uC2DC\uC2A4\uD15C \uC9C0\uC6D0, \uBAA8\uB4C8\uC131, \uAC15\uB825\uD55C \uBCF4\uC548 \uC900\uC218 \uB4F1 \uD575\uC2EC \uAE30\uB2A5\uC744 \uACC4\uC2B9\uD588\uC73C\uBA70, 1\uC5B5 \uB300\uAC00 \uB118\uB294 \uB514\uBC14\uC774\uC2A4 \uBC30\uD3EC\uC640 \uC218\uBC31\uB9CC \uBA85\uC758 \uC0AC\uC6A9\uC790\uB85C \uAC80\uC99D\uB418\uC5C8\uC2B5\uB2C8\uB2E4.\\n\\n### \uB300\uD68C \uC18C\uAC1C\\n\\n\uC774\uBC88 \uB300\uD68C\uB294 Hangzhou Cultural Investment\uC640 Tuya Smart\uAC00 \uACF5\uB3D9\uC73C\uB85C \uC2DC\uC791\uD55C \\"AI Awakening Plan\\"\uC73C\uB85C, \uC804 \uC138\uACC4 \uAC1C\uBC1C\uC790\uC758 \uD601\uC2E0 \uC5ED\uB7C9\uC744 \uBC1C\uAD74\uD558\uACE0 \uBB38\uD654\uC640 \uAE30\uC220\uC758 \uAE4A\uC740 \uC735\uD569\uC744 \uCCB4\uACC4\uD654\uD558\uBA70 \uBB38\uD654\uC640 \uAE30\uC220\uC744 \uD1B5\uD569\uD55C \uCC28\uC138\uB300 AI \uD558\uB4DC\uC6E8\uC5B4\uC640 \\"AI \uC2E0\uC885\\"\uC744 \uC721\uC131\uD558\uB294 \uAC83\uC744 \uBAA9\uD45C\uB85C \uD569\uB2C8\uB2E4. \\"AI\uB97C \uC704\uD574, \uD601\uC2E0\uC744 \uC704\uD574, \uBBF8\uB798\uB97C \uC704\uD574\\"\uB77C\uB294 \uC2AC\uB85C\uAC74 \uC544\uB798 100\uC77C\uAC04\uC758 \uC2EC\uCE35 \uACF5\uB3D9 \uC81C\uC791\uC744 \uD1B5\uD574 \uAC1C\uBC1C\uC790\uC758 \uC7A0\uC7AC\uB825\uC744 \uC774\uB04C\uC5B4 \uB0B4\uACE0 \uC0C8\uB85C\uC6B4 \uC9C8\uC801 \uC0DD\uC0B0\uC131\uC758 \uBC1C\uC804\uC744 \uCD09\uC9C4\uD558\uBA70 \uB514\uC9C0\uD138 \uC218\uB3C4\uC778 \uD56D\uC800\uC6B0\uC758 \uD601\uC2E0 \uD65C\uB825\uACFC \uAC1C\uBC29\uD615 \uC0DD\uD0DC\uACC4\uB97C \uBCF4\uC5EC \uC90D\uB2C8\uB2E4. \uAE30\uC220 \uD601\uC2E0\uC744 \uC0AC\uB791\uD558\uB294 \uC804 \uC138\uACC4 \uAC1C\uBC1C\uC790\uAC00 Tuya \uAE00\uB85C\uBC8C \uC0DD\uD0DC\uACC4 \uAC1C\uBC1C\uC790 141.7\uB9CC \uBA85\uACFC \uD568\uAED8 100\uC77C\uAC04\uC758 \uC5F4\uC815\uC801\uC778 \uD611\uC5C5\uC5D0 \uCC38\uC5EC\uD558\uAE30\uB97C \uCD08\uB300\uD569\uB2C8\uB2E4!\\n\\n\uC774 \\"AI Awakening Plan\\"\uC744 \uD1B5\uD574 \uCC28\uC138\uB300 \uAE30\uC220 \uC138\uB825\uC774 \uBB38\uD654\uC640 \uAE30\uC220\uC758 \uC735\uD569\uC774\uB77C\uB294 \uCD08\uACBD\uACC4\uC801 \uAD00\uC810\uC744 \uBC14\uD0D5\uC73C\uB85C AI \uC2E0\uC885\uC744 \uB9CC\uB4E4\uC5B4 \uB0B4\uB3C4\uB85D \uC601\uAC10\uC744 \uC8FC\uACE0, AI \uAE30\uC220\uC744 \uD575\uC2EC\uC73C\uB85C \uC0B0\uC5C5 \uC7A0\uC7AC\uB825\uC744 \uAC16\uCD98 \uC9C0\uB2A5\uD615 \uD558\uB4DC\uC6E8\uC5B4\uB97C \uC721\uC131\uD574 \uD601\uC2E0 \uC131\uACFC\uC640 \uC0B0\uC5C5 \uC218\uC694\uB97C \uC815\uD655\uD788 \uC5F0\uACB0\uD558\uBA70 \uACBD\uC7C1\uB825 \uC788\uB294 AI \uD558\uB4DC\uC6E8\uC5B4 \uC0B0\uC5C5 \uC0DD\uD0DC\uACC4\uB97C \uD568\uAED8 \uAD6C\uCD95\uD558\uACE0\uC790 \uD569\uB2C8\uB2E4.\\n\\n\uC8FC\uCD5C: Hangzhou Cultural Investment Development Co., Ltd., Hangzhou Tuya Information Co., Ltd.; \uC6B4\uC601: Hangzhou Guansheng Culture Communication Co., Ltd.\\n\\n## 2. \uB4F1\uB85D \uAE30\uAC04\\n\\n- \uB4F1\uB85D \uAE30\uAC04: 2025\uB144 8\uC6D4 8\uC77C ~ 9\uC6D4 10\uC77C\\n\\n<img src=\\"https://images.tuyacn.com/rms-static/37198f30-6f89-11f0-9f57-5d628208d2a7-1754129557411.png?tyName=%E6%8A%A5%E5%90%8D%E5%92%A8%E8%AF%A2%E7%BE%A4.png\\" alt=\\"\uB300\uD68C \uB4F1\uB85D \uC0C1\uB2F4 \uADF8\uB8F9\\" width=\\"300\\" />\\n\\n- \uC608\uC120 \uC81C\uCD9C \uB9C8\uAC10: 2025\uB144 9\uC6D4 30\uC77C\\n\\n  \uC791\uD488\uC744 GitHub \uAC1C\uBC1C\uC790 \uC791\uD488 \uC800\uC7A5\uC18C \uBC0F Xiaohongshu/Bilibili\uC640 \uAC19\uC740 \uC18C\uC15C \uBBF8\uB514\uC5B4 \uD50C\uB7AB\uD3FC\uC5D0 \uC5C5\uB85C\uB4DC\uD569\uB2C8\uB2E4.\\n\\n- \uC628\uB77C\uC778 \uC2EC\uC0AC(\uC791\uD488 20\uAC1C \uC120\uC815) \uC628\uB77C\uC778 \uB85C\uB4DC\uC1FC:\\n\\n  \uC628\uB77C\uC778 \uB85C\uB4DC\uC1FC\uC5D0\uC11C \uD300 \uC18C\uAC1C, \uB514\uC790\uC778 \uCF58\uC149\uD2B8, \uC0AC\uC6A9 \uAE30\uC220, \uC791\uD488\uC758 \uD2B9\uC9D5\uACFC \uB370\uBAA8\uB97C \uBC1C\uD45C\uD569\uB2C8\uB2E4(\uC791\uD488\uB2F9 10~15\uBD84).\\n\\n- \uCD5C\uC885 \uC2EC\uC0AC: 2025\uB144 10\uC6D4 8~13\uC77C\\n\\n  \uC218\uC0C1\uC790 \uBC1C\uD45C: 10\uC6D4 15\uC77C(\uC608\uC815)\\n\\n- \uC2DC\uC0C1\uC2DD: 2025\uB144 10\uC6D4 21\uC77C(\uC608\uC815)\\n\\n## 3. \uD589\uC0AC \uB0B4\uC6A9\\n\\n### \uACBD\uC7C1 \uD2B8\uB799\\n\\nTuyaOpen \uB124\uC774\uD2F0\uBE0C \uC624\uD508 \uC18C\uC2A4 \uD328\uD0A4\uC9C0 \uB610\uB294 TuyaOpen \uBC84\uC804 \uC624\uD508 \uC18C\uC2A4 \uD328\uD0A4\uC9C0\uB97C \uAE30\uBC18\uC73C\uB85C \uCC3D\uC758\uC801\uC778 \uC81C\uD488\uC744 \uAC1C\uBC1C\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n- **AI \uD558\uB4DC\uC6E8\uC5B4 \uD2B8\uB799**: AI \uC7A5\uB09C\uAC10 | \uB85C\uBD07 | AI \uC2A4\uB9C8\uD2B8 \uD648\\n- **AI \uC0B0\uC5C5 \uC194\uB8E8\uC158 \uD2B8\uB799**: \uC2A4\uB9C8\uD2B8 \uC624\uD53C\uC2A4, \uC2A4\uB9C8\uD2B8 \uC0B0\uC5C5 \uB4F1 \uBD84\uC57C\uC758 \uC560\uD50C\uB9AC\uCF00\uC774\uC158\\n- **AI+IP \uD2B8\uB799**: \uBB38\uD654\uC7AC | \uBC18\uB824\uB3D9\uBB3C | \uC560\uB2C8\uBA54\uC774\uC158 \uBC29\uD5A5\\n\\n  \uC785\uBB38 \uB2E8\uACC4: AI Agent \uD2B8\uB799\\n\\n- **AI \uD074\uB77C\uC6B0\uB4DC \uD2B8\uB799**: Tuya AI AGENT\uB97C \uAE30\uBC18\uC73C\uB85C \uAD6C\uCD95\uD55C AI \uC560\uD50C\uB9AC\uCF00\uC774\uC158\\n\\n### \uD559\uC2B5 \uC790\uB8CC\\n\\n| \uD559\uC2B5 \uC790\uB8CC | \uB9C1\uD06C |\\n|----------------|----------------------------------|\\n| GitHub \uB9AC\uC18C\uC2A4 \uC0AC\uC774\uD2B8 | https://github.com/tuya/TuyaOpen |\\n| \uBAA8\uB4C8 \uC0AC\uC591 \uBB38\uC11C | https://tuyaopen.ai/zh/blog |\\n| TuyaOpen \uBC0F TuyaOS \uBB38\uC11C \uBAA8\uC74C | https://tuyaopen.ai/zh/blog |\\n| AI Agent \uAC1C\uBC1C | https://developer.tuya.com/cn/docs/iot/ai-agent-management?id=Kdxr4v7uv4fud |\\n\\n- **\uBE44\uB514\uC624 \uC790\uB8CC**: \uAC1C\uBC1C\uC790 \uB370\uBAA8 \uC601\uC0C1\uC744 \uD655\uC778\uD558\uB824\uBA74 \\"Tuya Developer\\" \uBE44\uB514\uC624 \uCC44\uB110\uC744 \uD314\uB85C\uC6B0\uD558\uC138\uC694.\\n- **\uB77C\uC774\uBE0C \uC2A4\uD2B8\uB9AC\uBC0D**: \uD589\uC0AC \uAE30\uAC04\uC5D0 \uAC1C\uBC1C\uC790 \uBD80\uD2B8\uCEA0\uD504 \uB77C\uC774\uBE0C \uC138\uC158\uC774 \uC9C4\uD589\uB418\uBA70 \uC5C5\uB370\uC774\uD2B8\uB294 \uB300\uD68C \uADF8\uB8F9\uC5D0\uC11C \uD655\uC778\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n<img src=\\"https://images.tuyacn.com/rms-static/b9d2fba0-6f89-11f0-9fb9-e1834df84344-1754129776730.jpeg?tyName=%E5%BC%80%E5%8F%91%E8%80%85%E5%85%AC%E4%BC%97%E5%8F%B7.jpeg\\" alt=\\"Tuya Developer \uBE44\uB514\uC624 \uCC44\uB110\\" width=\\"300\\" />\\n\\n\uC81C\uACF5\uB41C \uD559\uC2B5 \uC790\uB8CC\uB97C \uBC14\uD0D5\uC73C\uB85C Tuya T5 \uBAA8\uB4C8\uC5D0\uC11C TuyaOpen\uC744 \uD559\uC2B5\uD558\uACE0 \uC790\uC2E0\uB9CC\uC758 \uD558\uB4DC\uC6E8\uC5B4\uB97C DIY\uD558\uC138\uC694.\\n\\n### \uAE30\uC220 \uC694\uAD6C \uC0AC\uD56D\\n\\n**\u{1F31F} AI \uD558\uB4DC\uC6E8\uC5B4 \uAC1C\uBC1C\uC740 Tuya \uAC1C\uBC1C \uD50C\uB7AB\uD3FC\uC744 \uAE30\uBC18\uC73C\uB85C \uD574\uC57C \uD569\uB2C8\uB2E4.**\\n\\n- **TuyaOpen**: TuyaOpen\uC740 \uC5C5\uACC4 \uC120\uB3C4\uC801\uC778 TuyaOS \uC544\uD0A4\uD14D\uCC98\uB97C \uAE30\uBC18\uC73C\uB85C \uD55C \uC624\uD508 \uC18C\uC2A4 \uD50C\uB7AB\uD3FC\uC774\uBA70 \uC804 \uC138\uACC4 141.7\uB9CC \uBA85\uC758 \uAC1C\uBC1C\uC790\uAC00 \uAC80\uC99D\uD588\uC2B5\uB2C8\uB2E4.\\n- **TuyaOS**: Tuya Wind IDE\uB294 TuyaOS EasyGo\uB97C \uC0AC\uC6A9\uD558\uB294 \uAC1C\uBC1C\uC790\uB97C \uC704\uD55C \uC6D0\uC2A4\uD1B1 \uD1B5\uD569 \uAC1C\uBC1C \uD658\uACBD\uC785\uB2C8\uB2E4.\\n\\n\uCC38\uAC00\uC790\uB294 \uC694\uAD6C \uC0AC\uD56D\uC5D0 \uB530\uB77C \uAD6C\uCCB4\uC801\uC778 \uAC1C\uBC1C \uD50C\uB7AB\uD3FC\uC744 \uC120\uD0DD\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. **\uBE44\uB514\uC624 AI \uAE30\uB2A5 \uD1B5\uD569** \uB610\uB294 **\uC0C1\uC6A9\uD654 \uC2DC\uB098\uB9AC\uC624**\uAC00 \uD544\uC694\uD558\uB2E4\uBA74 TuyaOS\uB97C \uAD8C\uC7A5\uD558\uBA70, \uADF8 \uC678\uC758 \uC2DC\uB098\uB9AC\uC624\uB098 \uC694\uAD6C \uC0AC\uD56D\uC5D0\uB294 \uB354 \uAC1C\uBC29\uC801\uC778 **TuyaOpen** \uC0DD\uD0DC\uACC4\uB97C \uAD8C\uC7A5\uD569\uB2C8\uB2E4.\\n\\n**\u{1F31F} \uD558\uB4DC\uC6E8\uC5B4 \uC694\uAD6C \uC0AC\uD56D**\\n\\n- **\uAC1C\uBC1C \uBCF4\uB4DC**: T5 \uC2DC\uB9AC\uC988 \uAC1C\uBC1C \uBCF4\uB4DC\uB97C \uAD8C\uC7A5\uD569\uB2C8\uB2E4. TuyaOpen \uD50C\uB7AB\uD3FC\uC774 \uC9C0\uC6D0\uD558\uB294 \uB2E4\uB978 \uC0DD\uD0DC\uACC4\uB294 \uB2E4\uC74C\uC744 \uCC38\uC870\uD558\uC138\uC694.\\nhttps://tuyaopen.ai/zh/docs/about-tuyaopen\\n- **DIY \uAC1C\uBC1C \uBCF4\uB4DC**: T5 \uBAA8\uB4C8\uC744 \uC0AC\uC6A9\uD574\uC57C \uD569\uB2C8\uB2E4.\\n\\n### \uC81C\uCD9C \uC694\uAD6C \uC0AC\uD56D\\n\\n**\u{1F31F} \uC791\uD488 \uAC8C\uC2DC \uACBD\uB85C**\\n\\n\uC791\uD488\uC744 OSChina \uC624\uD508 \uC18C\uC2A4 \uCEE4\uBBA4\uB2C8\uD2F0\uC5D0 \uAC00\uC7A5 \uC801\uD569\uD55C \uD615\uD0DC\uB85C \uC5C5\uB85C\uB4DC\uD569\uB2C8\uB2E4. \uC18C\uC2A4 \uCF54\uB4DC\uB97C GitHub \uB610\uB294 Gitee\uC5D0 \uC81C\uCD9C\uD558\uBA70 \uC800\uC7A5\uC18C\uC5D0\uB294 \uC18C\uD504\uD2B8\uC6E8\uC5B4\uC640 \uD558\uB4DC\uC6E8\uC5B4 \uAD00\uB828 \uC790\uB8CC\uAC00 \uD3EC\uD568\uB418\uC5B4\uC57C \uD569\uB2C8\uB2E4. \uC804\uCCB4 \uD504\uB85C\uC81D\uD2B8 \uBC1C\uD45C\uB3C4 \uD3C9\uAC00 \uB300\uC0C1\uC785\uB2C8\uB2E4.\\n\\n**\u{1F31F} \uBB38\uC11C \uC694\uAD6C \uC0AC\uD56D**\\n\\n\uD504\uB85C\uC81D\uD2B8 \uC81C\uC548\uC11C https://drive.weixin.qq.com/s?k=AGQAugfWAAkCkERkpHAFUAoAamAEg \uB610\uB294 PPT(\uD15C\uD50C\uB9BF \uB2E4\uC6B4\uB85C\uB4DC)\uB97C \uC81C\uCD9C\uD569\uB2C8\uB2E4.\\n\\n**\u{1F31F} \uB3D9\uC601\uC0C1 \uC81C\uCD9C \uC694\uAD6C \uC0AC\uD56D**\\n\\n- **\uB3D9\uC601\uC0C1 \uC694\uAD6C \uC0AC\uD56D**: \uB3D9\uC601\uC0C1\uC740 1\uBD84 \uC774\uC0C1\uC774\uC5B4\uC57C \uD558\uBA70 \uC81C\uD488\uC758 \uC804\uCCB4 \uAE30\uB2A5\uACFC \uC131\uB2A5, \uC791\uD488\uC758 \uD2B9\uC9D5\uACFC \uC0AC\uC6A9 \uC0AC\uB840\uB97C \uC18C\uAC1C\uD574\uC57C \uD569\uB2C8\uB2E4.\\n- **\uB3D9\uC601\uC0C1 \uAC8C\uC2DC**: Xiaohongshu/Douyin/Video Channel/Bilibili \uB4F1 \uC18C\uC15C \uBBF8\uB514\uC5B4 \uD50C\uB7AB\uD3FC\uC5D0 \uB3D9\uC601\uC0C1\uC744 \uAC8C\uC2DC\uD558\uACE0 `@Tuya Developer`\uC640 \uD574\uC2DC\uD0DC\uADF8 `#TuyaOpen#TuyaAI#Challenge100DaysDevelopAIHardware`\uB97C \uC0AC\uC6A9\uD558\uC138\uC694. \uC778\uAE30\uB3C4 \uBCF4\uB108\uC2A4 \uC810\uC218\uB97C \uBC1B\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n\uC704 \uC791\uD488 \uAC8C\uC2DC \uC8FC\uC18C \uB9C1\uD06C\uC640 \uBB38\uC11C\uB97C \uC774\uBA54\uC77C `huate.lai@tuya.com`\uC73C\uB85C \uBCF4\uB0B4\uC138\uC694. \uC774\uBA54\uC77C \uC81C\uBAA9 \uD615\uC2DD\uC740 \\"\uD300 \uC774\uB984 + \uC791\uD488 \uC774\uB984 + \uD2B8\uB799\\"\uC785\uB2C8\uB2E4.\\n\\n**\uC694\uAD6C \uC0AC\uD56D:**\\n- \uC791\uD488 \uB0B4\uC6A9\uC740 \uAD00\uB828 \uAD6D\uAC00 \uBC95\uB960\uACFC \uADDC\uC815\uC744 \uC900\uC218\uD574\uC57C \uD558\uBA70 \uAE0D\uC815\uC801\uC774\uACE0 \uAC74\uC804\uD574\uC57C \uD569\uB2C8\uB2E4.\\n- Tuya \uC218\uC11D IoT \uC5D4\uC9C0\uB2C8\uC5B4\uAC00 \uBAA8\uB4E0 \uC791\uD488\uC744 \uACF5\uC815\uD558\uACE0 \uACF5\uD3C9\uD558\uAC8C \uC2EC\uC0AC\uD569\uB2C8\uB2E4.\\n\\n### \uB300\uD68C \uB9AC\uC18C\uC2A4 \uC774\uC6A9\\n\\n- **\uAC1C\uBC1C \uBCF4\uB4DC \uAD6C\uB9E4**: \uB4F1\uB85D\uD55C \uCC38\uAC00\uC790\uB294 \uADF8\uB8F9\uC5D0 \uAC00\uC785\uD55C \uD6C4 T5AI \uAC1C\uBC1C \uBCF4\uB4DC \uD0A4\uD2B8\uB97C 50% \uD560\uC778\uC73C\uB85C \uAD6C\uB9E4\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n- **\uBB34\uB8CC \uAC1C\uBC1C \uBCF4\uB4DC(\uD55C\uC815 \uC218\uB7C9)**: \uCC3D\uC758\uC131\uACFC \uD504\uB85C\uC81D\uD2B8 \uC2E4\uD604 \uAC00\uB2A5\uC131\uC744 \uAE30\uC900\uC73C\uB85C \uC120\uC815\uB41C \uAC1C\uBC1C\uC790\uC5D0\uAC8C T5 \uAC1C\uBC1C \uBCF4\uB4DC\uB97C \uC81C\uACF5\uD558\uBA70 \uC2EC\uC0AC \uC2B9\uC778 \uD6C4 \uBC1C\uAE09\uD569\uB2C8\uB2E4.\\n- **Tuya Cloud \uC11C\uBE44\uC2A4 \uC774\uC6A9** \u2014 **\uD589\uC0AC \uAE30\uAC04 \uB3D9\uC548** \uC74C\uC131 \uD569\uC131, \uC74C\uC131 \uBCF5\uC81C, \uC74C\uC131 \uC778\uC2DD \uB4F1 AI \uAE30\uB2A5\uC744 \uBB34\uB8CC\uB85C \uC0AC\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uD589\uC0AC\uC6A9 \uD61C\uD0DD\uC774\uBA70 \uD589\uC0AC \uC678\uC5D0\uB294 [AI \uACFC\uAE08 \uADDC\uCE59](https://developer.tuya.com/en/docs/iot/ai-agent-price?id=Kegb2s2shaj4d)\uC5D0 \uB530\uB77C AI \uC0AC\uC6A9\uB7C9\uC774 \uCE21\uC815\uB418\uACE0 \uACFC\uAE08\uB429\uB2C8\uB2E4.\\n\\n- **\uB4F1\uB85D \uC644\uB8CC \uD6C4 \uADF8\uB8F9 \uAC00\uC785 \uBC0F \uB9AC\uC18C\uC2A4 \uC2E0\uCCAD**\\n\\n  \uB9AC\uC18C\uC2A4 \uC2E0\uCCAD \uC694\uAC74:\\n  - GitHub\uC758 \uACFC\uAC70 \uD504\uB85C\uC81D\uD2B8 \uB9C1\uD06C \uBCF4\uC720\\n  - \uAD00\uB828 \uD558\uB4DC\uC6E8\uC5B4 \uAC1C\uBC1C \uACBD\uD5D8 \uBCF4\uC720\\n\\n## 4. \uD589\uC0AC \uC2DC\uC0C1(\uB9AC\uC18C\uC2A4 \uD480 \uAC00\uCE58 100,000 \uC774\uC0C1)\\n\\n### \u{1F381} 1\uB4F1: \uC791\uD488 1\uAC1C, \uB2E4\uC74C\uC744 \uBC1B\uC744 \uC218 \uC788\uC74C\\n\\n- 5999 \uC0C1\uB2F9\uC758 \uC2A4\uB9C8\uD2B8 \uACF5\uAC04 \uC790\uB3D9\uD654 \uC81C\uD488\uAD70\\n- 4000\uC704\uC548 \uC1FC\uD551 \uCE74\uB4DC\\n\\n<img src=\\"https://images.tuyacn.com/rms-static/b9d4f770-6f89-11f0-9fb9-e1834df84344-1754129776743.png?tyName=%E5%A5%96%E5%93%811.png\\" alt=\\"1\uB4F1 \uC0C1\uD488\\" width=\\"300\\" />\\n\\n### \u{1F381} 2\uB4F1: \uC791\uD488 3\uAC1C, \uAC01 \uC791\uD488\uC774 \uB2E4\uC74C\uC744 \uBC1B\uC744 \uC218 \uC788\uC74C\\n\\n- 3999 \uC0C1\uB2F9\uC758 \uB2E4\uAE30\uB2A5 AI \uC81C\uC5B4 \uC13C\uD130\\n- 2000\uC704\uC548 \uC1FC\uD551 \uCE74\uB4DC\\n\\n<img src=\\"https://images.tuyacn.com/rms-static/b9d4a950-6f89-11f0-9fb9-e1834df84344-1754129776741.png?tyName=%E5%A5%96%E5%93%812.png\\" alt=\\"2\uB4F1 \uC0C1\uD488\\" width=\\"300\\" />\\n\\n### \u{1F381} 3\uB4F1: \uC791\uD488 5\uAC1C, \uAC01 \uC791\uD488\uC774 \uB2E4\uC74C\uC744 \uBC1B\uC744 \uC218 \uC788\uC74C\\n\\n- 299 \uC0C1\uB2F9\uC758 Wi-Fi AI \uC778\uD615\\n- 1000\uC704\uC548 \uC1FC\uD551 \uCE74\uB4DC\\n\\n<img src=\\"https://images.tuyacn.com/rms-static/b9d65700-6f89-11f0-9f57-5d628208d2a7-1754129776752.png?tyName=%E5%A5%96%E5%93%813.png\\" alt=\\"3\uB4F1 \uC0C1\uD488\\" width=\\"300\\" />\\n\\n### \u{1F381} \uCD5C\uACE0\uC758 \uC18C\uD1B5\uC0C1: \uC791\uD488 10\uAC1C, \uAC01 \uC791\uD488\uC774 \uB2E4\uC74C\uC744 \uBC1B\uC744 \uC218 \uC788\uC74C\\n\\n- Tuya \uAD7F\uC988 \uBC0F 200\uC704\uC548 \uC1FC\uD551 \uCE74\uB4DC\\n\\n\uC694\uAD6C \uC0AC\uD56D\uC5D0 \uB530\uB77C \uC791\uD488\uC744 \uC644\uC131\uD558\uACE0 Xiaohongshu/Douyin \uB4F1 \uD50C\uB7AB\uD3FC\uC5D0\uC11C \uAC00\uC7A5 \uB192\uC740 \uC778\uAE30\uB97C \uC5BB\uC740 \uC791\uD488\uC744 \uACF5\uC720\uD569\uB2C8\uB2E4.\\n\\n### \u{1F381} \uCD5C\uACE0\uC758 Agent \uCC3D\uC758\uC131\uC0C1(AI Agent \uD2B8\uB799 \uD2B9\uBCC4\uC0C1): \uC791\uD488 5\uAC1C, \uAC01 \uC791\uD488\uC774 \uB2E4\uC74C\uC744 \uBC1B\uC744 \uC218 \uC788\uC74C\\n\\n- \uCC3D\uC758\uC801\uC778 AI Agent \uD38C\uC6E8\uC5B4\uAC00 \uD3EC\uD568\uB41C \uB9DE\uCDA4\uD615 Tuya \uAC1C\uBC1C \uBCF4\uB4DC \uD0A4\uD2B8 \uBC0F 100\uC704\uC548 \uC1FC\uD551 \uCE74\uB4DC\\n\\n### \u{1F381} \uC218\uC0C1 \uC791\uD488\uC774 \uB204\uB9AC\uB294 \uC0DD\uD0DC\uACC4 \uB9AC\uC18C\uC2A4\\n\\n- Tuya Smart \uAE30\uC220\uD300\uC758 \uC77C\uB300\uC77C \uAE30\uC220 \uC9C0\uB3C4\uB85C \uC0C1\uC6A9\uD654 \uACBD\uB85C\uB97C \uBC1C\uC804\uC2DC\uD0A4\uACE0 \uBCA4\uCC98 \uCE90\uD53C\uD138 \uB9AC\uC18C\uC2A4 \uCD94\uCC9C\uC744 \uBC1B\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n- \uAC1C\uBC1C\uC790 \uC791\uD488 \uD64D\uBCF4 \uB9AC\uC18C\uC2A4 \uD328\uD0A4\uC9C0: Tuya Smart\uAC00 \uC778\uAE30 \uAC1C\uBC1C\uC790\uB85C \uC131\uC7A5\uD560 \uC218 \uC788\uB3C4\uB85D \uC9C0\uC6D0\uD569\uB2C8\uB2E4. Tuya Smart\uC758 \uC804 \uD50C\uB7AB\uD3FC \uC791\uD488 \uD64D\uBCF4\uC640 \uD2B9\uBCC4 \uD2B8\uB798\uD53D \uC9C0\uC6D0 \uACC4\uD68D\uC744 \uD1B5\uD574 \uB178\uCD9C\uC744 \uC9C0\uC6D0\uD558\uACE0 \uC8FC\uC694 KOL\uACFC \uD611\uB825\uD574 \uAC1C\uBC1C\uC790 \uC81C\uD488\uC758 \uC601\uD5A5\uB825\uACFC IP\uB97C \uD64D\uBCF4\uD569\uB2C8\uB2E4.\\n- Tuya \uAC1C\uBC1C\uC790 \uC0DD\uD0DC\uACC4\uC758 \uACF5\uC2DD \uD575\uC2EC \uC778\uC99D \uAC1C\uBC1C\uC790\uAC00 \uB418\uC5B4 \uCD5C\uC2E0 \uD50C\uB7AB\uD3FC \uAE30\uB2A5\uC5D0 \uC6B0\uC120 \uC811\uADFC\uD558\uACE0, Demo \uACF5\uB3D9 \uC81C\uC791\uC744 \uC704\uD55C \uBAA8\uB4C8 \uBC0F \uAC1C\uBC1C \uBCF4\uB4DC\uC640 \uAE30\uC220 \uC9C0\uC6D0\uC744 \uBB34\uB8CC\uB85C \uC774\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n- \uC81C\uD488 \uD574\uC678 \uC9C0\uC6D0 \uBC0F \uBE44\uC988\uB2C8\uC2A4 \uD611\uB825 \uCD94\uCC9C: \uC218\uC0C1 \uC791\uD488\uC740 \uD574\uC678 \uC804\uC2DC\uD68C\uC5D0 \uC804\uC2DC\uB418\uBA70 Tuya Smart\uAC00 \uD574\uC678 \uC9C4\uCD9C\uC744 \uC804\uBA74 \uC9C0\uC6D0\uD558\uACE0 Amazon, TikTok \uB4F1 \uD310\uB9E4 \uC804 \uACFC\uC815\uC744 \uC9C0\uC6D0\uD569\uB2C8\uB2E4."},{"id":"/72h-with-tuyaopen","metadata":{"permalink":"/ko/blog/72h-with-tuyaopen","editUrl":"https://github.com/Tuya-Community/TuyaOpen.io/edit/master/i18n/ko/docusaurus-plugin-content-blog/2025-06-27-developer-contest.md","source":"@site/i18n/ko/docusaurus-plugin-content-blog/2025-06-27-developer-contest.md","title":"72\uC2DC\uAC04 Adventure X \uC774\uBCA4\uD2B8","description":"{/ truncate /}","date":"2025-06-27T00:00:00.000Z","tags":[{"inline":false,"label":"TuyaOpen","permalink":"/ko/blog/tags/TuyaOpen","description":"TuyaOpen \uD50C\uB7AB\uD3FC \uBC0F \uAC1C\uBC1C \uAD00\uB828 \uCF58\uD150\uCE20"},{"inline":false,"label":"\uB300\uD68C","permalink":"/ko/blog/tags/Contest","description":"\uAC1C\uBC1C\uC790 \uB300\uD68C \uBC0F \uD574\uCEE4\uD1A4"}],"readingTime":7.03,"hasTruncateMarker":true,"authors":[{"name":"Tuya","title":"TuyaOpen \uBAA8\uB4E0 \uC720\uC9C0\uAD00\uB9AC\uC790","url":"https://github.com/tuya/tuya-open","socials":{"github":"https://github.com/tuya","youtube":"https://youtube.com/@tuyasmart5602","website":"https://tuyaopen.ai"},"imageURL":"https://avatars.githubusercontent.com/u/73523937?v=4","key":"tuya","page":null},{"name":"Edward Lai","title":"TuyaOpen \uC720\uC9C0\uAD00\uB9AC\uC790","url":"https://github.com/adwuard","email":"huate.lai@tuya.com","socials":{"github":"https://github.com/adwuard","website":"https://hsuanhanlai.com"},"imageURL":"https://avatars.githubusercontent.com/u/12602411?v=4","key":"hsuanhanlai","page":null}],"frontMatter":{"slug":"/72h-with-tuyaopen","title":"72\uC2DC\uAC04 Adventure X \uC774\uBCA4\uD2B8","authors":["tuya","hsuanhanlai"],"image":"/img/home/tuyaopen-logo-social-preview.png","tags":["TuyaOpen","Contest"]},"unlisted":false,"prevItem":{"title":"100\uC77C AI \uAC01\uC131 \uACC4\uD68D: \uBBF8\uB798\uC758 AI \uD558\uB4DC\uC6E8\uC5B4 \uB9CC\uB4E4\uAE30","permalink":"/ko/blog/8-8-online-contest"}},"content":"{/* truncate */}\\n\\n# title: \'52\uC2DC\uAC04 Startup Forest \uC774\uBCA4\uD2B8\'\\n{/* ![event](https://images.tuyacn.com/fe-static/docs/img/6d005a49-7b92-4602-af60-b7acca333eab.png) */}\\n\\n> **\uC774 \uAC00\uC774\uB4DC\uB294 \uB300\uD68C \uCC38\uAC00\uC790\uB97C \uC704\uD55C \uC804\uC6A9 \uBB38\uC11C\uB85C, \uD589\uC0AC\uC5D0 \uD544\uC694\uD55C \uC885\uD569\uC801\uC778 \uC548\uB0B4\uB97C \uC81C\uACF5\uD569\uB2C8\uB2E4.**\\n\\n{/* ### \uB300\uD68C \uC815\uBCF4 */}\\n{/* - \uD589\uC0AC \uAE30\uAC04: 6/27 ~ 6/29(\uCD1D 52\uC2DC\uAC04) */}\\n\\n# \uC8FC\uC694 \uB9AC\uC18C\uC2A4\\n{/* - Tuya \uB300\uD68C PPT: [PPT \uC18C\uAC1C](https://tuyaopen-pu9rufi.gamma.site/) */}\\n- TuyaOpen \uCF54\uB4DC \uC800\uC7A5\uC18C: [GitHub](https://github.com/tuya/TuyaOpen)\\n- TuyaOpen \uBB38\uC11C \uC6F9\uC0AC\uC774\uD2B8: [\uBB38\uC11C](https://tuyaopen.ai)\\n\\n{/* truncate */}\\n\\n## TuyaOpen\uACFC TuyaOS \uBE44\uAD50\\n\\nTuyaOpen\uC740 \uC5C5\uACC4 \uC120\uB3C4\uC801\uC778 TuyaOS \uC544\uD0A4\uD14D\uCC98\uB97C \uAE30\uBC18\uC73C\uB85C \uD55C \uC624\uD508 \uC18C\uC2A4 \uD504\uB85C\uC81D\uD2B8\uC774\uBA70 \uC804 \uC138\uACC4 130\uB9CC \uBA85\uC758 \uAC1C\uBC1C\uC790\uAC00 \uAC80\uC99D\uD588\uC2B5\uB2C8\uB2E4. TuyaOpen\uC740 \uC5EC\uB7EC MCU\uB97C \uC9C0\uC6D0\uD558\uB294 C/C++ \uC560\uD50C\uB9AC\uCF00\uC774\uC158 \uAC1C\uBC1C\uC744 \uC704\uD574 \uBA85\uD655\uD558\uAC8C \uC815\uC758\uB41C API\uB97C \uC81C\uACF5\uD574 \uC8FC\uBCC0 \uC7A5\uCE58 \uC5F0\uACB0, \uD074\uB77C\uC6B0\uB4DC \uC5F0\uACB0, \uBCF4\uC548 \uB4F1 \uBCF5\uC7A1\uD55C \uAC1C\uBC1C \uD504\uB85C\uC138\uC2A4\uB97C \uD06C\uAC8C \uAC04\uC18C\uD654\uD569\uB2C8\uB2E4. \uC774 \uD504\uB808\uC784\uC6CC\uD06C\uB294 \uAC1C\uBC1C \uD6A8\uC728\uC744 \uD06C\uAC8C \uB192\uC774\uACE0 AI + IoT \uC2A4\uB9C8\uD2B8 \uC81C\uD488\uC744 \uBE60\uB974\uAC8C \uAD6C\uCD95\uD560 \uC218 \uC788\uB3C4\uB85D \uD569\uB2C8\uB2E4.\\n\\n:::tip \uC5B4\uB5BB\uAC8C \uC120\uD0DD\uD558\uB098\uC694?\\n\uCC38\uAC00\uC790\uB294 \uD544\uC694\uC5D0 \uB530\uB77C \uC120\uD0DD\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. **\uBE44\uB514\uC624 AI \uAE30\uB2A5 \uD1B5\uD569** \uB610\uB294 **\uC0C1\uC6A9\uD654 \uC2DC\uB098\uB9AC\uC624**\uAC00 \uD544\uC694\uD558\uB2E4\uBA74 TuyaOS\uB97C \uAD8C\uC7A5\uD558\uACE0, \uADF8 \uC678\uC758 \uC2DC\uB098\uB9AC\uC624\uB098 \uC694\uAD6C \uC0AC\uD56D\uC5D0\uB294 \uB354 \uAC1C\uBC29\uC801\uC778 **TuyaOpen** \uC0DD\uD0DC\uACC4\uB97C \uAD8C\uC7A5\uD569\uB2C8\uB2E4.\\n:::\\n\\n### \uC8FC\uC694 \uCC28\uC774\uC810 \uBE44\uAD50\\n\\n| \uAE30\uB2A5 | TuyaOpen | TuyaOS |\\n|-----------------------|--------------------------------------------------|-------------------------------------------------------------|\\n| \uB300\uC0C1 \uC0AC\uC6A9\uC790 | \uC624\uD508 \uC18C\uC2A4 \uAC1C\uBC1C\uC790 | \uC0C1\uC6A9 \uD611\uB825 \uAC1C\uBC1C\uC790 |\\n| \uC18C\uC2A4 \uCF54\uB4DC \uC811\uADFC | \uC644\uC804\uD55C \uC624\uD508 \uC18C\uC2A4, \uC18C\uC2A4 \uCF54\uB4DC \uC811\uADFC \uAC00\uB2A5 | \uC0C1\uC6A9 \uCF54\uB4DC\uB294 \uBD80\uBD84 \uC624\uD508 \uC18C\uC2A4\uC774\uBA70 2\uCC28 \uAC1C\uBC1C \uC9C0\uC6D0 |\\n| \uCF54\uB4DC \uB2E4\uC6B4\uB85C\uB4DC | GitHub, Gitee\uC5D0\uC11C \uBB34\uB8CC \uC624\uD508 \uC18C\uC2A4 \uB2E4\uC6B4\uB85C\uB4DC | VSCode \uD50C\uB7EC\uADF8\uC778 WindIDE \uBC0F \uC774\uBA54\uC77C \uC778\uC99D\uC73C\uB85C \uCF54\uB4DC \uD68D\uB4DD |\\n| \uAC1C\uBC1C \uD658\uACBD | Linux, Windows, Mac | Linux \uC804\uC6A9, \uB2E4\uB978 \uD50C\uB7AB\uD3FC\uC740 \uAC00\uC0C1 \uBA38\uC2E0 \uD544\uC694 |\\n| Tuya Cloud AI \uAD6C\uC131 \uC694\uC18C | \u2705 | \u2705 \uCD5C\uC2E0 \uBC0F \uCD5C\uACE0 \uC18D\uB3C4 |\\n| Tuya Voice AI ASR \uAE30\uB2A5 | \u2705 | \u2705 |\\n| Tuya Video AI \uAE30\uB2A5 | \u274C \uD604\uC7AC \uC9C0\uC6D0\uB418\uC9C0 \uC54A\uC74C | \u2705 |\\n| Tuya Cloud \uB300\uADDC\uBAA8 \uBAA8\uB378 \uB9DE\uCDA4 \uC124\uC815(LLM/Prompt/Workflow/RAG) | \u2705 | \u2705 |\\n| \uC18C\uC2A4 \uCF54\uB4DC \uB9DE\uCDA4 \uC124\uC815 \uAE30\uB2A5 | \uC18C\uC2A4 \uCF54\uB4DC \uC218\uC900\uC758 \uB192\uC740 \uB9DE\uCDA4 \uC124\uC815 | API \uC218\uC900\uC758 \uB9DE\uCDA4 \uC124\uC815, \uC5F0\uACB0\uB41C \uB77C\uC774\uBE0C\uB7EC\uB9AC, \uB354 \uD48D\uBD80\uD55C \uC0C1\uC6A9 \uAE30\uB2A5 \uAD6C\uC131 \uC694\uC18C |\\n| \uCE69 \uC9C0\uC6D0 | Tuya T \uC2DC\uB9AC\uC988/ESP \uC2DC\uB9AC\uC988(\uC9C0\uC6D0 \uBAA9\uB85D \uCC38\uC870) | Tuya T \uC2DC\uB9AC\uC988 |\\n| \uAC1C\uBC1C \uC5B8\uC5B4 | C/C++ | C/C++ |\\n| \uBB38\uC11C \uC9C0\uC6D0 | [TuyaOpen \uACF5\uC2DD \uC6F9\uC0AC\uC774\uD2B8](https://TuyaOpen.ai) | [Tuya Developer \uACF5\uC2DD \uC6F9\uC0AC\uC774\uD2B8](https://developer.tuya.com/cn/docs/iot-device-dev) |\\n| \uC18C\uC2A4 \uCF54\uB4DC \uAE30\uC5EC \uB610\uB294 2\uCC28 \uC624\uD508 \uC18C\uC2A4 | \u2705 | Copyright License \uC900\uC218 |\\n| \uD558\uB4DC\uC6E8\uC5B4 \uC0DD\uD0DC\uACC4 | \uCE69, \uAC1C\uBC1C \uBCF4\uB4DC, \uC8FC\uBCC0 \uC7A5\uCE58 \uB4DC\uB77C\uC774\uBC84\uB97C \uC9C0\uC18D\uC801\uC73C\uB85C \uCD94\uAC00 | \uAD8C\uC7A5 \uC120\uD0DD \uC194\uB8E8\uC158 \uC0AC\uC6A9 |\\n\\n\\n# \uC784\uBCA0\uB514\uB4DC \uC18C\uD504\uD2B8\uC6E8\uC5B4 \uAC1C\uBC1C\\n## TuyaOpen \uC139\uC158\\n### \uBB38\uC11C\\n- TuyaOpen \uBB38\uC11C: [\uBB38\uC11C](/docs/about-tuyaopen)\\n- AI API \uCF54\uB4DC \uBAA8\uB4C8: [\uCF54\uB4DC \uBAA8\uB4C8](https://github.com/tuya/TuyaOpen/tree/master/src/tuya_ai_basic)\\n\\n### \uC608\uC81C \uAC1C\uC694\\n\uC608\uC81C \uCF54\uB4DC\uB97C \uC798 \uD65C\uC6A9\uD558\uBA74 \uAC1C\uBC1C \uBE44\uC6A9\uC744 \uC904\uC774\uACE0 \\"\uBC14\uD034\uB97C \uB2E4\uC2DC \uBC1C\uBA85\uD558\uB294 \uC77C\\"\uC744 \uD53C\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n- your chat bot: [\uC774\uB3D9](https://github.com/tuya/TuyaOpen/tree/master/apps/tuya.ai/your_chat_bot)\\n    - T5/ESP32 \uD06C\uB85C\uC2A4 \uD50C\uB7AB\uD3FC \uC9C0\uC6D0 \uC608\uC81C\\n    - \uC74C\uC131 ASR + Tuya Cloud \uB300\uADDC\uBAA8 \uBAA8\uB378\\n    - AI Prompt/Agent \uAE30\uB2A5 \uC5F0\uACB0\\n    - \uAC10\uC815 \uC778\uC2DD \uC0C1\uD638 \uC791\uC6A9 \uAE30\uB2A5\\n    - \uBAA8\uB4C8 \uAD6C\uC131 \uC694\uC18C: `Screen` + `Mic` + `Speaker` + `Wi-Fi` + `Button`\\n\\n- your chat bot: [\uC774\uB3D9](https://github.com/tuya/TuyaOpen/tree/master/apps/tuya.ai/your_chat_bot)    \\n    - T5/ESP32 \uD06C\uB85C\uC2A4 \uD50C\uB7AB\uD3FC \uC9C0\uC6D0 \uC608\uC81C\\n    - \uC74C\uC131 ASR + Tuya Cloud \uB300\uADDC\uBAA8 \uBAA8\uB378\\n    - AI Prompt/Agent \uAE30\uB2A5 \uC5F0\uACB0\\n    - \uAC10\uC815 \uC778\uC2DD \uC0C1\uD638 \uC791\uC6A9 \uAE30\uB2A5\\n    - \uC5EC\uB7EC \uC6E8\uC774\uD06C \uBAA8\uB4DC\\n    - \uC571 \uC81C\uC5B4 \uB85C\uBD07 \uC0C1\uD638 \uC791\uC6A9\\n    - \uAC10\uC815 \uC778\uC2DD \u2192 \uB3D9\uC791 \uAE30\uB2A5\\n    - \uBAA8\uB4C8 \uAD6C\uC131 \uC694\uC18C: `Screen` + `Mic` + `Speaker` + `Wi-Fi` + `Button` + `Servo`\\n- Switch Demo: [\uC774\uB3D9](https://github.com/tuya/TuyaOpen/tree/master/apps/tuya_cloud/switch_demo)\\n     - \uB514\uBC14\uC774\uC2A4\uB97C Tuya Cloud\uC5D0 \uC5F0\uACB0\uD558\uACE0 Tuya Cloud Service/App\uC5D0\uC11C \uC81C\uC5B4\uD560 \uC218 \uC788\uB294 IoT LED \uC870\uBA85\uC758 \uAE30\uBCF8 \uB124\uC774\uD2F0\uBE0C \uC608\uC81C\\n     - DP \uBA54\uC2DC\uC9C0 \uC774\uBCA4\uD2B8 \uCC98\uB9AC\\n     - \uAE30\uBCF8 \uB124\uD2B8\uC6CC\uD06C \uAD6C\uC131 \uBC0F \uD558\uB4DC\uC6E8\uC5B4 \uC778\uC99D \uD504\uB85C\uC138\uC2A4\\n\\n- Basic Component Demo: [\uC774\uB3D9](https://github.com/tuya/TuyaOpen/tree/master/examples)\\n     - Bluetooth/Wi-Fi\\n     - SPI I2C ADC \uAE30\uBCF8 \uC778\uD130\uD398\uC774\uC2A4 \uD504\uB85C\uD1A0\uCF5C \uB370\uBAA8\\n     - \uD504\uB85C\uD1A0\uCF5C \uB370\uBAA8\\n     - \uD654\uBA74 \uB80C\uB354\uB9C1 \uD504\uB808\uC784\uC6CC\uD06C LVGL \uC608\uC81C\\n     \uAE30\uD0C0...\\n\\n\\n## TuyaOS \uC139\uC158\\n\\nTuya Wind IDE\uB294 TuyaOS EasyGo\uB97C \uC0AC\uC6A9\uD558\uB294 \uAC1C\uBC1C\uC790\uB97C \uC704\uD55C \uC6D0\uC2A4\uD1B1 \uD1B5\uD569 \uAC1C\uBC1C \uD658\uACBD\uC785\uB2C8\uB2E4. [\uC774\uB3D9](https://developer.tuya.com/cn/docs/iot-device-dev/tuyaos-wind-ide)\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n### AI \uC778\uD504\uB77C Tuya Wukong AI \uC784\uBCA0\uB514\uB4DC \uB514\uBC14\uC774\uC2A4 \uCE21\\n- Tuya Wukong AI: [\uC774\uB3D9](https://developer.tuya.com/cn/docs/iot-device-dev/ai-hardware?id=Kectwmx9isrgl)\\n- \uAE30\uB2A5 \uB9F5: [\uC774\uB3D9](https://developer.tuya.com/cn/docs/iot-device-dev/wukong-abi-map?id=Keedxu1netj62)\\n- \uBA40\uD2F0\uBAA8\uB2EC \uC0C1\uD638 \uC791\uC6A9: [\uC774\uB3D9](https://developer.tuya.com/cn/docs/iot-device-dev/tuyaos-wukong-capability-multi-media)\\n\\n---\\n\\n## Tuya Cloud \uD50C\uB7AB\uD3FC, \uC81C\uB85C \uCF54\uB4DC \uD074\uB77C\uC6B0\uB4DC AI \uAC1C\uBC1C\\n- Tuya Developer Cloud Service \uB4F1\uB85D: [\uC774\uB3D9](https://auth.tuya.com/register)\\n- \uCC38\uACE0 \uBB38\uC11C:\\n    - [\uC9C0\uB2A5\uD615 Agent \uAC1C\uBC1C \uD50C\uB7AB\uD3FC](https://developer.tuya.com/cn/docs/iot/ai-agent-management)\\n    - [AI\uAC00 \uC9C1\uC811 \uD568\uC218\uB97C \uD638\uCD9C\uD558\uB3C4\uB85D \uD558\uAE30 - \uB514\uBC14\uC774\uC2A4 \uC790\uCCB4 \uC81C\uC5B4 \uBA85\uB839 \uD568\uC218](https://developer.tuya.com/cn/docs/iot/Self-control?id=Kep3yhifdrvah)\\n\\n---\\n\\n# \uD558\uB4DC\uC6E8\uC5B4 \uAC1C\uBC1C \uBCF4\uB4DC\\n## \uAC1C\uBC1C \uBCF4\uB4DC\\n### Tuya T5AI Board \uAC1C\uBC1C \uBCF4\uB4DC\\n![T5-AI Board \uD540 \uBC30\uCE58](https://images.tuyacn.com/fe-static/docs/img/6b7ab959-0635-4293-991b-b8dda293614b.jpg)\\n\\n- \uBB38\uC11C \uC785\uAD6C: [T5AI Board \uAC1C\uC694](/docs/hardware/t5-ai-board/overview-t5-ai-board)\\n- I/O \uD540 \uACE0\uD574\uC0C1\uB3C4 \uB2E4\uC6B4\uB85C\uB4DC: [\uD540 \uBC30\uCE58](/docs/hardware/T5-AI-Board-Pinout-v102.pdf)\\n- \uD504\uB85C\uC81D\uD2B8\uB97C \uBE60\uB974\uAC8C \uCEF4\uD30C\uC77C\uD558\uACE0 \uD50C\uB798\uC2F1\uD558\uB294 \uBC29\uBC95: [\uD29C\uD1A0\uB9AC\uC5BC](/docs/quick-start/enviroment-setup)\\n\\n{/* ### Tuya T5 mini \uAC1C\uBC1C \uBCF4\uB4DC(\uC11C\uB4DC\uD30C\uD2F0 \uCEE4\uBBA4\uB2C8\uD2F0 \uAC1C\uBC1C \uBCF4\uB4DC)\\n\\n- \uD06C\uAE30\uAC00 \uC791\uC544 \uACF5\uAC04 \uC694\uAD6C \uC0AC\uD56D\uC774 \uB192\uC740 \uC194\uB8E8\uC158\uC5D0 \uC801\uD569\uD569\uB2C8\uB2E4.\\n- \uC0AC\uC6A9 \uBC29\uBC95\uC740 [T5AI Board](/blog#%E6%B6%82%E9%B8%A6-t5ai-board-%E5%BC%80%E5%8F%91%E6%9D%BF)\uB97C \uCC38\uC870\uD560 \uC218 \uC788\uC73C\uBA70 \uAE30\uB2A5\uC740 \uBE44\uAD50\uC801 \uC720\uC0AC\uD569\uB2C8\uB2E4.\\n\\n### Digua Robot RDK X5\\n\\n\uCC38\uACE0 \uBB38\uC11C: [RDK X5 \uBB38\uC11C](https://developer.d-robotics.cc/information)\\n\\n#### RDK\uB294 TuyaOpen\uACFC \uC5B4\uB5BB\uAC8C \uD1B5\uD569\uB418\uB098\uC694?\\n\\n> T5\uC758 \uC5F0\uC0B0 \uC131\uB2A5\uB9CC\uC73C\uB85C \uCDA9\uBD84\uD558\uC9C0 \uC54A\uC744\uAE4C \uAC71\uC815\uB418\uB098\uC694? RDK X5\uAC00 \uC5E3\uC9C0 \uCEF4\uD4E8\uD305 \uC694\uAD6C\uB97C \uC9C0\uC6D0\uD558\uB3C4\uB85D \uD558\uC138\uC694! RDK + TuyaOpen \uC194\uB8E8\uC158\uC73C\uB85C \uB85C\uCEEC \uC2E4\uC2DC\uAC04 \uBAA8\uB378 \uCD94\uB860\uACFC \uD074\uB77C\uC6B0\uB4DC \uB300\uADDC\uBAA8 \uBAA8\uB378\uC744 \uACB0\uD569\uD55C \uD558\uC774\uBE0C\uB9AC\uB4DC \uC544\uD0A4\uD14D\uCC98\uB97C \uAD6C\uD604\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n- Tuya \uC571\uC73C\uB85C RDK X5 \uAE30\uB2A5\uC744 \uC6D0\uACA9 \uC81C\uC5B4\uD569\uB2C8\uB2E4.\\n    - RDK + TuyaOpen \uD504\uB808\uC784\uC6CC\uD06C \uC194\uB8E8\uC158 \uB370\uBAA8: [\uD29C\uD1A0\uB9AC\uC5BC](/docs/rdk/rdk-originbot-with-tuya-dp-control-demo.pdf)\\n- RDK X5\uC640 Tuya T5 \uCE69 \uD558\uC774\uBE0C\uB9AC\uB4DC \uD504\uB808\uC784\uC6CC\uD06C\\n    - \uC5E3\uC9C0 \uCEF4\uD4E8\uD305 + \uD074\uB77C\uC6B0\uB4DC \uCEF4\uD4E8\uD305 \uACB0\uD569: [\uD29C\uD1A0\uB9AC\uC5BC](https://diguazhandian-rdkx5-tuya-t4otm0d.gamma.site/) */}\\n\\n---\\n\\n# Tuya \uD558\uB4DC\uC6E8\uC5B4 \uB9AC\uC18C\uC2A4\\n- \uB9AC\uC18C\uC2A4 \uB0A8\uC6A9\uC744 \uBC29\uC9C0\uD558\uAE30 \uC704\uD574 \uB9AC\uC18C\uC2A4\uB97C \uC218\uB839\uD558\uAC70\uB098 \uC0AC\uC6A9\uD560 \uBA85\uD655\uD55C \uC544\uC774\uB514\uC5B4\uAC00 \uC788\uB294 \uD300\uC744 \uC6B0\uC120 \uC9C0\uC6D0\uD569\uB2C8\uB2E4. \uD300\uC774 \uC775\uC219\uD55C \uB3C4\uAD6C\uB97C \uC9C1\uC811 \uC900\uBE44\uD558\uB294 \uAC83\uB3C4 \uAD8C\uC7A5\uD569\uB2C8\uB2E4.\\n- \uAC1C\uBC1C \uBCF4\uB4DC\uB294 \uB300\uD68C\uC5D0\uC11C \uC9C0\uC815\uD55C T5\uB97C \uC0AC\uC6A9\uD574\uC57C \uD569\uB2C8\uB2E4. \uADF8 \uBC16\uC758 \uC8FC\uBCC0 \uC7A5\uCE58, \uD558\uB4DC\uC6E8\uC5B4 \uBC0F \uC81C\uD488 \uD615\uD0DC\uB294 \uCC38\uAC00\uC790\uAC00 \uC790\uC720\uB86D\uAC8C \uC900\uBE44\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n\\n\uD604\uC7A5\uC5D0\uC11C \uC81C\uACF5\uB418\uB294 \uD558\uB4DC\uC6E8\uC5B4 \uB9AC\uC18C\uC2A4\uC758 \uC218\uB7C9\uC740 \uB2E4\uC74C\uC744 \uCC38\uC870\uD558\uC138\uC694.\\n\\n### \uAC1C\uBC1C \uBCF4\uB4DC\\n- [Tuya T5-AI \uAC1C\uBC1C \uBCF4\uB4DC](/docs/hardware/t5-ai-board/overview-t5-ai-board): 15\uAC1C\\n- Tuya T5 mini \uAC1C\uBC1C \uBCF4\uB4DC: 10\uAC1C\\n{/* - Digua Robot RDK X5: 20\uAC1C */}\\n\\n### \uC8FC\uBCC0 \uC7A5\uCE58 \uC561\uC138\uC11C\uB9AC\\n- \uC2A4\uD53C\uCEE4(3020, 4\u03A9, 3W): 20\uAC1C\\n- \uB514\uC2A4\uD50C\uB808\uC774(1.54\uC778\uCE58, ST7789): 10\uAC1C\\n- \uBC30\uD130\uB9AC \uD329(2000mAh): 10\uAC1C\\n- \uC11C\uBCF4(MG90S): 40\uAC1C\\n- \uC13C\uC11C \uD0A4\uD2B8(\uC81C\uC2A4\uCC98, \uD130\uCE58, \uC870\uB3C4, \uACF5\uAE30, \uC628\uC2B5\uB3C4, \uCD08\uC74C\uD30C \uB4F1 10\uC885 \uC774\uC0C1): 4\uAC1C\\n- \uB4C0\uD401 \uC640\uC774\uC5B4/\uB370\uC774\uD130 \uCF00\uC774\uBE14: \uC5EC\uB7EC \uAC1C\\n\\n### \uB3C4\uAD6C\\n\\n- Zhengdian Atom HP15 \uC2A4\uB9C8\uD2B8 \uAC00\uC5F4 \uD50C\uB7AB\uD3FC: 2\uB300\\n- Zhengdian Atom DM40 \uB514\uC9C0\uD138 \uBA40\uD2F0\uBBF8\uD130: 2\uB300\\n- Zhengdian Atom T80/T80P \uC2A4\uB9C8\uD2B8 \uB0A9\uB55C \uC778\uB450: 2\uB300\\n- Zhengdian Atom \uB85C\uC9C1 \uBD84\uC11D\uAE30: 2\uB300\\n- \uC870\uC815\uC2DD DC \uC804\uC6D0 \uACF5\uAE09 \uC7A5\uCE58(\uCD5C\uB300 60V/5A): 1\uB300\\n- \uD788\uD2B8\uAC74: 1\uB300\\n- \uD56B \uAE00\uB8E8\uAC74: 1\uB300\\n- \uB4DC\uB77C\uC774\uBC84 \uC138\uD2B8: 1\uC138\uD2B8\\n- 3D \uD504\uB9B0\uD130(Bambu Lab P1S+AMS): 5\uB300\\n\\n---\\n\\n\\n# Tuya \uAE30\uC220 \uC9C0\uC6D0 \u{1F6E0}\uFE0F\u{1F4CB}\\n\\n\uD589\uC0AC \uD604\uC7A5\uC5D0\uB294 Tuya \uAE30\uC220 \uAC15\uC0AC\uC640 Digua Robot \uAC15\uC0AC\uAC00 \uC0C1\uC8FC\uD574 \uD589\uC0AC \uAE30\uAC04\uC5D0 \uC801\uC808\uD55C \uAE30\uC220 \uC9C0\uC6D0\uC744 \uC81C\uACF5\uD569\uB2C8\uB2E4.\\n\\n:::tip\\n\uB354 \uBCF5\uC7A1\uD55C \uBB38\uC81C\uAC00 \uC788\uAC70\uB098 \uD589\uC0AC \uB2F9\uC77C \uD604\uC7A5\uC5D0\uC11C \uC81C\uB54C \uC9C0\uC6D0\uC744 \uBC1B\uC9C0 \uBABB\uD55C \uACBD\uC6B0 \uC9C8\uBB38\uC744 \uC815\uB9AC\uD574 Github\uC5D0 Issue\uB97C \uB4F1\uB85D\uD558\uC138\uC694 \u{1F4DD}. Tuya\uAC00 \uAC00\uB2A5\uD55C \uD55C \uBE68\uB9AC \uB2F4\uB2F9\uC790\uB97C \uBC30\uC815\uD569\uB2C8\uB2E4.\\n:::\\n\\nIssue \uB9C1\uD06C: https://github.com/tuya/TuyaOpen/issues\\n\\n### Issue \uD615\uC2DD\\n\\n``` shell\\n### Include `\u301052Event\u3011` to help staff identify event issues\\nIssue Title: \u3010AdventureX Event\u3011 (bug/question/hardware): {Clear and concise problem description}\\nIssue Content:\\n- Development Environment: Mac/Win/Linux \u{1F4BB}\\n- Chip Platform: T5/RDK \\n- Problem Description: Clear and concise expression of the problem\\n- Problem Phenomenon: What patterns can be found, what methods have been tried to fix it?\\n- Expected Phenomenon: Expected resolution result\\n- Log Logs: Attaching logs helps staff analyze your problem \\n```\\n\\n---\\n\\n# \uC790\uC8FC \uBB3B\uB294 \uC9C8\uBB38\\n\\n1. ESP32\uB294 \uC5B4\uB5BB\uAC8C \uAC1C\uBC1C\uD558\uB098\uC694?\\n`tos.py` \uB3C4\uAD6C\uB85C \uCEF4\uD30C\uC77C \uBC0F \uD50C\uB798\uC2F1 \uB2E8\uACC4\uB97C \uC644\uB8CC\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uCF54\uB4DC \uD504\uB85C\uC81D\uD2B8\uC5D0 \uC62C\uBC14\uB978 \uBCF4\uB4DC \uC218\uC900 \uAD6C\uC131\uC778 ESPxxx.config\uB97C \uC120\uD0DD\uD558\uC138\uC694. `tos.py`\uC758 `build`\uC640 `flash`\uB294 \uBAA8\uB450 \uD06C\uB85C\uC2A4 \uD50C\uB7AB\uD3FC\uC744 \uC9C0\uC6D0\uD569\uB2C8\uB2E4.\\n2. TuyaOS\uC640 TuyaOpen\uC758 \uCC28\uC774\uB294 \uBB34\uC5C7\uC778\uAC00\uC694?\\n\uC704\uC758 **TuyaOpen\uACFC TuyaOS \uBE44\uAD50** \uC139\uC158\uC5D0 \uC790\uC138\uD55C \uC124\uBA85\uC774 \uC788\uC2B5\uB2C8\uB2E4. **\uBE44\uB514\uC624 AI \uAE30\uB2A5 \uD1B5\uD569** \uB610\uB294 **\uC0C1\uC6A9\uD654 \uC2DC\uB098\uB9AC\uC624**\uAC00 \uD544\uC694\uD558\uB2E4\uBA74 TuyaOS\uB97C \uAD8C\uC7A5\uD558\uACE0, \uADF8 \uC678\uC5D0\uB294 \uB354 \uAC1C\uBC29\uC801\uC778 **TuyaOpen** \uC0DD\uD0DC\uACC4\uB97C \uAD8C\uC7A5\uD569\uB2C8\uB2E4.\\n3. PID\uB780 \uBB34\uC5C7\uC778\uAC00\uC694?\\n\uD558\uB4DC\uC6E8\uC5B4\uC6A9 \uD074\uB77C\uC6B0\uB4DC \uC11C\uBE44\uC2A4\uC640 \uC5F0\uACB0\uB41C Product-ID\uC785\uB2C8\uB2E4. \uD074\uB77C\uC6B0\uB4DC \uC11C\uBE44\uC2A4\uC5D0 \uBC14\uC778\uB529\uB41C \uBC88\uD638\uC785\uB2C8\uB2E4.\\n4. \uC778\uC99D \uCF54\uB4DC\uB780 \uBB34\uC5C7\uC778\uAC00\uC694?\\n\uD558\uB4DC\uC6E8\uC5B4\uAC00 \uD074\uB77C\uC6B0\uB4DC \uC11C\uBE44\uC2A4\uC5D0 \uC811\uADFC\uD560 \uB54C \uD558\uB4DC\uC6E8\uC5B4 \uBCF4\uC548\uC744 \uBCF4\uC7A5\uD558\uB294 \uBCF4\uC548 \uC778\uC99D \uCF54\uB4DC\uC785\uB2C8\uB2E4. UUID/Key\uB294 \uC778\uC99D \uCF54\uB4DC \uD55C \uC138\uD2B8\uC785\uB2C8\uB2E4. TuyaOS\uC640 TuyaOpen\uC758 \uC778\uC99D \uCF54\uB4DC\uB294 \uC11C\uB85C \uD63C\uC6A9\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4. \uAE30\uB2A5\uACFC \uC11C\uBE44\uC2A4\uAC00 \uBE44\uC2B7\uD558\uB354\uB77C\uB3C4 \uC778\uC99D\uC740 \uD638\uD658\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.\\n5. Windows \uC2DC\uC2A4\uD15C\uC5D0\uC11C \uAC1C\uBC1C\uD560 \uC218 \uC788\uB098\uC694?\\n\uC608. \uD604\uC7AC Master \uBA54\uC778 \uBE0C\uB79C\uCE58\uB97C \uC0AC\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n6. MacOS\uC5D0\uC11C \uAC1C\uBC1C\uD560 \uC218 \uC788\uB098\uC694?\\n- \uC608. \uD604\uC7AC Master \uBA54\uC778 \uBE0C\uB79C\uCE58\uB97C \uC0AC\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.\\n- \uBCA0\uD0C0 \uAE30\uB2A5\uC785\uB2C8\uB2E4. Mac x86/ARM \uD658\uACBD\uC5D0\uC11C \uAC1C\uBC1C\uD560 \uC218 \uC788\uC9C0\uB9CC \uC544\uC9C1 \uBC1C\uACAC\uB418\uC9C0 \uC54A\uC740 \uBB38\uC81C\uAC00 \uC788\uC744 \uC218 \uC788\uC2B5\uB2C8\uB2E4. \uBA3C\uC800 Linux\uC640 Windows\uB97C \uC0AC\uC6A9\uD558\uB294 \uAC83\uC774 \uC88B\uC2B5\uB2C8\uB2E4.\\n7. MacOS M \uC2DC\uB9AC\uC988\uC5D0\uC11C T5 \uD504\uB85C\uC81D\uD2B8\uB97C \uCEF4\uD30C\uC77C\uD560 \uB54C lwip \uCEF4\uD30C\uC77C \uC624\uB958\uAC00 \uBC1C\uC0DD\uD569\uB2C8\uB2E4.\\nMac gcc \uBC84\uC804 \uCC28\uC774\uB85C \uC778\uD574 T5 \uCE69\uC744 \uC0AC\uC6A9\uD560 \uB54C \uB2E4\uC74C \uC218\uC815\uC774 \uD544\uC694\uD569\uB2C8\uB2E4.\\n\uBB38\uC81C\uAC00 \uD574\uACB0\uB418\uC5C8\uC2B5\uB2C8\uB2E4."}]}}')}}]);